// 동작: 새 문서를 만들고 국부론의 스타일·견본·부모 페이지를 가져온 뒤, 원고 1~7장과 뒷부속을 흘려 넣는다.
// 결과: 끝나면 요약 창을 띄우고, 전체 기록을 1쪽 왼쪽 대지에 '조판 기록' 글상자로 남긴다.
var ID = (typeof require !== "undefined") ? require("indesign") : null;   // UXP면 indesign 모듈, ExtendScript면 null
var APP = ID ? ID.app : app;
function E(name) { return ID ? ID[name] : eval(name); }   // 열거형 이름 → 값 (UXP/ExtendScript 공통)
var DATA = {"book": [{"key": "ch01", "num": "01", "title": "내가 밟는 땅, 누구의 것일까?", "p": [["본문", "여러분, 햄버거 좋아하나요? 출출할 때 먹는 햄버거 한 입, 정말 최고죠!", ""], ["본문", "저는 햄버거를 정말 좋아해서 일주일에 한 번은 꼭 먹어요. 그중에서도 제가 자주 가는 곳이 있어요. 바로 ‘맥도날드’예요! 이름만 들어도 익숙하죠? 커다란 M자 간판 아래에서 햄버거를 먹으면서 혹시 이런 생각을 해본 적이 있나요? “이 가게가 서 있는 땅과 건물은 누구 것일까?” 이 질문에 맥도날드 사업의 중요한 비밀이 숨어 있답니다.", ""], ["본문", "여러분이 낸 햄버거 값은 어디로 갈까요? 재료비와 직원 월급도 있겠지만, 가게가 있는 자리의 임대료도 빼놓을 수 없어요. 아무리 맛있는 햄버거를 만들어도 손님이 찾아오기 어려운 곳이라면 장사하기 힘들겠죠.", ""], ["본문", "맥도날드 지점 중에는 본사가 직접 운영하는 매장도 있고, 다른 사업자가 운영하는 가맹점도 있어요. 가맹점은 맥도날드의 이름과 운영 방식을 사용하는 대가로 로열티를 내요. 본사가 확보한 땅과 건물을 빌려 쓰면 임대료도 내지요. 본사는 부동산을 직접 소유하기도 하고, 다른 소유자에게 빌린 뒤 가맹점에 다시 빌려주기도 해요. 햄버거를 만드는 일과 가게가 들어설 자리를 마련하는 일이 이어져 있는 거예요.", ""], ["본문", "2024년 맥도날드 본사의 임대료 수입은 약 100억 달러였어요. 전체 매출 약 259억 달러의 약 39%에 해당하는 금액이지요. 햄버거 가게가 서 있는 공간이 회사의 사업에서 얼마나 중요한지 보여주는 숫자예요.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "맥도날드를 세계적인 프랜차이즈로 키운 초대 회장 레이 크록(Ray Kroc)에게는 고민이 있었어요. 가맹점이 늘어나도 맥도날드 형제와 맺은 계약 때문에 크록의 회사에 남는 돈이 아주 적었거든요. 이때 재무를 맡은 해리 소넨본이 새로운 방법을 내놓았어요. 본사가 매장이 들어설 땅과 건물을 사거나 빌려서 확보하고, 그 자리를 가맹점에 다시 빌려주자는 것이었죠. 임대료는 매달 꼬박꼬박 들어오는 안정적인 수입이 되었어요. 가게 자리를 쥔 본사는 가맹점이 맥도날드의 운영 기준을 지키도록 할 힘도 갖게 되었고요. 이렇게 해서 맥도날드는 햄버거 회사이면서, 땅과 건물로도 돈을 버는 회사로 성장했답니다. 맥도날드의 창업 이야기는 영화 파운더(The Founder, 2017)에서 흥미진진하게 볼 수 있어요. 단, 영화의 대사와 장면에는 극적인 재구성이 들어간다는 것은 생각하면서 봐야겠지요?", ""], ["도판 자리", "[도1-1] 손님 → 가맹점: 햄버거 판매대금. 가맹점 → 맥도날드 본사: ① 브랜드·운영 방식 사용의 대가인 로열티 ②…", "1-1"], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "매출은 물건이나 서비스를 팔아 들어온 돈이에요. 여기에서 재료비, 임금, 임차료 같은 비용을 빼야 이익을 알 수 있어요. 따라서 임대료 수입이 크다는 사실만으로 “햄버거보다 부동산에서 더 큰 이익을 냈다”고 단정할 수는 없어요. 숫자를 볼 때는 무엇을 기준으로 나눈 것인지도 살펴야 해요. 여기서 약 39%는 ‘가맹점 수입만’이 아니라 ‘맥도날드 본사의 전체 매출’을 기준으로 계산한 값이에요.", ""], ["본문", "어때요? 햄버거 회사의 사업에 땅과 건물이 이렇게 깊이 연결되어 있다니 신기하죠? 이 이야기처럼 우리가 발을 딛고 서 있는 땅, 잠자는 집, 공부하는 학교, 친구들과 뛰노는 공원에도 우리가 잘 몰랐던 부동산 이야기가 숨어 있어요.", ""], ["본문", "부동산이라고 하면 왠지 어렵고 복잡한 이야기, 또는 돈 많은 사람들만 관심을 갖는 이야기 같나요? 물론 부동산이 돈과 아주 깊은 관련이 있는 것은 사실이에요. 하지만 부동산은 단지 집이나 건물을 사고파는 어른들만의 이야기가 아니에요. 부동산은 우리 삶과 아주 가까이 연결되어 있고, 우리가 살아가는 세상을 이해하는 데 꼭 필요한 열쇠 같은 존재랍니다. 맥도날드 이야기처럼 말이죠!", ""], ["본문", "그렇다면 우리는 왜 부동산을 알아야 할까요? 혹시 나중에 건물을 여러 채 가진 부자가 되기 위해서? 물론 그렇게 된다면 좋겠지만, 부동산 공부는 단순히 돈을 버는 기술을 배우는 게 아니에요. 부동산을 알면 내가 사는 집의 의미, 재산을 지키는 방법, 우리 동네가 왜 지금 모습인지, 사회가 어떻게 돌아가는지를 더 깊이 이해할 수 있어요. 왜냐하면 부동산은 과거와 현재, 그리고 미래까지 우리의 삶과 떼려야 뗄 수 없는 중요한 주제이기 때문이에요.", ""], ["본문", "맥도날드를 부자 회사로 만든 그 ‘부동산’은 도대체 무엇일까요? 우리가 매일 딛고 서 있는 땅에 관한 질문부터 함께 시작해 볼까요?", ""], ["절 제목", "땅은 원래 누구의 것이었을까?", ""], ["본문", "지금은 집이나 학교가 있는 땅의 주인을 서류로 확인할 수 있어요. 하지만 아주 오래전 사람들에게도 지금과 똑같은 서류와 소유권이 있었을까요? 그렇지는 않아요. 그렇다고 모두가 아무 규칙 없이 땅을 썼다고 생각해서도 안 돼요. 이동하며 살던 사람들에게도 함께 쓰는 사냥터나 머물 곳에 관한 관습이 있었을지 모르거든요.", ""], ["본문", "인류학자들은 인류가 농경 생활을 시작하면서부터 땅의 소유 개념이 생겨났을 거라고 이야기해요. 농사를 짓게 되면 무엇이 달라질까요?", ""], ["본문", "씨앗을 뿌리고 작물이 자라기를 기다리는 모습을 떠올려 보세요. 몇 달 동안 가꾼 밭에서 다른 사람이 마음대로 곡식을 가져가면 곤란하겠죠. 그래서 자신이 애써 가꾼 땅 주변에 돌담을 쌓거나 나뭇가지로 울타리를 만들어 '이 땅은 내가 농사짓는 땅이니 다른 사람은 들어오지 마시오!' 하고 표시하기 시작했어요. 바로 땅에 대한 '점유(占有)', 즉 실제로 사용하고 지배한다는 개념이 생겨난 거예요.", ""], ["본문", "이처럼 한곳에 머물러 농사를 짓는 생활이 널리 퍼지면서, 누가 어느 땅을 사용하고 수확을 나눌지 정하는 일이 더욱 중요해졌어요. 땅을 둘러싼 규칙도 지역과 시대에 따라 여러 모습으로 발달했답니다.", ""], ["본문", "어떤 사회에서는 가족이나 공동체가 땅을 함께 쓰고 관리했어요. 어떤 곳에서는 왕이나 지배층, 사원 등이 넓은 땅을 관리했지요. 개인이 땅을 소유하고 사고파는 방식도 있었어요. 전 세계가 하나의 순서를 따라 같은 제도를 만든 것은 아니에요. 그 사회의 생활, 계급과 지위 같은 힘의 관계의 따라 누가 땅을 쓸 수 있는지를 정하는 규칙이 정해졌어요.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "‘소유’는 물건이나 땅을 법적으로 자기 것으로 가지고 있어서, 사용하고 이익을 얻고 처분할 수 있는 권리를 가진 상태를 말해요. ‘점유’는 물건이나 땅을 실제로 지배하며 사용하는 상태를 말해요. 법으로 인정되는 ‘소유권’과 점유는 달라요. 집을 빌려 사는 사람은 그 집을 점유하지만, 그 사실만으로 집의 소유자가 되지는 않아요.", ""], ["절 제목", "땅은 어떻게 사고팔 수 있게 되었을까? : 소유와 거래의 시작, 그리고 부의 축적", ""], ["본문", "농경 사회가 발전하고 인구가 늘어나면서 땅은 점점 더 중요해졌어요. 그러면서 땅마다 다른 조건에도 주목하게 되었지요. 물을 구하기 쉬운 땅, 농사가 잘되는 땅, 물건을 나르기 좋은 땅은 높은 가치를 가지게 되었고요.", ""], ["본문", "필요한 물건을 서로 바꾸어 쓰던 것처럼, 땅도 필요에 따라 다른 물건과 바꾸거나 사람 간에 넘겨주는 일이 생겨났어요. 이런 과정이 반복되면서 '땅을 사고파는 것'이 자연스러워지자, 누가 무엇을 넘겼는지 기록하고, 다툼이 생기면 판단할 규칙을 만드는 일도 중요해졌답니다. 이때부터 나라에서는 땅 주인이 누구인지 적어 놓는 문서, 즉 ‘땅의 주인증명서’ 같은 기록을 만들기 시작했어요. 그리고 땅 주인이 바뀔 때는 공식적인 절차를 통해 소유권을 옮기도록 했죠. 이처럼 거래의 대상이 되었다는 건, 땅이 사람들의 약속과 제도가 만들어낸 '재산'이자 '상품'이 되었음을 보여줍니다.", ""], ["본문", "오늘날의 부동산 거래 역시 땅 자체뿐 아니라 이런 약속과 제도 위에서 이루어지고 있어요.", ""], ["절 제목", "고대 문명 속 땅 거래 : 역사 속 부동산 이야기", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "메소포타미아는 티그리스강과 유프라테스강 사이를 중심으로 한 지역이에요. 오늘날 이라크 일대에 해당하지요. 사람들은 물기 있는 점토에 쐐기 모양의 문자를 눌러 쓴 뒤 말려서 기록을 남겼어요.", ""], ["도판 자리", "[도1-2] 메트로폴리탄 미술관 「부동산 매매 점토판」, 유물 번호 86.11.443. 캡션: 작은 점토판에 남은 옛 부…", "1-2"], ["본문", "미국 메트로폴리탄 미술관에는 기원전 7세기경 메소포타미아에서 만들어진 부동산 매매 점토판이 있어요. 손안에 들어올 만큼 작은 점토판에도 거래의 흔적이 남아 있지요. 종이 계약서나 컴퓨터가 없던 시절에도 사람들은 약속을 기록으로 남겼던 거예요.", ""], ["본문", "기록의 재료는 달라졌지만, “누가 무엇을 약속했는지 나중에도 알 수 있게 하자”는 생각은 지금과 닮았어요. 땅은 오래전부터 생활의 터전인 동시에 재산과 거래의 대상이었답니다. 역사는 그 땅을 모아 큰 부자가 된 사람들의 이야기도 전해 주고 있어요.", ""], ["본문", "수천 년 전 고대 로마에는 ‘부동산’ 하면 빼놓을 수 없는 인물이 있었어요. 바로 마르쿠스 리키니우스 크라수스라는 사람인데요, 기원전 1세기 로마 공화정 시대를 살았던 그는 당시 손꼽히는 부자였다고 해요. 그런데 그가 부자가 된 방법이 좀 놀라워요. 다른 사람의 불행을 이용해 부동산을 모았거든요.", ""], ["본문", "고대 역사가 플루타르코스의 기록에는 크라수스가 건축가와 건축 일을 하는 노예를 500명 넘게 거느렸다고 나와요. 로마에서는 건물이 빽빽하게 들어선 곳에서 불이 나거나 건물이 무너지는 일이 있었어요. 크라수스는 불이 난 건물뿐 아니라 불이 옮겨붙을까 걱정하는 이웃의 건물도 싸게 샀다고 전해져요.", ""], ["본문", "불길이 가까워지는 집의 주인을 상상해 보세요. 평소라면 팔지 않았을 집도 조금이라도 돈을 건질 수 있을 때 서둘러 팔고 싶었을 거예요. 반면 많은 돈과 사람을 가진 크라수스는 그런 건물을 사들일 수 있었지요. 같은 재난 앞에서도 사람들이 가진 선택지는 무척 달랐어요.", ""], ["본문", "이 이야기에서 눈여겨볼 것은 크라수스가 얼마를 벌었느냐만이 아니에요. 위기에 빠진 사람과 그 틈에 재산을 늘릴 수 있는 사람의 차이예요. 당장 살 곳을 잃을까 두려운 사람에게 “싫으면 팔지 않으면 되잖아”라고 말하기는 어렵겠죠.", ""], ["본문", "부동산 거래에는 이렇게 사람들의 형편과 힘의 차이도 얽혀 있어요. 서로 동의한 거래라고 해도 그 과정이 공정했는지 따져 볼 수 있지요. 재난을 막는 시설, 피해자를 돕는 제도, 거래의 규칙이 왜 필요한지 생각하게 하는 이야기예요.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "크라수스의 부동산 이야기로는 “집을 헐값에 넘겨야 소방대가 불을 꺼 주었다”는 일화가 유명한데요. 사실 이 이야기는 옛 기록에 나오지 않아요. 플루타르코스가 전하는 내용은, 크라수스가 불이 잦던 로마에서 불타는 집과 그 옆집을 겁에 질린 주인에게서 싼값에 사들였다는 거예요. 남의 불행을 부동산을 싸게 사는 기회로 삼은 셈이죠. 이런 방식은 오늘날에도 볼 수 있어요. 뉴욕의 일부 건물주들은 세입자를 내보내고 집을 비싸게 팔거나 세를 올리려고 건물을 일부러 망가뜨리곤 했어요. 이런 일이 되풀이되자 뉴욕시는 세입자 괴롭힘을 막는 법까지 만들었답니다.", ""], ["절 제목", "부동산이란 무엇인가? : 움직일 수 없는 재산", ""], ["본문", "학교 운동장을 떠올려 볼까요? 운동장이 있는 땅은 다른 곳으로 들고 갈 수 없어요. 그 옆의 학교 건물도 마찬가지죠. 이제 ‘부동산’이라는 말이 조금 가까워지나요?", ""], ["본문", "부동산(不動産)은 한자 그대로 ‘움직일 수 없는 재산’이라는 뜻이에요. 우리 민법은 토지와 그 정착물을 부동산이라고 해요. ‘정착물’은 건물처럼 땅에 계속 붙어 사용되는 것을 말해요.", ""], ["본문", "두 갈래로 생각하면 쉬워요.", ""], ["본문", "첫째는 운동장 자리와 같은 ‘땅 자체’, 곧 토지예요. 둘째는 학교 건물처럼 그 땅에 붙어 있는 것이에요. 반면 책상이나 자전거처럼 옮길 수 있는 물건은 동산이에요.", ""], ["본문", "담장이나 땅에 뿌리내린 나무처럼 토지와 한몸으로 보는 물건도 있지만, 에어컨처럼 떼어 옮길 수 있는 설비는 설치 방식과 거래 내용에 따라 판단이 달라질 수 있어요. 그래서 실제 계약에서는 ‘무엇이 집에 포함되는지’를 계약서에 구체적으로 적어 두는 것이 중요해요.", ""], ["본문", "한편, 우리나라는 토지와 건물을 서로 독립된 부동산으로 다뤄요. 그래서 땅 주인과 건물 주인이 다를 수 있고, 등기 기록도 따로 만들어요. 외국에는 땅과 건물을 하나로 묶어 다루는 나라도 많아서, 이건 우리나라 부동산을 이해할 때 꼭 기억해야 할 특징이에요.", ""], ["도판 자리", "[도1-3] 〈도해〉 학교 운동장과 학교 건물을 각각 ‘토지’와 ‘건물’로 표시. 옆의 책상·자전거는 ‘동산’으로 묶기.…", "1-3"], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "부동산 시장에서는 “땅은 거짓말하지 않는다”는 격언을 종종 사용하곤 해요. 19세기 미국의 유명한 사업가인 존 제이콥 애스터의 말로 알려져 있는데, 그는 모피 무역으로 큰돈을 번 후 뉴욕의 부동산에 투자하여 엄청난 부를 쌓았다고 해요. 이 말은 주로 어떻게 쓰일까요? 땅이란 변함없이 그곳에 존재하는 것이란 의미도 있지만, 대개는 땅의 가치에 대한 믿음을 표현할 때 사용해요. 그런데 이 말을 땅값이 언제나 오른다는 뜻으로 받아들여서는 안 돼요. 토지는 새로 만들어내기 어렵고 위치를 옮길 수 없지만, 인구와 산업, 재해와 환경, 정책 변화에 따라 가치가 변화될 수 있기 때문이에요. 예를 들어 길이 끊겨 드나들기 어려워지거나 물난리가 잦아지면 땅을 쓰기가 불편해질 수 있어요. 그러니 이런 말을 들으면 “어떤 땅을, 언제를 두고 한 말일까?” 하고 한 번 더 물어보세요.", ""], ["절 제목", "학교, 놀이터, 도로도 누군가의 소유일까? : 우리가 함께 쓰는 공간에도 주인이 있다니!", ""], ["본문", "“우리 집이나 가게에는 주인이 있겠지. 그런데 학교 운동장이나 도로는 누구 땅이지?” 하고 궁금할 수 있어요. 넓은 공원은 누구나 이용하니 주인이 없는 것처럼 느껴지기도 하고요. 하지만 함께 쓰는 공간에도 소유자와 관리자가 있어요. 둘이 같은 경우도 있고 다른 경우도 있답니다.", ""], ["목록", "• 학교: 대부분 나라 또는 지방 자치 단체(시청, 교육청 등)가 소유하고 있어요. 우리가 낸 세금으로 나라나 지방 자치 단체가 땅을 사고 건물을 지어서 학생들이 공부할 수 있도록 만든 거죠. 사립학교는 학교를 세운 재단이 소유하고 있어요.", ""], ["목록", "• 놀이터/공원: 동네 놀이터나 큰 공원은 대부분 구청이나 시청 같은 지방 자치 단체가 시민들이 자유롭게 이용하고 쉴 수 있도록 세금으로 관리하는 땅이에요. 아파트 단지 안에 있는 놀이터는 아파트 주민들이 공동으로 소유하거나 관리하는 경우도 있어요.", ""], ["목록", "• 도로: 차도와 인도는 국가나 지방자치단체가 관리하는 경우가 많아요. 개인 소유의 땅이 길로 쓰이기도 하지요. 누가 땅을 소유하는지와 누가 통행할 수 있는지는 따로 확인해야 할 문제예요.", ""], ["목록", "• 하천과 산: 하천은 국가나 지방자치단체가 관리하는 경우가 많지만, 주변 토지의 소유관계는 구간마다 다를 수 있어요. 우리나라 산림은 오히려 개인이 소유한 사유림의 비중이 큰 편이에요. 국립공원 안의 땅도 모두 국유지는 아니므로 이용 규칙과 소유권을 구분해서 보아야 해요.", ""], ["본문", "공원을 편리하게 이용할 수 있는 까닭은 주인이 있기 때문만은 아니에요. 놀이터 기구가 고장 나면 누가 수리할지, 쓰레기는 누가 치울지, 이용자는 어떤 규칙을 지킬지가 정해져 있기 때문이지요. 우리가 함께 쓰는 공간은 소유자와 관리자, 이용자가 각자의 역할을 맡아 돌보는 곳이에요.", ""], ["절 제목", "신기한 부동산 이야기: 비싼 공간을 비교하려면?", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "‘한 평’은 약 3.3제곱미터로, 가로·세로 약 1.8미터인 정사각형 크기예요. 어른 한 명이 넉넉히 누울 수 있는 공간이죠. 지금은 공식 문서에 제곱미터(㎡)를 쓰지만, 일상생활에서는 여전히 ‘평’이라는 단위가 많이 쓰이고 있어요.", ""], ["본문", "“세계에서 가장 비싼 곳!”이라는 말을 들으면 얼마나 비싼지 궁금해져요. 그런데 땅값과 아파트값을 그냥 비교해도 될까요? 같은 돈으로 살 수 있는 넓이를 비교하려면 먼저 무엇을 재고 있는지 살펴야 해요.", ""], ["본문", "땅은 집을 짓는 데도, 가게나 사무실을 여는 데도, 농사를 짓는 데도 쓰여요. 위치와 쓰임새에 따라 가치가 달라지지요. 집의 가격에는 그 안에서 살 수 있는 공간뿐 아니라 건물의 상태와 그 자리에 관한 가치도 함께 담겨 있어요.", ""], ["본문", "마음대로 아무 건물이나 지을 수 있는 것도 아니에요. 나라와 지방자치단체는 땅을 어떻게 이용할지 계획하고 건축 규칙을 정해요. 그 내용은 5장과 6장에서 다시 만나게 될 거예요.", ""], ["본문", "한 가지 숫자를 볼까요? 부동산 조사 회사 나이트프랭크의 『부자보고서(The Wealth Report) 2025』는 2024년 기준으로 모나코에서 미화 100만 달러로 살 수 있는 고급 주택의 면적을 약 19㎡로 제시했어요. 정사각형이라면 한 변이 약 4.4m인 공간이에요. (단, 이것이 모나코의 모든 집이나 땅의 평균 가격이라는 뜻은 아니랍니다.)", ""], ["본문", "모나코는 프랑스 남쪽 지중해 연안에 있는 작은 나라예요. 집을 지을 공간은 한정되어 있는데 고급 주택을 찾는 수요가 모이면 가격이 높아질 수 있어요. 그렇다고 값이 끝없이 오르는 것은 아니에요. 사려는 사람의 수와 형편이 달라지면 가격도 달라질 수 있지요.", ""], ["본문", "여기서 한 가지 팁! 부동산의 가격을 볼 땐 세 가지 질문을 기억하세요. “무엇의 가격이지?”, “언제 조사했지?”, “넓이와 돈의 단위가 같을까?” 같은 ‘평당 가격’이라도 땅 1평인지 건물 1평인지에 따라 뜻이 달라지거든요.", ""], ["본문", "우리나라에서는 서울 명동의 상업용 토지가 높은 공시지가로 뉴스에 자주 등장해요. 사람들이 많이 오가는 자리는 장사하기에 유리할 수 있거든요. 하지만 명동의 ‘토지 공시지가’와 모나코의 ‘고급 주택 가격’을 나란히 놓고 어느 쪽이 비싼지 순위를 매길 수는 없어요. 비교하는 대상과 가격의 기준이 서로 다르니까요.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "공시지가는 세금과 행정의 기준으로 삼으려고 정부가 정한 가격이에요. 실제로 사고파는 가격인 ‘시세’와는 다르고, 해마다 조사 결과가 바뀌어요. 그래서 “어디가 제일 비싸다”고 말할 때는 반드시 기준 연도를 함께 밝혀야 해요.", ""], ["본문", "이런 이야기를 보면 공간의 가치는 넓이만으로 정해지지 않는다는 걸 알 수 있어요. 어디에 있고 어떻게 쓸 수 있는지, 그곳을 이용하려는 사람이 얼마나 있는지도 중요하지요. 가격표 뒤에 어떤 조건이 있는지 읽어 보는 습관을 길러 보세요.", ""], ["본문", "그럼 이제 궁금해지죠? 이렇게 각각 다른 땅값, 도대체 누가 어떻게 정하는 걸까요?", ""], ["절 제목", "우리 집값이 오르내리는 이유는? : 눈에 보이지 않는 시장의 손", ""], ["본문", "‘집값이 올랐다’, ‘집값이 떨어졌다’, ‘부동산 시장이 과열되었다’, ‘거래가 얼어붙었다’ 같은 뉴스를 자주 듣게 돼요. 왜 우리 집이나 동네의 집값은 자꾸만 변하는 걸까요? 집값은 대체 누가, 어떻게 정하는 걸까요?", ""], ["도판 자리", "[도1-5] 제안 도판", "1-5"], ["본문", "집값은 사려는 사람과 팔려는 사람이 얼마에 거래할지 정하면서 움직여요. 어떤 동네의 집을 사려는 사람이 늘고 팔 집은 적다면 가격이 오를 수 있어요. 반대로 팔려는 집은 많은데 사려는 사람이 적으면 가격이 내려갈 수 있지요. 인기 있는 물건이 모자라거나 재고가 남을 때를 떠올려 보세요. 부동산 시장에서도 ‘수요와 공급’의 관계가 중요하답니다.", ""], ["본문", "집값에 영향을 미치는 요인들은 정말 다양하고 복잡해서 정확히 예측하기 어렵지만, 주요 요인들을 살펴보면 다음과 같아요.", ""], ["목록", "• 수요와 공급: 이게 바로 가장 기본적인 원리예요. 집을 사려는 사람이 많고 팔 집은 적으면 집값은 오르고, 반대면 내려가요. 새 주택이 얼마나 공급되는지, 사람들이 어디로 이사 가는지, 1인 가구가 얼마나 늘어나는지도 모두 수요와 공급에 영향을 줘요.", ""], ["목록", "• 금리: 빌린 돈을 쓰는 대가로 내는 돈이 ‘이자’이고, 빌린 돈에 비해 이자를 얼마나 내는지 나타낸 비율이 ‘금리’예요. 금리가 낮아지면 같은 돈을 빌려도 이자 부담이 줄어요. 집을 사려는 사람이 늘어날 수 있지요. 금리가 높아지면 그 반대의 일이 생길 수 있어요. 물론 금리 하나만으로 집값이 결정되지는 않아요.", ""], ["목록", "• 정부 정책: 정부가 부동산 시장을 안정시키거나 활성화하기 위해 내놓는 정책들도 집값에 큰 영향을 미쳐요. 예를 들어 집을 여러 채 가진 사람에게 세금을 더 많이 물리거나(다주택자 중과세), 집을 살 때 돈을 빌리는 것을 어렵게 하거나(대출 규제), 특정 지역에 건물을 더 많이 짓게 허락하거나(공급 확대) 하는 정책들이 있죠.", ""], ["목록", "• 개발 소식 (호재): 지하철역이 생기고, 큰 도로나 공원, 대형 쇼핑몰 같은 시설이 들어온다는 소식은 그 동네를 더 살기 좋은 곳으로 만들어 줄 거라는 기대감을 줘요. 이런 ‘호재’가 있을 때는 마치 “여기에 보물이 묻혀 있대!”라는 소문처럼, 사람들의 관심이 몰리면서 집값도 함께 오르곤 한답니다.", ""], ["목록", "• 경제 상황: 나라 전체의 경제가 좋으면 사람들의 소득이 늘어나고 집을 살 여유가 생겨서 집값이 오르는 경향이 있어요. 반대로 경제가 나쁘면 집 사기가 어려워지고 이미 가진 집도 팔려고 하면서 집값이 떨어질 수 있죠.", ""], ["목록", "• 사람들의 심리: 사람들이 앞으로 집값이 계속 오를 거라고 기대하면, ‘지금 사지 않으면 늦는다’는 마음에 다들 집을 사려고 몰려들어요. 그러면 실제로 집값이 더 빠르게 오르게 되죠. 이런 마음을 ‘기대 심리’라고 해요. 기대가 기대를 부르는, 일종의 심리 작용인 거예요. 이 기대를 이용해 짧은 기간에 사고팔아 차익만 노리는 것은 ‘투기’라고 하지요. 반대로 집값이 떨어질 것 같다는 불안감이 커지면, ‘더 떨어지기 전에 팔자!’ 하고 매물을 내놓는 사람들이 많아져서 집값이 더 빠르게 하락하기도 해요. 이렇게 집값은 사람들의 기대감이나 불안감 같은 심리적인 요인에도 크게 영향을 받아요. 집은 단순한 상품이 아니라, 사람이 실제로 살아가는 공간이기 때문에 사람들의 감정과 생각이 더욱 복잡하게 얽혀 있답니다.", ""], ["절 제목", "우리나라에서 부동산이 차지하는 자산의 비중", ""], ["본문", "우리나라 사람들이 가진 재산 중에서 집이나 땅 같은 부동산이 얼마나 큰 비중을 차지할까요?", ""], ["본문", "국가데이터처(옛 통계청)의 2025년 가계금융복지조사를 보면, 가구의 평균 자산 가운데 실물자산이 75.8%, 금융자산이 24.2%였어요. 실물자산에는 부동산뿐 아니라 자동차 같은 자산도 포함돼요. (이 숫자는 전국 가구를 조사한 결과이지, 모든 집의 재산 구성이 똑같다는 뜻은 아니에요.)", ""], ["도판 자리", "[도1-4] 〈그래프〉2025년 가계금융복지조사 가구 평균 자산 구성: 실물자산 75.8%, 금융자산 24.2%. 기준 …", "1-4"], ["본문", "집과 땅의 비중이 크면 가격 변화도 가계와 경제에 큰 영향을 줄 수 있어요. 집값이 오르면 소유자의 자산 가치가 커지지만, 처음 집을 사려는 사람은 더 많은 돈을 마련해야 해요. 반대로 집값이 떨어지면 빚을 내서 집을 산 사람의 부담이 커질 수 있지요. 집을 빌리는 사람에게는 보증금과 월세의 변화도 중요해요. 같은 뉴스가 누구에게는 반갑고 누구에게는 걱정스러운 이유예요.", ""], ["본문", "그래서 어른들이 부동산 뉴스에 귀를 기울이고, 정부도 부동산 정책에 많은 신경을 쓰는 거예요. 집과 땅의 문제는 단지 개인만의 문제가 아니라, 우리 모두의 삶과 사회에 깊이 연결된 중요한 사안이기 때문이죠. 결국 부동산을 공부한다는 것은 단순히 돈을 버는 기술을 배우는 것이 아니라, 우리나라의 사회와 경제를 이해하는 데 꼭 필요한 지식을 쌓는 일이에요.", ""], ["절 제목", "생각해 볼 질문", ""], ["번호 목록", "1. 햄버거 가게에서 땅, 건물, 옮길 수 있는 물건을 하나씩 찾아보세요.", ""], ["번호 목록", "2. 맥도날드 가맹점이 본사에 내는 로열티와 임대료는 각각 무엇의 대가인가요?", ""], ["번호 목록", "3. 집값을 알지 못해도 우리 동네의 좋은 점을 소개할 수 있나요? 한 가지를 골라 이야기해 보세요.", ""], ["절 제목", "조금 더 깊게 생각하기", ""], ["질문 제목", "□ 맥도날드 사례를 통해 본 부동산의 경제적 가치", ""], ["본문", "맥도날드 본사 매출의 약 39%가 가맹점에서 받는 임대료라는 점은, 부동산이 사람이 사는 공간일 뿐 아니라 기업의 중요한 사업 모델이 될 수 있다는 사실을 보여줍니다. 이 사례를 바탕으로, 부동산이 갖는 경제적 가치에 대해 여러분은 어떤 생각을 하게 되었나요?", ""], ["질문 제목", "□ 동네마다 다른 집값의 이유와 그 영향", ""], ["본문", "왜 어떤 동네는 집값이 비싸고, 어떤 동네는 저렴할까요? 경제적 조건, 사회적 환경, 정책적 지원 등 여러 요인을 살펴보고, 이 차이가 사람들의 삶에 어떤 영향을 미치는지 가상의 두 동네를 예로 들어 설명해 보세요. 특히 도서관·공원·병원 같은 공공시설이 어디에 있는지, 그 차이를 줄이려면 무엇이 필요할지를 중심으로 생각해 봅시다.", ""], ["질문 제목", "□ '좋은 동네'는 집값으로 결정될까?", ""], ["본문", "집값이 높은 곳을 ‘좋은 동네’라고 여기는 사회 분위기에 대해 비판적으로 생각해 보고, 여러분이 생각하는 진짜 좋은 동네는 어떤 곳인지 써 보세요. 공동체의 따뜻함, 안전한 환경, 자연과의 조화 같은 요소들도 함께 고려해 봅시다.", ""], ["질문 제목", "□ 부동산과 부의 축적, 그리고 사회적 영향", ""], ["본문", "고대 로마의 크라수스, 현대의 부동산 재벌처럼, 부동산은 오랫동안 부를 쌓는 수단이 되어 왔습니다. 이들이 부동산을 통해 어떻게 부를 얻었는지 설명하고, 이렇게 축적된 부가 사회에 어떤 영향을 미치는지도 생각해 봅시다. 그 과정에서 나타날 수 있는 공정성 문제나 윤리적인 고민도 함께 정리해 보세요.", ""]]}, {"key": "ch02", "num": "02", "title": "집에도 주민등록증이 있다고요?", "p": [["본문", "여러분, 주민등록증이 뭔지 알고 있죠? 태어난 날짜, 이름, 얼굴 사진, 사는 곳 같은 정보가 담겨 있어서 ‘이 사람이 누구인지’를 공식적으로 보여주는 아주 중요한 서류예요. 어른들은 주민등록증이나 운전면허증을 가지고 다니고, 여러분도 학생증이나 청소년증을 가지고 있거나 앞으로 갖게 될 거예요. 이런 신분증이 필요한 이유는, 세상에는 나와 이름이나 얼굴이 비슷한 사람이 있을 수도 있고, 내가 누구인지 정확하게 확인해야 할 상황이 생기기 때문이에요. 예를 들어, 은행에서 통장을 만들거나 비행기를 탈 때 “당신이 진짜 그 사람 맞나요?”라는 걸 확인하기 위해 신분증을 보여달라고 하잖아요.", ""], ["본문", "그런데 신기하게도, 집에도 신분증 같은 게 있다는 사실, 알고 있었나요? 사람에게 신분증이 있듯이, 집에도 주인이 누구인지, 어떤 역사가 있는지 같은 중요한 정보들이 기록된 특별한 서류가 있어요. 마치 집의 종합기록부 같은 이 서류의 이름은 바로 등기사항전부증명서랍니다! 어른들은 흔히 ‘등기부등본’이라고 불러요.", ""], ["절 제목", "등기사항전부증명서: 집의 신분증이자 역사책", ""], ["본문", "등기사항전부증명서가 왜 ‘집의 신분증’이라고 불릴까요?", ""], ["본문", "등기사항전부증명서는 나라에서 공식적으로 관리하는 문서예요. 이 서류에는 여러분이 지금 살고 있거나, 앞으로 살게 될 집이나 땅에 대한 중요한 정보들이 꼼꼼히 기록돼 있어요.", ""], ["본문", "서류는 크게 표제부·갑구·을구로 나뉘어요. 이름이 낯설죠? “어떤 부동산인가, 소유자로 누가 적혀 있나, 그 밖에 어떤 권리가 있나”를 찾는 세 칸이라고 생각해 보세요.", ""], ["소제목", "1) 표제부: 집의 첫인상! 집의 외모", ""], ["본문", "표제부에는 땅과 건물의 겉모습 정보가 담겨 있어요. 사람의 주민등록증 앞면처럼, 그 집의 기본적인 정보를 보여줘요. 살펴보면 이런 내용이 들어 있어요.", ""], ["목록", "• 소재지(주소): 집이나 땅이 어디에 있는지 알려줘요. 아파트나 빌라 같은 집합건물은 건물 한 동 전체의 표시와 각 세대의 표시를 나누어 보아요. 계약하려는 동·호수가 맞는지까지 확인해야 해요.", ""], ["목록", "• 지목: 토지의 주된 쓰임새를 나누어 등록한 종류예요. ‘전’은 밭, ‘답’은 논, ‘임야’는 산림 등에 쓰는 이름이에요. ‘대’는 주택·상가 등의 부지와 관련된 지목이지요. 다만 지목이 ‘대’라고 해서 원하는 건물을 모두 지을 수 있는 것은 아니에요. 건축 가능 여부는 용도지역과 다른 규정도 확인해야 해요.", ""], ["목록", "• 면적: 땅과 건물의 크기를 제곱미터(㎡) 단위로 알려줘요.", ""], ["목록", "• 구조와 용도: 철근콘크리트인지 벽돌인지, 주택인지 상가인지 사무실인지가 적혀 있어요.", ""], ["도판 자리", "[도2-1] 〈도해〉 가상의 집합건물 등기사항전부증명서를 펼침면으로 구성. “설명을 위해 주요 칸만 간추린 가상 서류”라…", "2-1"], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "사용승인일(준공일), 위반건축물 여부, 층별 용도처럼 ‘건물의 행정 정보’는 등기사항전부증명서만으로는 알 수 없어요. 이런 내용은 건축물대장을 함께 확인해야 해요. 등기와 건축물대장은 역할이 다른 서류랍니다.", ""], ["본문", "잠깐, 넓이가 다르게 보이나요? 분양 안내문에서 ‘전용면적’은 한 세대가 주로 따로 쓰는 공간, ‘공용면적’은 계단이나 복도처럼 함께 쓰는 공간과 관련돼요. 어떤 면적을 더한 숫자인지에 따라 표시되는 넓이가 달라질 수 있어요. 등기 서류와 광고의 면적을 비교할 때는 같은 범위를 가리키는지 먼저 살펴야 해요.", ""], ["도판 자리", "[도2-2] 〈도해〉 앞의 가상 서류에 나온 새봄빌라 301호를 위에서 내려다본 평면 그림. ① 집 안(방·거실·부엌·화…", "2-2"], ["소제목", "2) 갑구: 소유자로 누가 기록되어 있을까?", ""], ["본문", "갑구에는 이 집의 주인이 누구인지, 주인이 어떻게 바뀌었는지가 순서대로 기록돼 있어요. 이 부분을 보면 집의 ‘소유권 역사’를 알 수 있죠.", ""], ["목록", "• 소유자: 등기상 소유자의 이름과 주소 등을 보여줘요. 계약 상대방의 신분과 대리 권한을 확인할 때 대조하는 중요한 정보예요. 등기에 이름이 있다는 사실과 앞에 앉은 사람이 그 사람인지 확인하는 일은 별개랍니다.", ""], ["목록", "• 등기 원인: 매매, 증여, 상속 등 어떤 이유로 등기했는지 알려줘요. 집을 팔아서 소유자가 바뀐 것인지, 누군가에게 물려준 것인지 읽을 수 있지요.", ""], ["목록", "• 원인일자와 접수일자: 거래 등의 원인이 생긴 날과 등기 신청을 접수한 날은 서로 다를 수 있어요. 서류에 나온 날짜를 모두 ‘집주인이 된 날’로 읽으면 안 돼요.", ""], ["목록", "• 그 밖의 기록: 소유자가 여러 명이면 각자의 지분을 확인할 수 있어요. 압류나 소유권이전청구권가등기처럼 소유권과 관련된 다른 기록도 갑구에서 살펴봐요. 낯선 기록은 뜻을 확인한 뒤 거래를 결정해야 해요.", ""], ["소제목", "3) 을구: 숨겨진 권리관계를 찾아라!", ""], ["본문", "을구는 이 집에 대해 집주인 말고 다른 사람이 가지고 있는 권리를 보여주는 부분이에요. 주로 돈과 관련된 권리, 예를 들어 근저당권이나 전세권 같은 내용이 나오기 때문에 계약 전에 반드시 확인해야 하는 중요한 정보랍니다.", ""], ["목록", "• 근저당권: 돈을 빌려준 쪽이 빚을 돌려받지 못할 때, 담보로 잡은 집을 경매에 넘겨 그 대금에서 우선 변제받을 수 있는 권리예요. 누구의 권리인지와 채권최고액을 확인해야 해요. 집이 곧바로 은행 소유가 되는 것은 아니에요.", ""], ["목록", "• 전세권: 전세금을 지급하고 남의 부동산을 사용하면서, 전세금을 돌려받는 것에 관한 권리도 갖는 제도예요. 집주인과 합의하고 전세권 설정등기를 해야 해요. 흔히 말하는 전세 계약이 모두 전세권으로 등기되는 것은 아니에요.", ""], ["목록", "• 지상권·지역권: 남의 땅에 건물 등을 소유하기 위해 이용하는 권리나, 내 땅의 편익을 위해 다른 땅을 이용하는 권리예요. 다른 사람 땅을 지나갈 수 있는 통로를 정한 경우를 떠올리면 쉬워요.", ""], ["목록", "• 임차권등기: 계약이 끝났는데 보증금을 받지 못한 세입자가 이사해야 할 때 중요한 제도예요. 임차권등기명령을 신청했다는 것만으로 충분하지 않아요. 필요한 등기가 완료되었는지 확인한 뒤 이사해야 기존의 보호를 잃는 일을 피할 수 있어요.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "‘권리관계’는 한 집을 두고 누가 어떤 권리를 갖고 있는지를 말해요. 소유자는 누구인지, 은행이 담보권을 갖고 있는지처럼 여러 사람의 권리가 한 집에 연결되어 있을 수 있어요. 여기서 아주 중요한 점 하나! 근저당권에 적힌 ‘채권최고액’은 은행이 실제로 빌려준 돈이 아니에요. 이자와 비용까지 미리 감안해 담보로 잡아 둔 최대 범위예요. 그러니까 “지금 빚이 얼마 남았는지”는 등기사항전부증명서만으로는 알 수 없답니다.", ""], ["본문", "보통의 주택 임대차는 전세권 등기와 다른 방식으로도 보호받아요. 집을 넘겨받고 주민등록을 갖추는 것, 확정일자를 받는 것 등이 중요하지요. 각각 어떤 역할을 하는지는 다음 장에서 알아볼 거예요.", ""], ["본문", "가등기나 압류처럼 낯선 기록이 있거나 소유자와 계약 상대방이 다르면 혼자 판단하지 말고 법무사, 변호사, 개업공인중개사 등에게 확인해야 해요. 등기사항전부증명서는 중요한 출발점이지만 집의 모든 위험을 보여주는 완전한 안전증명서는 아니에요.", ""], ["절 제목", "꼭 봐야 하는 서류인데, 모든 것을 보장하지는 않는다고요?", ""], ["도판 자리", "[도2-3] 〈도해〉 왼쪽: 등기 서류에서 확인하는 ‘등록된 소유자·권리의 내용’. 오른쪽: 별도로 확인하는 ‘계약 상대…", "2-3"], ["본문", "등기사항전부증명서는 처음 보면 내용이 복잡하고 어렵게 느껴질 수 있어요. 하지만 천천히 하나씩 살펴보면, 부동산 거래에서 정말 중요한 정보들이 담겨 있다는 걸 알 수 있죠. 집을 사거나 전세, 월세 계약을 맺을 때 이 서류를 꼼꼼히 확인하면, 내 소중한 재산을 지키는 데 큰 도움이 돼요. 그래서 부동산 계약을 앞두고 있다면 반드시 미리 열람하고, 꼼꼼히 확인하는 습관이 필요해요. 혹시 이해가 잘 되지 않는 부분이 있다면, 혼자 고민하지 말고 전문가의 도움을 받는 것도 좋은 방법이에요.", ""], ["본문", "그런데 정말 이 서류만 잘 확인하면 부동산 거래에서 문제가 전혀 없을까요?", ""], ["본문", "등기 기록은 소유자만 볼 수 있는 비밀 문서가 아니에요. 다른 사람도 인터넷등기소 등에서 열람할 수 있어요. 부동산의 권리 내용을 밖으로 알리는 것을 ‘공시’라고 해요. 누구의 이름으로 어떤 권리가 등록되어 있는지 거래 전에 살펴볼 수 있게 하는 거죠.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "주소를 정확히 알고 있어야 다른 집의 서류를 보는 실수를 줄일 수 있어요. 특히 비슷한 이름의 건물이나 여러 동·호수가 있는 집은 주의해서 살펴야 해요. 열람한 시점도 확인하세요. 오래전에 발급받은 서류에는 이후의 변화가 반영되지 않아요.", ""], ["본문", "여기서 꼭 기억할 게 있어요. 등기사항전부증명서는 공시력은 있지만, 공신력(公信力)은 없다는 사실이에요.", ""], ["본문", "‘공신력’은 기록을 믿고 거래한 사람의 권리를 일정한 조건에서 보호하는 힘을 말해요. 우리나라 부동산 등기에는 이런 공신력이 인정되지 않아요. 예를 들어 실제 소유자가 아닌 사람의 이름으로 잘못 등기되어 있다면, 그 기록을 믿고 샀다는 이유만으로 소유권을 얻는 것은 아니에요. \"이 집의 주인은 A입니다\"라고 쓰여 있어서 믿고 계약을 했는데, 알고 보니 실제 주인은 B였다면 어떻게 될까요? 이럴 때 \"공식 문서를 믿고 계약했으니 제 책임이 아니에요\"라고 주장해도, 법은 그 사람을 완전히 보호해 주지 않는 거죠.", ""], ["본문", "그래서 등기사항전부증명서는 꼭 확인해야 하지만, 그것만으로 거래의 모든 위험을 알 수 있는 것은 아니에요. 소유자와 계약 상대방이 같은지 신분증으로 확인하고, 건축물대장과 세금 자료, 임대 권한처럼 등기 기록에 모두 나타나지 않는 정보도 함께 살펴야 해요. 등기사항전부증명서만 잘 보면 다 되는 것처럼 말해 놓고, 또 그대로 믿으면 안 된다고 하니 조금 헷갈리죠? 괜찮아요! 왜 그런지, 다음 이야기에서 더 쉽게 예를 들어 설명할게요!", ""], ["절 제목", "사건 속으로: 지워진 기록 뒤에 남아 있던 빚", ""], ["본문", "먼저 ‘말소’라는 말을 알아볼까요? 말소는 등기 기록에서 어떤 내용을 지우는 일이에요. 은행 빚을 갚은 뒤 근저당권 등기를 지우는 경우가 대표적이지요. 하지만 기록이 지워졌다는 것과 빚을 실제로 갚았다는 것은 같은 말이 아니에요. 서류를 위조해 기록을 지웠다면 문제가 생길 수 있어요.", ""], ["본문", "2017년 서울 화곡동의 빌라를 산 부부의 사례를 살펴볼게요. 이 사건은 2022년 대법원에서 결론이 났어요. 집을 산 A씨 부부는 등기 기록에서 남아 있는 근저당권이 없다는 것을 확인했어요. 즉, 이 집을 담보로 빌린 돈이 없다는 것이었죠. 이로 미루어, 은행 같은 채권자가 집을 경매에 넘길 권리를 가지고 있지 않다고 보았어요. 큰돈을 주고 집을 사기 전에 중요한 서류를 살핀 것이죠. 그런데 나중에 전 소유자의 대출 문제가 드러났어요.", ""], ["본문", "보도에 따르면, 이전에 집을 가지고 있던 소유자는 은행 빚을 갚지 않은 채 서류를 위조했고, 그 서류가 등기에 반영되었어요. 부부가 본 것은 단순히 가짜로 출력한 종이가 아니라, 잘못된 내용이 들어간 등기 기록이었어요.", ""], ["본문", "서류 위조 사실을 알게 된 은행은 A 씨 부부에게 “위조로 지워진 근저당권 기록을 원래대로 되살려 달라”며 소송을 걸었어요. 법원도 은행 편을 들어줬죠. 부부가 위조를 전혀 몰랐다는 사실도 결과를 바꾸지 못했어요. 억울한 A 씨는 전 집주인에게 \"은행에 진 빚을 빨리 갚아 달라\"고 요구했지만, 전 주인은 끝내 빚을 갚지 않았어요.", ""], ["본문", "없어진 줄 알았던 근저당권이 되살아나면서, 부부의 집은 전 주인이 갚지 않은 빚의 담보가 되어 버렸어요. 은행은 되살아난 근저당권으로 이 집을 ‘경매’에 넘길 수 있게 되었고, 부부는 어렵게 마련한 집을 잃게 될 처지가 되었어요.", ""], ["도판 자리", "[도2-4] 〈도해〉 화곡동 사례를 네 칸 그림으로 재구성. ‘실제 서류가 아닌 설명용 재구성’임을 표시. ① 전 주인이…", "2-4"], ["본문", "그렇다면 전 집주인은 어떻게 되었을까요? 보도 당시 전 집주인은 비슷한 사기와 문서 위조로 여러 건의 재판을 받고 있었어요. 하지만 가해자를 처벌하는 것과 피해자의 집이나 돈을 되찾아 주는 것은 다른 문제예요. 범죄자가 벌을 받았다고 피해가 저절로 회복되는 것은 아니지요. 이 사건을 볼 때 우리가 함께 기억해야 할 부분이에요.", ""], ["본문", "등기소는 신청된 서류와 법에서 정한 요건을 심사해요. 아무것도 확인하지 않고 기록만 입력하는 곳은 아니에요. 다만 서류를 심사하는 절차만으로 실제 거래와 모든 위조를 밝혀내는 데에는 한계가 있어요. 실제로 돈이 오갔는지, 문서가 진짜인지, 권리 내용이 정확한지까지 등기소가 확인할 수는 없거든요.", ""], ["본문", "이처럼 등기사항전부증명서에 적힌 내용이 항상 진실만을 보여주는 것은 아니에요. 누군가가 나쁜 마음을 먹고 서류를 위조하거나 거짓 정보를 넣는다면, 우리가 그걸 한눈에 알아차리기는 정말 어려운 일이죠. 하지만 너무 겁먹을 필요는 없어요. 가장 중요한 것은, 등기사항전부증명서의 이런 문제를 알고, 부동산 계약을 신중하게 검토하는 것이에요.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "다만 이 이야기를 “그러니까 본인이 조심했어야지”로 끝내서는 안 돼요. 개인이 알아차리기 어려운 위조까지 피해자의 부주의로 돌릴 수는 없으니까요. 등기 제도를 더 안전하게 만들고 피해를 어떻게 구제할지도 우리 사회가 함께 풀어야 할 숙제랍니다.", ""], ["절 제목", "등기사항전부증명서 천재가 되기 위한 꿀팁!", ""], ["본문", "처음부터 어려운 권리를 모두 해석할 필요는 없어요. 어떤 내용을 직접 찾고, 무엇을 질문해야 하는지 아는 것부터 시작해 볼까요?", ""], ["소제목", "❶ 등기사항전부증명서는 꼭! 직접 확인하기", ""], ["본문", "계약할 집의 등기사항전부증명서를 직접 열람해 주소와 동·호수가 맞는지 확인해요. 등기상 소유자의 이름과 계약 상대방의 신분을 대조하지요. 다른 사람이 대신 계약한다면 누구를 대신해 어디까지 계약할 권한이 있는지도 확인해야 해요.", ""], ["소제목", "❷ 근저당권이 말소됐다고 안심하지 말기", ""], ["본문", "등기사항전부증명서에서 근저당권이 말소된 것으로 나와 있더라도, 그게 정상적으로 말소된 것인지 꼼꼼히 확인하는 것이 중요해요. ‘말소사항 포함’으로 발급해서 언제, 어떤 이유로 지워졌는지를 반드시 살펴봐야 해요. 앞에서 봤듯이 위조된 말소 등기를 이용해 사람들을 속이는 부동산 거래 사기도 있기 때문에, 조금이라도 이상하거나 의심스러운 부분이 있다면, 권리 말소를 맡은 법무사나 금융기관이 확인해 줄 수 있는 범위를 문의하고, 필요하면 법률 전문가에게 서류를 보여 주세요. 개인정보 때문에 전화만으로 확인할 수 없는 내용도 있어요.", ""], ["소제목", "❸ 거래 마지막 단계(잔금 지급 직전)에도 반드시 한 번 더 확인!", ""], ["본문", "계약을 맺은 뒤에도 근저당권이 새로 설정되거나 소유자가 바뀌고 압류 기록이 생길 수 있어요. 그래서 잔금을 지급하기 직전에 최신 기록을 다시 확인해요. 세금 체납처럼 등기만으로 모두 알 수 없는 정보는 별도 자료도 살펴야 해요. 새 기록이 보이면 돈부터 보내지 말고 무엇이 달라졌는지 설명을 요청하세요.", ""], ["소제목", "❹ 조금이라도 의심스러운 내용이 보이면, 꼭 전문가에게 물어보기", ""], ["본문", "‘소유권이전청구권가등기(장차 소유권을 넘겨달라고 요구할 권리의 순위를 미리 확보하는 등기)’처럼 길고 낯선 말이 나오면 어떻게 할까요? 단어를 짐작해 넘기기보다 어디에 어떤 내용이 적혀 있는지 보여 주고 질문하는 편이 좋아요.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "등기사항전부증명서를 꼼꼼히 읽고 계약을 도와줄 사람은 누구일까요? 바로 '개업 공인중개사'예요. 개업 공인중개사는 나라에서 치르는 시험에 합격해 자격증을 따고, 사무소를 등록한 전문가예요. 그래서 집의 권리 관계를 설명하고, 계약서를 쓰고, 책임을 지고 도장을 찍을 수 있어요. 공인중개사의 일에 관해서는 5장에서 더 자세히 알아볼 거예요.", ""], ["본문", "이럴 땐 혼자 판단하지 말고 믿을 수 있는 개업공인중개사, 법무사, 변호사 등 전문가에게 꼭 확인을 요청하세요. 잠깐의 확인이 큰 피해를 막아 준답니다.", ""], ["절 제목", "역사 속 등기사항전부증명서 이야기", ""], ["본문", "등기사항전부증명서는 지금은 누구나 인터넷으로 쉽게 확인할 수 있는 문서지만, 예전에는 이렇게 편리한 시스템이 없었어요. 그럼, 옛날 사람들은 어떻게 집이나 땅에 대한 정보를 기록하고 관리했을까요?", ""], ["도판 자리", "[도2-5] 제안 도판", "2-5"], ["소제목", "1) 조선시대의 토지 기록: 양안(量案)과 문기(文記)", ""], ["본문", "조선시대에는 국가가 토지를 측량해 ‘양안’이라는 토지대장을 만들었어요. 땅의 위치와 모양, 등급 등을 적어 세금을 거두는 기초 자료로 삼았지요. 오늘날의 등기와 똑같은 제도는 아니지만, 땅에 관한 정보를 기록하고 관리했다는 점에서 함께 살펴볼 만해요. [2-3]", ""], ["본문", "사람들이 땅을 사고팔거나 물려줄 때는 ‘문기’라는 문서도 남겼어요. 무엇을 누구에게 어떤 조건으로 넘겼는지 적어 두는 것이었지요. 국가가 토지 정보를 모은 장부와 사람들이 거래의 근거로 간직한 문서는 용도가 서로 달랐어요.", ""], ["소제목", "2) 종이 기록에서 법률에 따른 등기로", ""], ["본문", "근대에 들어서며 부동산 거래를 확인하고 기록하는 법과 절차도 바뀌었어요. 일제강점기에는 조선부동산등기령에 따른 등기 제도가 시행되었지요. 일제강점기라는 시대적 배경 속에서 도입된 등기 제도는 식민 통치의 수단으로 활용되기도 했지만, 동시에 근대적인 법률 시스템의 도입이라는 측면에서 이후 우리나라 등기 제도에 중요한 토대가 되었어요. 이 시기의 기록은 식민 통치와 토지 제도의 변화라는 역사적 배경 속에서 살펴볼 필요가 있겠죠.", ""], ["소제목", "3) 광복 이후와 전산화", ""], ["본문", "대한민국의 부동산등기법은 1960년에 제정되었어요. 이후 거래가 늘고 기록이 쌓이면서 보관과 열람 방식도 달라졌지요. 수많은 종이 장부에서 원하는 집의 기록을 찾아야 한다고 생각해 보세요. 필요한 정보를 빠르고 정확하게 찾는 일이 큰 과제였겠죠.", ""], ["본문", "대법원은 1992년 등기 전산화 사업을 시작해 2002년에 전국의 등기부 전산화를 마쳤어요. 종이 기록을 찾아보던 일을 컴퓨터로 처리할 수 있게 된 거예요. 지금 우리가 인터넷으로 등기 정보를 확인하는 데에도 이런 변화가 바탕이 되었어요.", ""], ["소제목", "4) 현재 그리고 미래: 더욱 안전하고 편리한 등기 시스템을 향하여", ""], ["본문", "앞으로 기록을 더 안전하게 보관하고 위조를 발견하는 기술은 계속 발전할 거예요. 다만 기술이 좋아지는 것과 기록할 내용이 처음부터 사실인지 확인하는 일은 같지 않아요. 편리한 시스템과 정확한 심사가 함께 필요해요.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "블록체인은 여러 참여자가 기록을 공유하고, 기록을 뒤에서 함부로 바꾸기 어렵게 만드는 기술이에요. 하지만 처음부터 거짓 정보를 넣었다면 그 정보가 사실로 바뀌지는 않아요. 정보를 입력하기 전에 확인하는 과정도 중요해요.", ""], ["본문", "등기 기록을 보면 한 집의 소유자가 바뀌고 여러 권리가 생기고 사라진 흔적을 읽을 수 있어요. 오래된 사진첩처럼 집이 지나온 시간을 보여주는 셈이지요. 다만 그 사진첩 밖에 어떤 사정이 있는지도 함께 물어봐야 한답니다.", ""], ["절 제목", "내 권리가 궁금할 때, 혼자 고민하지 않기", ""], ["본문", "“권리 위에 잠자는 자는 법의 보호를 받지 못한다.”", ""], ["본문", "이 말은 흔히 독일의 법학자 루돌프 폰 예링(Rudolf von Jhering)의 『권리를 위한 투쟁』과 함께 소개되지만, 뿌리는 로마법에서 이어져 온 오래된 법 격언이에요. 예링은 이 책에서 자기 권리를 주장하는 일이 자신과 사회를 위한 의무라고 강조했어요.", ""], ["본문", "이 말은 부동산을 포함한 모든 권리문제에서 정말 중요한 원칙이에요. 권리를 지키려면 정해진 기간 안에 신청하거나 이의를 제기해야 하는 경우가 있어요. 예를 들어 보증금을 돌려받지 못한 세입자가 임차권등기를 마치기 전에 이사하면, 그동안 누리던 보호를 잃을 수 있어요. 그래서 문제가 생기면 미루지 말고 어떤 절차가 필요한지 알아보는 것이 좋아요. 물론, 특히 어려운 서류나 위조를 개인이 모두 알아내기는 힘들어요. 질문하고 도움을 받을 수 있는 기관, 제대로 설명할 의무, 잘못을 바로잡는 절차가 함께 있어야 해요. 권리를 지키는 일은 개인의 노력과 사회의 제도가 만나는 일이랍니다.", ""], ["본문", "“권리는 알고, 묻고, 제때 행사할 때 지켜진다.”", ""], ["본문", "그러므로 부동산을 계약할 때는 등기사항전부증명서를 꼼꼼히 확인하고, 의심스러운 부분이 있다면 반드시 질문하고 점검해야 해요. 문제가 생기면 미루지 말고 도움을 요청해요. 권리는 가지고만 있는 게 아니라, 스스로 행사해야 진짜 내 것이 되기 때문이에요. 다만 앞에서 본 화곡동의 부부처럼, 확인을 다 하고도 피해를 입는 일도 있어요. 그럴 때 필요한 것은 피해자를 탓하는 말이 아니라 피해를 바로잡는 제도랍니다.", ""], ["본문", "부동산은 단순한 물건이 아니라 우리가 살아가는 삶의 터전이자 소중한 자산이에요. “이건 제 권리 아닌가요?” 하고 묻는 것을 두려워하지 마세요. 그리고 “무엇이 달라졌나요?”, “이 기록은 어떤 뜻인가요?”, “누구에게 도움을 요청하면 좋을까요?” 이 세 질문을 기억해 두세요.", ""], ["본문", "이 격언은 책에만 나오는 어려운 말이 아니라, 권리를 제때 행사하라는 중요한 원칙이에요.", ""], ["절 제목", "생각해 볼 질문", ""], ["번호 목록", "1. 앞의 가상 서류에서 주소, 소유자, 채권최고액을 찾아보세요.", ""], ["번호 목록", "2. 그 서류만으로는 은행 빚이 현재 얼마 남았는지 알 수 있을까요? 본문에서 근거를 찾아보세요.", ""], ["번호 목록", "3. 계약 당일 서류와 잔금 지급 전 서류가 다르다면 누구에게 무엇을 물어볼지 한 문장으로 적어보세요.", ""], ["절 제목", "조금 더 깊게 생각하기", ""], ["질문 제목", "□ 개인의 주의 vs 국가의 책임: 등기 제도의 신뢰를 지키는 주체는 누구일까요?", ""], ["본문", "부동산 등기 제도의 신뢰성을 높이기 위해 개인의 주의와 국가의 책임 중 어느 쪽이 더 중요하다고 생각하나요? 그 이유를 설명하고, 국가가 등기 제도를 더 안전하고 믿을 수 있게 만들기 위해 어떤 역할을 해야 하는지도 함께 써 보세요.", ""], ["질문 제목", "□ 블록체인 기술과 미래의 등기 제도", ""], ["본문", "등기부 위·변조 같은 범죄를 막기 위해 블록체인처럼 위조가 어려운 기술을 활용한다면, 어떤 점이 달라질 수 있을까요? 또 앞으로의 부동산 등기 제도가 어떤 방향으로 발전해야 사람들이 자신의 권리를 더욱 안전하게 보호받을 수 있을지, 앞에서 배운 내용을 바탕으로 종합해 여러분의 생각을 제안해 보세요.", ""], ["질문 제목", "□ 부동산 권리에 대한 무관심이 부르는 위험", ""], ["본문", "개인이 자신의 부동산 권리에 관심을 기울이지 않으면 어떤 위험이나 피해가 생길 수 있을까요? 실제 사례나 앞서 살펴본 이야기들을 참고해, 구체적인 예시와 함께 설명해 보세요.", ""], ["질문 제목", "□ 조선 시대의 토지 기록과 오늘날의 등기 제도 비교", ""], ["본문", "조선 시대에는 ‘양안’과 ‘문기’라는 방식으로 토지 소유를 기록했어요. 이러한 방식은 오늘날의 등기 제도와 어떤 점에서 차이가 있었고, 시간이 흐르면서 어떤 발전이 이루어졌는지 서술해 보세요.", ""]]}, {"key": "ch03", "num": "03", "title": "보증금의 정체는 무엇?", "p": [["본문", "여러분, 무더운 여름날 친구들이나 가족과 함께 워터파크에 가본 적 있나요? 파도풀에서 놀고, 짜릿한 슬라이드를 타며 신나게 놀았던 기억이 떠오르죠. 그런데 혹시, 워터파크에서 구명조끼를 빌릴 때 돈을 맡겼던 일도 기억나나요? 나중에 구명조끼를 잘 반납하면, 맡겼던 돈을 그대로 돌려받을 수 있었을 거예요.", ""], ["본문", "관광지에서 자전거를 빌릴 때도 대여료와 별도로 보증금을 맡기는 곳이 있어요. 대여료는 자전거를 타는 대가이고, 보증금은 약속대로 반납했을 때 돌려받는 돈이에요. 둘 다 처음에 내더라도 역할은 다르답니다.", ""], ["본문", "그런데 가만히 생각해 볼까요? 왜 물건을 빌릴 때 요금도 내고, 또 따로 돈을 맡기라고 할까요? 그 이유는 혹시라도 우리가 빌린 물건을 망가뜨리거나 잃어버리거나, 심지어 나쁜 마음을 먹고 가져가 버릴 수도 있기 때문이에요. 만약 그런 일이 생기면, 미리 받아둔 보증금으로 그 손해를 어느 정도 막을 수 있겠죠. 일종의 안전장치로 작용하는 거죠.", ""], ["본문", "이렇게 약속을 지키지 않거나 손해가 생기는 경우에 대비해 미리 맡기는 돈을 ‘보증금’이라고 해요. 집이나 가게를 빌릴 때도 보증금을 맡기는 일이 많아요. 집의 보증금은 액수가 커서, 돌려받지 못하면 다음에 살 곳을 마련하는 데까지 어려움이 생길 수 있어요.", ""], ["본문", "“보증금을 올려달라고 하는데 어떡하지?”,", ""], ["본문", "“이번에 계약 끝나면 보증금은 잘 받을 수 있을까?”,", ""], ["본문", "“뉴스에서 전세사기로 보증금 다 날렸다는 사람 봤어. 정말 무섭더라.”", ""], ["본문", "이처럼 보증금은 단순히 물건을 맡기고 돌려받는 문제를 넘어서, 삶의 터전과 재산을 지키는 문제와도 연결되어 있어요. 오늘은 우리가 살아가는 데 꼭 필요한 집을 빌릴 때 내는 보증금에 대해, 왜 필요한지, 어떻게 쓰이는지, 어떤 위험이 있는지를 하나씩 알아보려고 해요. 앞으로 여러분이 직접 세상을 살아가면서 반드시 알아야 할 중요한 이야기랍니다.", ""], ["절 제목", "전세 vs 월세: 집을 빌리는 두 가지 방식", ""], ["본문", "다른 사람의 집이나 방을 빌려 사는 방법으로 전세와 월세가 있어요. 월세는 여러 나라에서 널리 쓰이고, 큰 보증금을 맡기는 전세는 우리나라에서 특히 발달했어요. 두 방식 모두 집을 빌리는 방법이지만 돈을 내고 돌려받는 방식이 달라요.", ""], ["소소제목", "월세", ""], ["본문", "월세는 집주인에게 매달 정해진 돈을 내는 방식이에요. 예를 들어 한 달에 50만 원을 내기로 했다면 계약 기간 동안 매달 그 돈을 지급해요. 보증금을 따로 맡기는 계약도 많아요. 금액은 집과 계약 조건에 따라 달라지지요. 계약이 끝나면 밀린 월세나 세입자가 책임져야 할 손해 등을 정산하고 남은 보증금을 돌려받아요. 정상적으로 살면서 낡은 부분까지 모두 세입자가 물어내는 것은 아니에요.", ""], ["소소제목", "전세", ""], ["본문", "월세처럼 매달 돈을 내는 대신, 처음에 집값의 상당 부분에 해당하는 아주 큰 돈, 바로 전세 보증금을 집주인에게 맡기는 방식이에요. 예를 들어 집값이 3억 원인 아파트의 전세 보증금이 1억 8천만 원이라면, 세입자는 집주인에게 1억 8천만 원을 맡기고 계약 기간(보통 2년) 동안 따로 월세를 내지 않고 그 집에서 살 수 있어요.", ""], ["본문", "계약이 끝나면 집을 돌려주는 것과 보증금을 반환받는 일을 정산해요. 월세를 내지 않는다고 주거 비용이 전혀 없는 것은 아니에요. 보증금을 대출로 마련했다면 이자가 나가고, 자기 돈이라면 그동안 다른 곳에 쓰거나 저축할 수 없지요. 관리비와 보증료 등도 따져야 해요.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "주택임대차보호법은 원칙적으로 2년의 임대차 기간을 보호하고, 세입자가 한 번 계약갱신을 요구할 수 있도록 해요. 갱신요구권을 행사해 연장되는 기간은 2년이에요. 다만 법에서 정한 거절 사유도 있어요. “최대 4년만 살 수 있다”는 뜻은 아니에요. 서로 합의해 그 뒤에도 계속 살 수 있답니다.", ""], ["도판 자리", "[도3-1] 〈도해〉 2년 계약 사. 월세: 계약 때 보증금 지급 → 매달 월세 지급 → 종료 때 보증금 정산·반환. 전…", "3-1"], ["절 제목", "전세 보증금, 내 돈은 어디에 있을까?", ""], ["본문", "집주인은 보증금을 그대로 따로 보관할까요? 꼭 그렇지는 않아요. 예금에 넣거나 대출을 갚고, 사업 자금이나 다른 집을 사는 돈으로 쓰기도 해요. 세입자는 그 돈을 돌려받을 권리를 갖지만, 내 보증금이 별도 금고에 그대로 남아 있는 것은 아닐 수 있어요.", ""], ["본문", "앞서, 전세는 매달 돈을 받는 대신, 큰 금액의 보증금을 보관하는 것이라고 했어요. 집주인이 이렇게 하는 이유는 뭘까요? 대부분의 경우, 큰돈을 계약 기간 동안 활용할 수 있기 때문이에요. 금리가 높고 낮음에 따라 그 돈을 활용하는 이점도 달라지겠죠.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "금리의 효과를 가상의 예로 볼까요? 1억 원을 연 5% 예금에 넣으면 1년 이자는 세금을 빼기 전 500만 원이에요. 연 2%라면 200만 원이지요. 같은 1억 원이라도 금리에 따라 이자 수입이 달라져요.", ""], ["본문", "보증금을 보태 집을 사기도 해요. 예를 들어 집값이 2억 원이고 전세 보증금이 1억 8천만 원이라면 차이는 2천만 원이에요. 이 차이를 뜻하는 영어 ‘갭’을 써서 흔히 ‘갭투자’라고 부르지요. 그러나 집주인은 나중에 보증금 1억 8천만 원을 돌려줘야 해요. 적은 자기 돈으로 샀다는 말이 돌려줄 책임까지 작다는 뜻은 아니에요.", ""], ["도판 자리", "[도3-2] 〈도해〉 설명용 가정: 집값 2억 원 \\= 집주인 자기 돈 2천만 원 + 세입자 보증금 1억 8천만 원. 별…", "3-2"], ["본문", "집주인이 돈을 어디에 썼든 보증금을 반환할 의무는 남아요. 그런데 투자가 실패하거나 집값이 떨어져 당장 돌려줄 돈이 부족해질 수 있지요. 세입자가 “다음 집으로 이사해야 하니 보증금을 돌려주세요”라고 했을 때 “지금은 돈이 없어요”라는 답을 듣게 되는 거예요. 돌려받을 권리가 있다는 것과 제때 돌려받는 것은 다른 문제랍니다.", ""], ["본문", "보증금을 돌려받지 못했다고 모든 일이 곧바로 사기죄가 되는 것은 아니에요. 처음부터 속여 돈을 받았는지 등 구체적인 사정을 따져야 해요. 하지만 사기죄가 성립하는지와 별개로, 보증금을 받지 못하면 세입자는 큰 어려움을 겪게 되지요.", ""], ["본문", "계약 중에 집주인이 바뀌는 경우도 있어요. 법에서 정한 대항력을 갖춘 세입자라면 새 소유자가 임대인의 지위와 보증금 반환 의무를 이어받는 것이 원칙이에요. 대항력이 무엇인지는 잠시 뒤 살펴볼게요.", ""], ["본문", "보증금 문제를 이해하려면 어떤 위험이 어디에서 생기는지 나누어 보는 것이 좋아요. 먼저 보증금을 받아 집을 사는 수법과, 계약 상대방을 속이는 수법을 살펴볼까요?", ""], ["절 제목", "사건 속으로: 같은 보증금, 서로 다른 위험", ""], ["본문", "아래 사건에는 집값을 부풀리거나 서로 다른 계약서를 만드는 수법이 등장해요. 피해자가 무엇을 믿고 계약했는지, 어떤 정보가 가려져 있었는지에 주목해 보세요.", ""], ["소제목", "1) 보증금이 있었는데, 없어졌어요?! : 깡통전세", ""], ["본문", "‘깡통전세’는 집을 처분해도 보증금을 온전히 돌려주기 어려운 상태를 가리키는 말이에요. 집값이 떨어지거나 보증금과 앞선 빚이 너무 크면 이런 문제가 생길 수 있지요. 여기에 집값을 속이거나 보증금을 돌려줄 능력이 없는 사람을 집주인으로 내세워 돈을 받는 사기가 겹치기도 해요.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "집값이 2억 원이고 보증금이 1억 5천만 원이면 무조건 안전할까요? 실제로 얼마에 팔릴지, 그 돈에서 누구에게 먼저 갚아야 할지에 따라 결과가 달라져요. 비율 하나가 모든 집의 안전선을 정해 주지는 않아요.", ""], ["도판 자리", "[도3-3] 가상 사례: 예상 집값 2억 원 → 경매에서 1억 6천만 원에 매각 → 먼저 갚을 은행 채무 2천만 원 → …", "3-3"], ["본문", "2025년 JTBC는 울산경찰청이 서울·인천 등 수도권 빌라 53채의 전세 보증금 약 115억 원을 가로챈 혐의로 일당을 검거했다고 보도했어요. 경찰 수사 내용에 따르면, 세입자의 보증금으로 집을 사고 이름을 빌려준 사람을 소유자로 내세우는 수법이 쓰였어요. (여기서 ‘검거’는 수사 단계의 사실이며, 최종 판결과는 구별해야 해요.)", ""], ["본문", "어떻게 돈이 남는지 가상의 숫자로 살펴볼게요. 2억 5천만 원에 살 수 있는 집의 보증금을 3억 원으로 정하고 그 돈을 받아요. 2억 5천만 원으로 집값을 치르고 남은 5천만 원을 관련자들이 나누어 가지면, 집주인에게는 세입자에게 돌려줘야 할 3억 원의 책임이 남지요. 집을 2억 5천만 원에 팔아도 보증금에는 못 미쳐요.", ""], ["본문", "보도는 중개인의 가담과 부풀린 감정평가 문제도 전했어요. 세입자가 확인하는 집값과 설명 자체가 왜곡될 수 있었던 거예요. 그래서 여러 자료를 대조하는 일과 함께, 정보를 제공하고 거래를 돕는 사람들의 책임을 묻는 제도도 중요해요.", ""], ["소제목", "2) 하나의 집, 두 개의 계약서? : 이중계약 사기", ""], ["본문", "이중계약 사기 중에는 집주인에게 받은 권한과 다른 내용으로 세입자와 계약하고 돈을 가로채는 수법이 있어요. 집주인과 세입자가 같은 약속을 했다고 생각했는데 서로 다른 계약서를 갖고 있는 거예요.", ""], ["도판 자리", "[도3-7] 제안 도판", "3-7"], ["본문", "예를 들어 집주인에게는 월세 세입자를 구해 주겠다고 하고, 세입자에게는 전세 계약을 제안해요. 세입자에게 받은 큰 보증금은 가로채고 집주인에게 월세만 보내면 한동안 속임수가 드러나지 않을 수도 있어요. 계약서를 두 장 썼다는 것 자체가 범죄라는 뜻은 아니에요. 누구에게 어떤 권한을 받고 무슨 내용으로 계약했는지가 핵심이에요.", ""], ["본문", "어느 경제 매체가 전한 인터뷰에는 수원에서 전세로 살던 한 직장인의 경험이 나와요. 2016년, 빌라 복도에 특정 중개사와 계약한 세입자는 계약서를 가지고 연락해 달라는 벽보가 붙었어요. 세입자가 집주인을 찾아가 서류를 비교하자, 자신의 서류에는 전세가, 집주인의 서류에는 월세가 적혀 있었어요.", ""], ["본문", "인터뷰에 따르면 중개사는 세입자에게 받은 전세 보증금을 가져가고 집주인에게는 매달 월세를 보냈어요. 서로 다른 계약을 믿는 두 사람 사이에서 돈의 흐름을 가렸던 거예요. 세입자는 다른 피해자들과 함께 상담을 받고 소송을 진행했어요.", ""], ["본문", "사연자는 약 2년 6개월이 지나 보증금 3,300만 원을 돌려받았다고 밝혔어요. 임대인이 중개사에게 어떤 계약 권한을 맡겼는지에 관한 진술과 보관해 둔 서류가 중요한 근거였다고 해요. 다만 다른 피해자들의 결과까지 모두 같지는 않았어요. 비슷해 보이는 사건도 맡긴 권한과 증거에 따라 판단이 달라질 수 있답니다.", ""], ["소제목", "3) 누가 빌려줄 권한이 있을까? : 신탁된 집", ""], ["본문", "부동산 사기 중에는 ‘집주인’이라고 믿었던 사람이 사실상 그 집의 진짜 소유자가 아닌 경우도 있어요. 그중 하나가 바로 신탁부동산 사기예요. ‘신탁’은 재산을 정해진 목적에 따라 관리하거나 처분하도록 맡기는 제도예요. 맡기는 사람을 ‘위탁자’, 맡아 관리하는 사람이나 회사를 ‘수탁자’라고 해요. 부동산의 소유권을 수탁자에게 넘겨 신탁등기를 했다면 등기에 수탁자가 소유자로 나타나요.", ""], ["본문", "신탁회사는 수탁자 역할을 하는 회사예요. 정해진 신탁 내용에 따라 부동산을 관리하거나 처분해요. 원래 집주인이 계속 건물을 드나든다는 이유만으로 마음대로 임대할 수 있는 것은 아니에요.", ""], ["본문", "이때 중요한 질문은 두 가지예요. “등기에 소유자로 누가 적혀 있지?”, “이 집을 빌려줄 권한은 누구에게 있지?”", ""], ["본문", "그 답을 찾으려면 신탁의 내용이 적힌 ‘신탁원부’를 함께 봐야 해요. 원래 집주인이 임대할 권한을 갖는지, 수탁자 등의 동의가 필요한지, 보증금을 누구에게 지급해야 하는지는 신탁 내용에 따라 확인해야 해요. (신탁된 집에 모두 같은 조건이 적용되는 것은 아닙니다.)", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "신탁재산에서 이익을 받을 사람을 ‘수익자’라고 해요. 담보신탁에서는 돈을 빌려준 은행 등이 정해진 범위에서 먼저 지급받는 ‘우선수익자’가 되기도 해요. 이 말만 보고 세입자와 은행의 모든 순서를 정할 수는 없어요. 신탁 내용과 계약 권한을 함께 확인해야 해요.", ""], ["본문", "권한이 없는 위탁자에게 보증금을 주고 계약하면, 수탁자인 신탁회사나 새 소유자에게 그 집에 살 권리를 주장하기 어려울 수 있어요. 그렇다고 보증금을 받은 사람과 맺은 계약이 당사자 사이에서도 무조건 없던 일이 된다는 뜻은 아니에요. 보증금 반환 문제와 그 집에서 계속 살 수 있는 문제를 나누어 보아야 해요.", ""], ["본문", "2024년 대구 침산동 신탁 전세사기 사건의 1심 재판에서 임대인에게 징역 5년이 선고되었어요. 보도에 따르면, 신탁회사에 소유권을 넘긴 뒤에도 17가구와 임대차 계약을 맺어 약 15억 5천만 원의 보증금을 받았다고 해요. 피해자들은 보증금을 돌려받지 못한 채 집에서 쫓겨날까 봐 오랫동안 걱정했어요. 그러다 2024년 법이 바뀌어 이런 신탁 사기 피해도 지원 대상이 되었고, 2025년에는 한국토지주택공사(LH)가 이 건물의 피해 주택을 사들여 보증금 일부를 돌려주는 절차에 나섰어요.", ""], ["본문", "계약 상대방이 “제가 원래 집주인이에요”라고 말하는 것만으로는 충분하지 않아요. 신탁등기 표시가 있다면 신탁원부를 보여 주며 임대 권한과 필요한 동의 서류를 설명해 달라고 요청해야 하죠.", ""], ["본문", "어려운 신탁 내용을 처음 집을 구하는 사람이 혼자 해석하기는 힘들어요. 거래를 멈추고 전문가의 설명을 받는 것이 도움이 돼요. 중개인과 관련 기관이 위험과 권한을 분명하게 알려 주는 일도 필요하답니다.", ""], ["도판 자리", "[도3-4] 〈도해〉 위탁자: 재산을 맡기는 사람 → 수탁자: 신탁 내용에 따라 관리하는 사람·회사. 별도 가지에 수익자…", "3-4"], ["소제목", "4) 겉모습과 서류가 다른 집 : 건축물대장 확인하기", ""], ["본문", "방과 부엌이 있다고 모두 적법한 주택인 것은 아니에요. 사무실이나 가게로 허가받은 공간을 허가 없이 주거용으로 바꾸거나, 옥상에 무단으로 방을 만든 경우도 있어요. 이런 사실을 숨긴 채 정상적인 주택이라고 설명하면 계약하는 사람이 중요한 정보를 놓치게 돼요.", ""], ["본문", "위반한 부분을 고치거나 철거해야 할 수 있고, 대출이나 보증 가입에도 제한이 생길 수 있어요. 건물의 안전과 거주를 계속할 수 있는지도 문제예요. 그렇다고 위반건축물의 세입자가 주택임대차보호법의 보호를 전혀 받지 못하는 것은 아니에요. 법 적용은 실제 주거용으로 쓰이는지 등 구체적인 사정을 따져 판단해요. 건축법상 적법성, 임대차 보호, 보증 가입은 서로 다른 문제랍니다.", ""], ["본문", "어떤 정보를 대조할까요?", ""], ["본문", "건축물대장에 ‘근린생활시설’이라고 적힌 공간을 집처럼 꾸며 놓은 경우를 생각해 보세요. 침대가 있고 도배가 깨끗하다는 이유만으로 주택이라고 판단할 수는 없어요. 등록된 용도와 실제 상태가 다른 이유를 확인해야 해요.", ""], ["본문", "근린생활시설은 가게나 의원, 학원처럼 주민의 일상생활에 필요한 시설을 가리키는 건축물 용도예요. 어떤 시설인지에 따라 적용되는 기준도 달라요. 이름이 낯설면 “여기에서 주거용 계약을 해도 되는지, 대출과 반환보증 조건에는 맞는지”를 각각 확인해야 해요.", ""], ["소제목", "5) 문을 열 수 있으면 주인일까? :직거래와 가짜 집주인", ""], ["본문", "온라인에서 집을 직접 내놓고 거래하는 ‘직거래’도 있어요. 중개보수를 줄일 수 있지만 계약 당사자가 확인할 일이 많아져요. 직거래 자체가 사기는 아니에요. 다만 중개를 하든 직접 거래하든 집주인과 임대 권한을 속이는 수법을 주의해야 해요.", ""], ["본문", "시세보다 싼 광고만 보고 서둘러 돈을 보내거나, 상대가 보내 준 서류 사진만 믿는 일이 위험할 수 있어요. 실제 집을 보여 주더라도 그 사람에게 임대 권한이 있는지 별도로 확인해야 해요.", ""], ["본문", "쉽게 이해하도록 가상의 예를 들어볼게요.", ""], ["본문", "한 집주인이 빈 오피스텔을 온라인에 내놓았어요. 방을 보고 싶다는 사람이 문 비밀번호를 알려 달라고 했지요. 그런데 그 사람은 집을 구하려던 사람이 아니었어요. 알아낸 비밀번호로 다른 사람에게 방을 보여 주려 했던 거예요.", ""], ["본문", "그는 집주인인 척하며 싼 월세 광고를 올렸어요. 방을 보러 온 사람은 상대가 문을 열어 주는 모습을 보고 안심했고요. 하지만 문을 열 수 있다는 것과 집을 빌려줄 권한이 있다는 것은 달라요.", ""], ["본문", "이 장면에서 확인할 것은 값싼 월세만이 아니에요. 직접 열람한 최신 등기, 계약 상대방의 신분과 권한, 보증금을 받을 사람이 서로 연결되는지 살펴야 해요. 확인을 재촉하거나 피하는 말이 나오면 일단 멈추어 질문하세요.", ""], ["절 제목", "체크리스트 : 계약 전 확인부터 계약 후까지, 이것만은 꼭 확인!", ""], ["본문", "이제 머릿속에 낯선 말이 많이 모였을 거예요. 한꺼번에 외우려고 하지 않아도 괜찮아요. 계약 전에는 집과 상대방을 확인하고, 계약 후에는 보호를 위한 절차를 챙긴다는 두 단계로 정리해 볼게요. 아래 항목은 질문을 시작하는 길잡이예요.", ""], ["소제목", "1) 계약 전 꼭 확인해야 할 다섯 가지", ""], ["소소제목", "등기사항전부증명서 확인하기", ""], ["본문", "주소와 동·호수, 등기상 소유자, 담보권 등 권리 기록을 살펴요. 갑구와 을구를 모두 보아야 해요. 채권최고액이 실제 남은 빚과 같지는 않다는 점도 기억하세요.", ""], ["소소제목", "집주인 신분증 확인하기", ""], ["본문", "계약 상대방의 신분을 등기 기록과 대조해요. 대리인이면 위임 범위를, 신탁등기가 있으면 신탁원부와 임대 권한을 확인해요. 보증금을 누구의 어떤 계좌로 지급할지도 확인해야 해요.", ""], ["소소제목", "부동산 시세 확인하기", ""], ["본문", "여러 자료에서 비슷한 집의 실제 거래 가격을 비교해요. 집값이 떨어지거나 경매에서 예상보다 낮게 팔릴 때를 생각해 보세요. 예를 들어 1억 6천만 원에 팔린 집에서 먼저 갚을 은행 채무 2천만 원을 빼면 1억 4천만 원이 남아요. 보증금이 1억 5천만 원이면 이미 1천만 원이 부족하지요. 실제로는 세금과 비용도 따져야 해요.", ""], ["소소제목", "건축물대장 확인하기", ""], ["본문", "등록된 용도·면적·위반건축물 표시 등을 확인하고 실제 집과 비교해요. 서류 한 장만으로 모든 위반 여부나 건물의 안전을 알아낼 수는 없어요. 다른 점이 보이면 이유와 해결 여부를 물어보세요.", ""], ["소소제목", "세금 체납 여부 확인하기", ""], ["본문", "계약할 때 임대인은 국세·지방세 납세증명서를 보여 줘야 해요. 법으로 정한 의무예요. 미납 세금은 등기에 모두 나타나지 않아요. 보증금보다 먼저 배당되는지는 세금의 종류와 정해진 기준일 등에 따라 달라요. 계약 뒤에는 법에서 정한 절차로 미납 세금을 열람할 수 있어요. 예를 들어 보증금이 1천만 원을 넘는 주택 임대차는 계약 후 임대차가 시작되기 전까지 임대인 동의 없이 미납 국세를 열람할 수 있어요. [3-7]", ""], ["소제목", "2) 계약 후 챙길 세 가지", ""], ["소소제목", "집을 인도받고 전입신고하기", ""], ["본문", "집을 실제로 넘겨받는 일을 ‘인도’라고 해요. 집의 인도와 주민등록을 갖추면 다음 날 0시부터 대항력이 생겨요. 새 주인에게도 “이 계약에 따라 살고 있어요”라고 주장할 수 있는 힘이지요. 전입신고는 신청만 했는지, 처리가 완료되었는지도 확인해야 해요.", ""], ["도판 자리", "[도3-5] 〈타임라인 도해〉 두 줄. ① 계약 체결 → 확정일자는 입주 전에도 취득 가능. ② 집 인도 + 주민등록 완…", "3-5"], ["소소제목", "확정일자 받기", ""], ["본문", "확정일자는 계약서가 그 날짜에 존재했다는 것을 공적으로 확인하는 장치예요. 계약 후 입주 전에도 받을 수 있어요. 집의 인도와 주민등록을 갖춘 세입자가 확정일자까지 받으면, 경매나 공매에서 뒤 순위의 권리자보다 먼저 보증금을 받을 우선변제권이 생겨요. 다만 전액 회수를 보장하지는 않으며 필요한 배당 절차도 챙겨야 해요.", ""], ["소소제목", "전세보증금 반환보증 확인하기", ""], ["본문", "반환보증은 임대인이 보증금을 돌려주지 않을 때 보증기관이 약정한 조건에 따라 세입자에게 지급하고, 나중에 임대인에게 그 돈을 청구하는 상품이에요. 계약 전에 가입 조건과 신청 기한을 확인하고, 기한 안에 신청해 심사를 거친 뒤 보증서가 발급되었는지 확인해요. 은행의 전세자금대출 보증과 보증금 반환보증은 역할이 다르므로 이름과 보장 내용을 구별해야 해요.", ""], ["본문", "새로운 담보권을 설정하지 않겠다는 특약도 위험을 줄이는 약속이 될 수 있어요. 하지만 특약만으로 다른 사람의 권리 설정이 자동 차단되지는 않아요. 최신 등기를 다시 확인하는 절차가 함께 필요해요. 낯선 내용은 전문가나 공공 상담기관의 도움을 받아 확인하세요.", ""], ["도판 자리", "[도3-6] 〈체크리스트〉 계약 전: ① 등기 ② 상대방 신분·임대 권한 ③ 시세·앞선 권리 ④ 건축물대장·실제 상태 ⑤…", "3-6"], ["절 제목", "역사 속 집 이야기: 노상추도 셋집 문제로 속을 끓였어요", ""], ["본문", "지금부터 200여 년 전인 1796년, 조선의 무관 노상추도 한양에서 셋집 문제를 겪었어요. 『노상추일기』에는 처음 낸 세가 ‘27관’으로 기록되어 있어요. 집주인은 더 많은 돈을 주겠다는 사람에게 방을 내주려고 노상추를 내보내려 했지요.", ""], ["본문", "노상추는 돈을 더 내고 계속 살 생각도 했지만, 집주인은 이번에는 다른 방으로 옮기라고 했어요. 편안히 지내야 할 집에서 약속이 자꾸 달라진 거예요. 결국 노상추는 이사하겠다며 맡긴 돈을 돌려달라고 요구했어요.", ""], ["본문", "집주인은 돈을 써 버려 10냥밖에 없다고 답했어요. 노상추는 사람을 대하는 일을 아이들 놀이처럼 해서는 안 된다며 항의했지요. 일기에는 집주인이 다른 공간을 넘겨 마련한 30냥을 내주었다고 적혀 있어요. 처음의 ‘27관’과 뒤의 ‘30냥’은 기록에 나온 단위를 그대로 적은 것이에요. 기록에는 ‘관’과 ‘냥’처럼 여러 돈의 단위가 섞여 쓰여서, 지금 돈으로 바로 비교하기는 어려워요.", ""], ["본문", "연구자들은 노상추가 겪은 것처럼 ‘세전(貰錢)’이라는 돈을 맡기고 집을 빌려 살던 조선 후기의 ‘세매’ 관습을 오늘날 전세의 뿌리 가운데 하나로 보기도 해요. 다만 이 일을 오늘날의 전세사기와 완전히 같은 법적 사건으로 볼 수는 없어요. 당시의 관습과 지금의 제도가 다르니까요. 그래도 약속한 공간에서 살지 못하는 불안, 맡긴 돈을 돌려받지 못할까 하는 걱정은 낯설지 않아요. 집을 빌리는 사람의 생활을 지킬 규칙이 왜 필요한지 생각하게 해요.", ""], ["절 제목", "생각해 볼 질문", ""], ["번호 목록", "1. 구명조끼 대여료와 보증금은 무엇이 다른가요? 돌려받는 돈에 동그라미를 쳐 보세요.", ""], ["번호 목록", "2. ‘계약하기·확정일자 받기·집을 넘겨받기·전입신고하기’ 카드를 만들어 보세요. 입주 전에도 할 수 있는 것은 무엇인가요?", ""], ["번호 목록", "3. 앞의 그림에서 집이 1억 6천만 원에 팔리고 은행에 먼저 2천만 원을 갚으면 얼마가 남나요? 보증금 1억 5천만 원과 비교해 보세요.", ""], ["절 제목", "조금 더 깊게 생각하기", ""], ["질문 제목", "□ 전세 제도의 양면성: 기회와 위험 사이", ""], ["본문", "한국의 전세는 집을 소유하지 않고도 살 수 있는 독특한 주거 방식이자, 자산을 형성할 수 있는 수단이기도 해요. 하지만 동시에 부동산 임대 사기나 보증금 미반환과 같은 문제는 이 제도 아래 숨겨진 위험이기도 하죠. 조선 시대 노상추의 사례처럼, 보증금과 임차인의 권리를 둘러싼 갈등은 과거에도 존재했어요.맡긴 돈을 돌려받지 못할까 하는 불안이 예나 지금이나 있었다는 점, 그리고 오늘날 더 정교해진 사기 수법을 함께 생각하며, 지금 우리가 어떤 제도적 장치와 시민의식을 가져야 할지 논의해 봅시다.", ""], ["질문 제목", "□ 보증금을 지키는 안전장치, 얼마나 알고 있나요?", ""], ["본문", "등기사항전부증명서 확인, 건축물대장 열람, 세금 체납 조회, 전입신고, 확정일자 받기, 보증보험 가입 등은 세입자의 보증금을 보호해 주는 중요한 장치예요. 특히 집주인이 세금을 밀릴 경우, 세금이 경우에 따라 보증금보다 먼저 배당될 수 있다는 점은 보증금 보호가 얼마나 복잡한지를 잘 보여주죠. 각 제도가 어떤 역할을 하는지 설명하고, 세입자가 꼭 실천해야 할 점은 무엇인지 정리해 보세요.", ""], ["질문 제목", "□ 계약서 확인, 누구의 책임", ""], ["본문", "전세 계약을 맺을 때 계약서를 꼼꼼히 읽지 않거나 중요한 확인을 놓치면 피해를 입을 수 있어요. 하지만 이런 실수나 피해가 과연 전적으로 개인의 책임일까요? 세입자의 주의 의무와 더불어, 사회나 정부가 어디까지 책임지고 보호해 주어야 하는지도 함께 고민해 봅시다.", ""], ["질문 제목", "□ 임대 사기는 개인 실수일까, 사회 문제일까?", ""], ["본문", "부동산 임대 사기를 단순히 “피해자가 조심하지 않아서 생긴 일”로만 볼 수 있을까요? 실제로는 정보의 비대칭, 제도의 허점, 악성 임대인의 범죄 행위 등 다양한 사회적 문제가 얽혀 있는 경우가 많아요. 조선 후기에도 세전을 맡기고 셋집에 살던 양반이 그 돈을 돌려받지 못할까 걱정한 기록이 남아 있을 만큼, 주거 불안정은 시대를 넘어 반복되는 구조적 문제예요. 우리는 이런 문제를 해결하기 위해 어떤 정책과 시스템을 갖추어야 할까요? 여러분의 생각을 자유롭게 제안해 보세요.", ""]]}, {"key": "ch04", "num": "04", "title": "종이 한 장이 내 권리를 지켜준다고요?", "p": [["본문", "여러분, 친구랑 약속해 본 적 있죠? “이따가 점심시간에 운동장에서 축구하자!”, “이번 주말에 마라탕 먹으러 가자!”처럼 말이에요. 우리는 하루에도 몇 번씩 이런 약속을 주고받으며 살아가요. 친구와의 소소한 약속부터, 엄마 아빠와의 약속, 학교에서 지켜야 할 규칙, 그리고 편의점에서 물건을 사는 일처럼 돈이 오가는 약속까지. 생각해 보면, 우리 삶은 약속의 연속이죠.", ""], ["본문", "이 많은 약속 가운데 법적인 권리와 의무를 만들려는 약속을 ‘계약’이라고 해요. 조금 딱딱하게 느껴지나요? 편의점에서 과자를 사거나 자전거를 빌리는 일에도 계약이 숨어 있어요. 서로 무엇을 해 주기로 했는지 정하면, 상대에게 그 약속을 지켜 달라고 요구할 수 있는 것이죠.", ""], ["본문", "친구와 “내일 도서관에서 만나자”고 약속했다가 만나지 못하면 보통은 사정을 듣고 다시 약속을 잡아요. 반면 집을 빌리기로 계약하고 돈까지 지급했는데 집을 넘겨주지 않는다면, 계약에 따른 권리와 책임을 따져야 하지요. 약속이 모두 같은 법적 의미를 갖는 것은 아니에요.", ""], ["본문", "잘 작성한 계약서는 서로의 약속을 확인하는 든든한 길잡이가 될 수 있어요. 반대로 뜻이 모호하거나 중요한 조건이 빠져 있으면 다툼이 생기기 쉬워요. 서명하기 전에 천천히 읽고 질문하는 시간이 필요한 이유예요.", ""], ["본문", "이번 장에서는 계약이 어떻게 생기고, 계약서는 무슨 일을 하는지 알아볼 거예요. 그리고 흐릿한 약속을 누구나 이해할 수 있는 문장으로 바꾸는 연습도 해 볼게요.", ""], ["절 제목", "계약이란 도대체 무엇일까? : 약속을 지키게 만드는 힘!", ""], ["본문", "계약은 당사자들이 법적인 권리와 의무를 만들 내용에 합의하면서 성립해요. 모든 계약에 서명한 종이가 꼭 있어야 하는 것은 아니에요. 특별히 정해진 형식이 필요한 경우가 아니라면, 말로 합의해도 계약이 될 수 있어요. 계약이 있는지와 그 내용을 나중에 어떻게 증명할지는 다른 질문이에요.", ""], ["본문", "또 다른 예를 하나 들어볼게요. 여러분이 편의점에서 1,000원을 주고 과자를 산다고 해봐요. 이것도 일종의 계약이에요. 여러분은 “1,000원을 드릴 테니 과자를 주세요”라고 약속하는 거예요. 그러면 돈을 줄 의무와 과자를 받을 권리가 생기죠. 반대로 편의점 주인은 “1,000원을 받으면 과자를 줄게요”라고 약속하는 거예요. 그래서 과자를 줄 의무와 돈을 받을 권리가 생기는 거예요. 이렇게 작은 거래 하나에도 계약이 숨어 있는 거죠.", ""], ["본문", "과자와 가격에 합의했다면 돈을 건네기 전에도 매매계약이 성립할 수 있어요. 돈을 내고 과자를 받는 것은 그 약속을 실행하는 과정이지요. 돈을 냈는데 과자를 주지 않으면 약속대로 과자를 달라고 요구할 수 있어요. 이렇게 작은 거래에서도 권리와 의무가 서로 이어져 있어요.", ""], ["절 제목", "계약서를 꼭 써야 하는 이유 : 눈에 보이지 않는 약속을 눈으로 보게 만들자!", ""], ["본문", "“우린 서로 믿으니까 괜찮아.” 이런 말을 들으면 계약서를 쓰자고 하는 것이 상대방을 의심하는 일처럼 느껴질 수 있어요. 하지만 약속을 적어 두는 것은 서로를 도울 수 있어요. 어떤 내용을 약속했는지 나중에도 함께 확인할 수 있으니까요.", ""], ["본문", "사람의 기억은 완벽하지 않아요. 약속할 때는 분명히 “이렇게 하자”고 말했는데, 시간이 지나면 서로 다르게 기억하거나 아예 기억나지 않을 수도 있어요. 심지어 자신에게 유리하게 기억이 바뀌는 일도 있죠. 말로만 약속하면, 나중에 “나는 그런 말 한 적 없어”라고 우기거나 “그건 네가 오해한 거야”라며 다툼이 생기기 쉬워요.", ""], ["본문", "같은 말도 다르게 이해할 수 있어요. “고장 난 것은 알아서 고쳐 줄게요”에서 ‘고장 난 것’은 어디까지이고, ‘알아서’는 언제까지일까요? 종이에 적었다고 저절로 분명해지는 것은 아니에요. 누가 무엇을 언제까지 할지 구체적으로 써야 오해를 줄일 수 있어요.", ""], ["본문", "중요한 이야기를 나눈 뒤에는 계약서에 반영된 내용이 맞는지 함께 읽어 보세요. 처음 설명과 달라진 점은 없는지, 비용이나 책임이 빠져 있지는 않은지 살펴야 해요.", ""], ["본문", "나중에 기억이 달라져도 계약서를 함께 펼치면 어떤 약속을 했는지 확인할 수 있어요. 계약서는 중요한 증거예요. 다만 서명한 종이가 있다는 이유만으로 모든 문구가 언제나 유효해지는 것은 아니랍니다.", ""], ["절 제목", "계약서에 담을 네 가지 질문", ""], ["본문", "첫째, 누구와 무엇을 계약하나요? 당사자의 이름, 대신 서명하는 사람의 권한, 집의 주소와 동·호수를 확인해요. 다른 집이나 권한 없는 사람과 계약하는 실수를 줄일 수 있어요.", ""], ["본문", "둘째, 얼마를 언제 지급하나요? 보증금·계약금·잔금·월세의 금액과 지급일, 받을 사람과 계좌를 정해요. 관리비에 무엇이 포함되는지도 확인해요.", ""], ["본문", "셋째, 언제부터 언제까지 사용하나요? 입주와 퇴거 시점, 집을 넘겨주는 방법, 고장이나 수리의 책임을 정해요. 둘이 다르게 이해한 표현이 있으면 다시 써요.", ""], ["본문", "넷째, 약속을 바꾸거나 끝내야 하면 어떻게 하나요? 어떤 사유와 절차로 계약을 끝낼 수 있는지, 이미 지급한 돈은 언제 어떻게 정산할지 확인해요. 합의한 내용이 법에 어긋나지 않는지도 중요해요.", ""], ["도판 자리", "[도4-1] 〈도해〉 가상의 주택 임대차 계약서 한 장을 간추려 구성. ‘주택임대차표준계약서’(법무부·국토교통부)의 항목…", "4-1"], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "계약서가 없다고 권리가 무조건 사라지는 것은 아니에요. 문자, 녹음, 돈을 주고받은 기록 등도 판단 자료가 될 수 있어요. 이미 문제가 생겼다면 “종이가 없으니 소용없겠지” 하고 포기하지 말고 남아 있는 자료를 모아 상담을 받아야 합니다. 앞장에서 배웠던 “권리 위에 잠자는 자는 법의 보호를 받지 못한다”는 말을 항상 기억하세요.", ""], ["절 제목", "역사 속 계약 읽기 : 맨해튼과 60길더의 기록", ""], ["본문", "“맨해튼을 단돈 24달러에 샀다”는 이야기를 들어 본 적 있나요? 1626년, 네덜란드 서인도회사가 세운 식민지 ‘뉴네덜란드’의 책임자 피터 미뉴잇(Peter Minuit)이 지금의 뉴욕 한가운데에 있는 맨해튼 섬을 샀다고 전해져요. 그것도 단돈 60길더어치의 물건으로요. 오늘날 돈으로 약 1,100달러, 흔히 ‘24달러짜리 구슬과 거울’ 정도의 물건을 주고 거래한 것으로 알려졌죠. 이 이야기는 오늘날 세계에서 가장 비싼 땅 중 하나인 맨해튼이 이렇게 헐값에 팔렸다는 점에서, 지금까지도 많은 사람들의 관심과 상상력을 자극하는 전설 같은 사례로 남아 있어요. (‘24달러’는 뒤 시대에 60길더를 달러로 환산하면서 퍼진 숫자예요. 1626년 당사자들이 오늘의 미국 달러 지폐 24장을 주고받았다는 뜻은 아니랍니다.)", ""], ["본문", "실제로 네덜란드 국가기록원에는 1626년 피터르 스하헌이 쓴 편지가 남아 있어요. 이 편지는 맨해튼을 60길더어치 물건으로 샀다고 짧게 전할 뿐, 누가 거래했는지는 적지 않았어요. 물론, 지금의 계약서처럼 거래 조건을 자세히 적은 문서가 남아 있는 것은 아니에요.", ""], ["본문", "이 계약은 단순히 “싸게 땅을 샀다”라는 얘기만은 아니에요. 그 이면에는 서로 다른 문화를 가진 두 집단 사이에 큰 오해가 있었을지도 몰라요. 미뉴잇을 비롯한 네덜란드 사람들은, 이 거래를 통해 맨해튼 섬의 법적 소유권을 완전히 넘겨받았다고 믿었어요. 즉, \"이제부터 이 땅은 우리 땅이야!\"라고 생각한 거죠. 그런데 거래 상대였던 레나페 족(Lenape), 즉 이 지역의 원주민들은 그런 식으로 땅을 영구히 소유한다는 개념 자체가 없었어요. 이처럼 오늘날 연구자들은 당시 원주민과 네덜란드인이 땅을 이용하고 넘기는 권리를 다르게 이해했을 가능성을 이야기하곤 해요. 하지만 정확한 거래 물품과 당사자들의 생각을 모두 확정할 만큼 기록이 충분하지는 않아요.", ""], ["본문", "이 이야기는 싼값에 땅을 사는 비법보다 “누구의 기록이 남아 있고, 누구의 목소리가 빠져 있을까?”라는 질문으로 읽으면 좋아요. 오늘의 계약에서도 서로가 같은 대상과 조건을 이해하는지 확인하는 일이 중요하답니다.", ""], ["도판 자리", "[도4-2] 〈지도와 기록 읽기〉 현재의 맨해튼 위치 지도 옆에 1626년 스하헌 편지 이미지. 캡션 : ‘기록에서 확인…", "4-2"], ["절 제목", "부모님이 계약할 때 : 누구의 이름으로 하는 약속일까?", ""], ["본문", "휴대전화를 새로 개통할 때 부모님이 서명하는 모습을 볼 수 있어요. 이때는 두 경우를 구별해야 해요. 부모님 자신의 이름으로 계약하는 것과, 자녀를 대신하는 법정대리인으로 계약하는 것이에요.", ""], ["본문", "부모님이 본인 명의로 휴대전화를 개통하면 계약에 따른 권리와 요금 납부 책임은 원칙적으로 부모님에게 생겨요. 반면 부모님이 법정대리인으로 자녀를 대신해 자녀 명의의 계약을 맺으면, 그 계약의 권리와 의무는 원칙적으로 자녀에게 생겨요. 누가 서명했는지만 보지 말고 누구를 위한 어떤 계약인지 살펴야 해요.", ""], ["본문", "미성년자도 권리를 가지고 계약의 당사자가 될 수 있어요. 계약에는 원칙적으로 법정대리인의 동의가 필요하고, 용돈으로 하는 거래처럼 법에서 정한 예외도 있지요. 성인이 되어야만 처음으로 권리를 갖게 되는 것은 아니랍니다.", ""], ["본문", "나중에 직접 계약할 날을 위해 지금부터 계약이 얼마나 중요한지 조금씩 배워 두면 좋아요. 부모님과 함께 휴대폰을 개통할 때 옆에서 “이건 무슨 뜻이에요?” 하고 물어보는 것만으로도 큰 도움이 된답니다.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "미성년자가 계약을 하려면 원칙적으로 법정대리인(보통은 부모님)의 동의가 필요해요. 동의 없이 한 계약은 미성년자나 법정대리인이 취소할 수 있어요. 다만 예외도 있어요. 용돈처럼 자유롭게 쓰도록 허락받은 돈의 범위에서 한 계약이거나, 자기가 성년인 것처럼 적극적으로 속인 경우에는 취소하지 못할 수도 있답니다.", ""], ["절 제목", "계약서 읽기 : 잘 보이게 설명받을 권리", ""], ["본문", "계약서에서 크게 보이는 금액만 읽고 지나가기 쉬워요. 하지만 추가 비용이나 해지 조건, 개인정보 제공 같은 내용도 중요해요. 글씨가 작거나 말이 어려워 이해하기 힘들면 설명해 달라고 요청할 수 있어요.", ""], ["본문", "“다들 그냥 서명해요”라는 말에 서두를 필요는 없어요. 읽을 시간을 갖고, 중요한 조건을 말로 다시 설명해 달라고 해 보세요. 조건을 분명하게 알리는 것은 계약을 제안하는 쪽의 책임이기도 해요.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "‘약관’은 회사가 많은 사람과 같은 내용으로 계약하기 위해 미리 만들어 둔 계약 조건이에요. 우리가 앱에 가입할 때 누르는 ‘동의합니다’가 바로 약관 동의죠. 내용을 바꾸기 어렵다는 점 때문에, 소비자에게 지나치게 불리한 약관은 법으로 효력을 제한하기도 해요.", ""], ["본문", "홈플러스의 경품 응모권을 둘러싼 개인정보 사건을 살펴볼까요? 소비자는 경품 행사라고 생각했지만, 응모권에는 개인정보를 보험회사에 제공한다는 내용이 작은 글씨로 적혀 있었어요. 개인정보를 판매하려는 목적을 충분히 알렸는지가 법적 쟁점이 되었지요.", ""], ["본문", "2017년 대법원은 이 사건에서 작은 글씨와 행사 방식 등을 함께 살펴, 이런 방식으로 받은 동의는 ‘거짓이나 그 밖의 부정한 방법’으로 받은 것이라고 보았어요. 앞선 재판에서 무죄로 본 것을 뒤집은 판결이었지요. 핵심은 “작게라도 적혀 있으면 모두 약속”이라는 것이 아니에요. 중요한 목적을 감추거나 알아보기 어렵게 한 채 형식적인 동의만 받아서는 안 된다는 점이에요.", ""], ["본문", "따라서 소비자는 중요한 조건을 확인하고, 사업자는 그 조건을 알아보기 쉽게 알려야 해요. 서명 하나로 설명할 책임이 모두 사라지지는 않아요. 질문할 권리와 설명할 책임이 함께 있다는 것을 기억하세요.", ""], ["본문", "계약서를 읽는 연습은 무엇을 이해했고 무엇이 아직 불분명한지 알아차리기 위한 것이에요. “추가 비용이 있나요?”, “중간에 그만두면 어떻게 되나요?”처럼 질문을 구체적으로 만들어 보세요.", ""], ["절 제목", "재미있는 활동 : ‘작은 글씨의 비밀을 찾아라!’ 게임", ""], ["본문", "집에서 구할 수 있는 여러 가지 계약서나 서류들을 한 번 꺼내서 살펴보는 것은 좋은 연습이 돼요. 예를 들어 휴대폰 가입 신청서, 보험 약관, 은행 계좌 개설 안내문 같은 서류들에는 작은 글씨로 적힌 다양한 조건들이 숨어 있어요. 가족들과 함께 둘러앉아 ‘작은 글씨 속에 숨어 있는 중요한 내용 찾기 게임’을 해보는 건 어떨까요? 누가 더 많은 조건을 찾아내는지 시합을 해봐도 재미있고, 그 조건들이 실제로 우리의 권리나 책임에 어떤 영향을 줄 수 있는지 이야기해 보는 것도 유익한 시간이 될 거예요.", ""], ["본문", "또 평소에 우리가 자주 접하지만, 그냥 넘기기 쉬운 부분들도 꼭 한 번 주의 깊게 들여다보세요. 예를 들어 인터넷 쇼핑몰이나 앱을 사용할 때 나오는 ‘이용 약관 동의’ 체크박스, 대부분은 별생각 없이 체크하고 넘어가곤 하죠. 하지만 그 안에는 여러분의 권리와 의무에 관한 중요한 내용이 담겨 있어요. 예를 들어 “무료라고 쓰여 있는데, 언제부터 얼마를 내야 하나요?”처럼 물을 수도 있지요. 앞으로는 “그냥 넘기지 말고 한 번쯤 열어보기”로 해요. 이 작은 습관 하나만으로도 여러분은 더 똑똑하고 안전한 소비자가 될 수 있어요.", ""], ["절 제목", "계약은 특히 신중하게! 계약금을 주고받은 뒤 마음이 바뀌면?", ""], ["본문", "집을 사거나 빌릴 때는 계약금을 먼저 주고받는 경우가 많아요. 계약금에는 계약을 맺었다는 것을 보여주는 역할뿐 아니라, 일정한 조건에서 계약을 끝내는 기준이 되는 역할도 있어요.", ""], ["본문", "다른 약속이 없다면, 어느 한쪽이 계약의 실행에 나서기 전까지는 계약금을 낸 사람이 그 돈을 포기하거나, 받은 사람이 두 배를 돌려주고 계약을 해제할 수 있어요. 이런 계약금의 역할을 ‘해약금’이라고 해요.", ""], ["본문", "계약금이 1천만 원이라면, 낸 사람은 1천만 원을 포기하는 것이고 받은 사람은 받은 1천만 원에 1천만 원을 더해 모두 2천만 원을 돌려주는 거예요. 다만 중도금을 지급하는 등 계약의 실행이 시작된 뒤에도 마음대로 이 방법을 쓸 수 있는 것은 아니에요.", ""], ["도판 자리", "[도4-3] 〈타임라인 도해〉 계약서 작성·계약금 지급 → 중도금 지급 → 잔금 지급·입주. 계약금을 지급한 때부터 ‘어…", "4-3"], ["본문", "이것은 계약을 어겨 손해를 배상하는 문제와 구별해야 해요. 계약금 일부만 먼저 보낸 경우나 따로 정한 약정이 있는 경우에도 판단이 달라질 수 있어요. “가계약금이니까 언제나 돌려받겠지”라고 이름만 보고 결정하면 안 돼요.", ""], ["본문", "돈을 보내기 전에는 어떤 조건에 동의한 것인지, 계약을 끝내면 그 돈을 어떻게 처리하는지 확인하세요. 적은 돈을 먼저 보냈더라도 중요한 계약 문제가 생길 수 있답니다.", ""], ["절 제목", "협상해 볼까요? : “알아서 고쳐 줄게요”를 바꾸는 대화", ""], ["본문", "처음 자취방을 구하는 대학생 지후는 마음에 드는 집을 찾았지만, 한 가지 문제가 있었어요. 에어컨을 켜도 찬 바람이 나오지 않았거든요. 집주인은 걱정하지 말라는 듯 말했어요.", ""], ["본문", "“입주하면 알아서 고쳐 줄게요.”", ""], ["본문", "지후는 마음이 놓였지만, 곧 한 가지가 마음에 걸렸어요. 이사할 때는 한여름인데, 입주한 뒤에 수리를 시작하면 며칠 동안 더운 방에서 지내야 할 수도 있었어요. 지후에게는 에어컨을 고치는 것만큼이나 언제까지 고치는지가 중요했던 거예요.", ""], ["본문", "“이사하는 날부터 에어컨을 쓸 수 있으면 좋겠어요. 입주 전에 수리를 마쳐 주실 수 있을까요?”", ""], ["본문", "“수리 기사님 일정을 먼저 확인해 봐야겠네요.”", ""], ["본문", "집주인은 기사에게 연락해 방문할 수 있는 날을 알아보았어요. 두 사람은 그 일정을 바탕으로 집주인이 비용을 부담해 입주 전날까지 수리를 마치기로 했어요. 입주하는 날에는 함께 에어컨을 켜서 찬 바람이 잘 나오는지도 확인하기로 했지요.", ""], ["본문", "지후는 한 가지를 더 부탁했어요.", ""], ["본문", "“그 내용을 계약서에도 적어 주실 수 있을까요?”", ""], ["본문", "두 사람은 합의한 내용을 계약서에 적었어요. “알아서 고쳐 준다”는 말이 누가 비용을 부담하고, 무엇을 언제까지 하며, 어떻게 확인할지 분명한 약속으로 바뀐 거예요. 서로 같은 내용으로 이해했는지 확인하고, 나중에도 약속을 다시 살펴볼 수 있게 되었지요.", ""], ["본문", "물론 지후가 원하는 대로 협상이 이루어지지 않을 수도 있어요. 수리 기사 일정이 맞지 않아 입주 전에 고치기 어렵다면 어떻게 해야 할까요? 지후는 수리를 며칠 정도 기다릴 수 있는지, 입주일을 조정할 수 있는지 생각해 봐야 해요. 조건이 맞지 않으면 다른 집을 알아볼 수도 있고요. 그래서 협상하기 전에는 자신에게 꼭 필요한 조건과 조정할 수 있는 조건을 생각해 두는 것이 좋아요.", ""], ["본문", "협상은 이렇게 내게 필요한 것을 말하고, 상대가 할 수 있는 일을 확인하며, 서로 지킬 약속을 만들어 가는 과정이에요. 집을 구할 때도 궁금하거나 분명하지 않은 조건이 있다면 질문할 수 있어요. 상대가 불편해할까 봐 망설여진다면, 이렇게 시작해 보세요.", ""], ["본문", "“제가 이해한 내용이 맞는지 확인하고 싶어요.”", ""], ["소제목", "1) 계약은 협상의 결과", ""], ["본문", "계약은 이미 정해진 종이에 이름만 쓰는 일로 끝나지 않아요. 가격과 기간, 수리 책임, 계약을 끝내는 조건을 살펴보고 수정을 제안할 수 있어요. 합의한 내용은 나중에도 확인할 수 있도록 계약서에 반영해요.", ""], ["본문", "다만 협상을 잘한다는 것은 상대를 이기는 기술이 아니에요. 집을 급히 구하는 세입자처럼 시간과 정보가 부족한 사람은 상대와 같은 힘으로 협상하기 어려울 수 있어요. 그래서 법은 주택 임차인과 소비자에게 최소한의 보호를 따로 마련해요. 서로 지킬 수 있는 조건을 분명하게 정하고, 힘이나 정보가 한쪽에 치우치지 않도록 확인하는 일이 좋은 협상의 기준이에요. 불법이거나 사회질서에 어긋난 약속, 소비자에게 지나치게 불리한 약관은 서명했다고 해서 언제나 그대로 효력이 인정되는 것도 아니에요.", ""], ["도판 자리", "[도4-4] 〈도해〉 협상 저울. 한쪽에 ‘시간·정보·돈이 많은 쪽’, 다른 쪽에 ‘급하게 집을 구하는 세입자’를 올려 …", "4-4"], ["소제목", "2) 계약에서 생기는 권리, 법이 지켜 주는 권리", ""], ["본문", "계약을 통해 집을 사용할 권리나 물건을 받을 권리처럼 구체적인 권리가 생겨요. 계약서는 그 내용을 확인하는 중요한 증거이지요. 그래서 당사자와 대상, 금액, 기간, 책임을 분명히 적는 일이 중요해요.", ""], ["본문", "그러나 우리의 모든 권리가 계약으로 생기는 것은 아니에요. 인간답게 살 권리와 어린이를 보호받게 하는 권리, 법에서 정한 소비자의 권리도 있어요. 불공정한 조건에 서명했다는 이유만으로 법이 마련한 보호를 모두 잃는 것도 아니고요.", ""], ["본문", "계약서를 만났을 때는 이렇게 생각해 보세요. “나는 무엇을 할 수 있고, 무엇을 해야 하지? 상대방은 무엇을 해 주기로 했지?”", ""], ["본문", "둘의 설명이 다르거나 이해가 안 되는 조항이 있다면 멈추어 물어보면 돼요. 서명을 서두르는 것보다 동의할 내용을 아는 것이 먼저예요.", ""], ["절 제목", "생각해 볼 질문", ""], ["번호 목록", "1. 편의점에서 과자를 살 때, 손님이 할 일과 가게가 할 일을 하나씩 말해 보세요.", ""], ["번호 목록", "2. “계약서가 없으면 아무 권리도 없다”는 말은 맞을까요? 본문에서 이유를 찾아보세요.", ""], ["번호 목록", "3. 해약금에 따른 계약 해제가 가능한 조건에서 계약금 1천만 원을 받은 사람이 해제하려면, 총 얼마를 돌려줘야 하나요?", ""], ["절 제목", "조금 더 깊게 생각하기", ""], ["질문 제목", "□ ‘약속’과 ‘계약’의 차이", ""], ["본문", "두 개념의 차이를 법적인 효력과 증명 가능성의 관점에서 설명해 보세요. 특히 부동산 계약처럼 중요한 거래에서는 말로도 계약이 될 수 있는데 왜 계약서를 꼭 써 두어야 하는지, 말로만 한 약속에는 어떤 위험이 있는지 예를 들어 이야기해 보세요.", ""], ["질문 제목", "□계약을 끝내는 규칙, ‘해약금’", ""], ["본문", "어느 한쪽이 계약을 실행하기 전이라면, 계약금을 낸 사람은 그 돈을 포기하고 받은 사람은 두 배를 돌려주고 계약을 끝낼 수 있어요. 이것을 ‘해약금’ 규칙이라고 해요. 이런 규칙은 왜 필요할까요? 이 규칙이 계약하는 사람들에게 어떤 신중함을 요구하는지, 약속을 어겨 손해를 물어 주는 일과는 어떻게 다른지 함께 생각해 봅시다.", ""], ["질문 제목", "□ 부동산 계약은 어떻게 돈과 힘을 만들까?", ""], ["본문", "1장에서 본 맥도날드를 예로 들어, 가게 자리를 빌리고 다시 빌려주는 계약이 회사의 수입과 가맹점 관리에 어떤 역할을 했는지 설명해 보세요. 그리고 이런 계약에서 힘이 약한 쪽을 보호하려면 무엇이 필요할지도 생각해 봅시다.", ""], ["질문 제목", "□ ‘계약이 권리를 만든다’라는 말의 의미", ""], ["본문", "계약을 통해 개인의 권리가 어떻게 형성되고 보호되는지, 실제 생활 속 예시를 들어 설명해 보세요. 또한 계약을 맺을 때 개인이 가져야 할 윤리적 태도와 책임감에 대해서도 함께 생각해 봅시다. 계약은 단순한 절차가 아니라, 사회적 신뢰를 지탱하는 약속임을 잊지 말고 논의해 보세요.", ""]]}, {"key": "ch05", "num": "05", "title": "부동산 뉴스의 비밀 코드를 해독하라!", "p": [["본문", "이 책을 읽고 있는 여러분이라면 뉴스나 신문을 본 적이 있겠죠? 특히 경제면이나 사회면을 보다 보면, 무슨 말인지 쉽게 이해되지 않는 단어들이 눈에 띌 때가 많아요. 그중에서도 부동산 관련 뉴스는 유난히 어렵고 낯설게 느껴지죠.", ""], ["본문", "‘신탁’, ‘청약’, ‘용도지역’, ‘재건축’, ‘용적률’, ‘건폐율’…. 처음 들으면 암호처럼 느껴지지만, 뜻을 알고 나면 기사에서 무슨 이야기를 하는지 조금씩 보이기 시작해요.", ""], ["본문", "이번 장에서는 세 가지 질문을 따라 뉴스를 읽어 볼 거예요. “누가 어떤 일을 맡았을까?”, “새 집을 살 기회는 어떻게 나눌까?”, “우리 동네는 어떻게 바뀔까?”예요. 앞에서 배운 계약과 권리에 관한 지식도 다시 꺼내 써 보아요.", ""], ["본문", "단어의 뜻을 알아도 기사 한 줄만으로 모든 것을 알 수는 없어요. ‘추진’과 ‘완공’은 다르고, 사람들이 많이 신청했다는 소식이 앞으로의 집값을 보장하지도 않지요.", ""], ["본문", "이번 장의 비밀 암호는 바로 두 질문이에요. “이 기사로 무엇을 알 수 있지?” 그리고 “무엇을 더 확인해야 하지?” 자, 함께 해독해 볼까요?", ""], ["절 제목", "신탁이란? : 나의 소중한 것을 믿고 맡기는 약속", ""], ["본문", "제3장에서 만난 ‘신탁’을 기억하나요? ‘믿을 신(信)’과 ‘맡길 탁(託)’을 써요. 재산을 맡기는 사람인 ‘위탁자’가 관리하는 사람인 ‘수탁자’에게 재산을 넘기거나 처분해, 정해진 목적에 따라 관리하게 하는 제도예요. 부동산 신탁에서는 신탁회사가 수탁자를 맡는 경우가 많아요.", ""], ["본문", "그렇다면 부동산을 왜 신탁회사에 맡길까요?", ""], ["본문", "직접 건물을 관리하기 어렵거나, 전문적인 개발이 필요할 때 신탁을 이용할 수 있어요. 빌린 돈의 상환을 담보하기 위한 신탁도 있고요. 어떤 목적으로 누구를 위해 관리할지는 신탁의 내용에 따라 달라져요.", ""], ["본문", "신탁을 위해 소유권을 넘기면 등기사항전부증명서에 신탁회사 등이 소유자로 표시돼요. “잠깐 이름만 빌린 것”이라고 생각하면 안 돼요. 신탁이 끝난 뒤 남은 재산을 누가 받는지도 신탁에서 정한 내용과 법에 따라 달라져요. 언제나 원래 주인에게 돌아오는 것은 아니랍니다.", ""], ["본문", "하지만 이렇게 유용한 제도가 때로는 부동산 사기에 악용되기도 해요. 예를 들어, 집주인이 자신이 가진 집의 소유권을 신탁회사에 넘겨서 법적인 주인은 신탁회사로 바뀌었는데, 그 사실을 숨기고 세입자에게 “나는 여전히 이 집 주인이에요”라고 속이면서 임대 계약을 맺는 거예요. 세입자는 보증금을 내고 계약을 하지만, 위탁자에게 임대 권한이 없거나 수탁자의 동의가 없다면 신탁회사나 새 소유자에게 임차권을 주장하기 어려운 상황에 놓일 수 있어요. 제3장에서 나왔던 신탁부동산 사기가 바로 이런 사례예요.", ""], ["본문", "등기에 신탁이 표시되어 있다면 신탁원부까지 확인해, 누가 집을 빌려줄 권한을 가지고 어떤 동의가 필요한지 살펴야 해요. 제3장에서 배운 것처럼 서류와 계약할 사람의 권한을 함께 확인하는 것이 핵심이에요.", ""], ["절 제목", "누가 어떤 일을 할까? : 공인중개사와 중개보조원", ""], ["본문", "공인중개사사무소에 들어가니 한 사람은 집을 보여 주고, 다른 사람은 서류를 설명해요. 모두 같은 일을 할 수 있을까요? 사무소에 있다는 사실만으로 그 사람의 자격과 맡은 일을 알 수는 없어요.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "예전에는 집이나 땅을 소개하는 곳을 ‘복덕방’이라고 불렀어요. 지금도 익숙하게 ‘부동산’이라고 부르지만, 간판에서는 ‘○○공인중개사사무소’ 같은 이름을 볼 수 있지요. '공인(公認)'은 나라가 인정한, '중개(仲介)'는 사이에 끼어 양쪽을 이어 주는, '사(士)'는 그 일을 하는 전문가라는 뜻이에요. 즉, 공인중개사는 나라가 자격을 인정한, 집을 사고팔거나 빌리고 빌려주는 사람 사이를 이어 주는 전문가를 말해요.", ""], ["도판 자리", "[도5-1] 〈도해〉 사무소 등록증과 공인중개사 자격증, 명함의 직함을 확인하는 장면. ‘등록한 개업공인중개사: 중개 업…", "5-1"], ["본문", "공인중개사사무소에는 다양한 사람들이 일하고 있지만, 그중에서 꼭 구분해서 알아야 할 두 사람이 있어요. 바로 공인중개사와 중개보조원입니다. 뉴스에서 부동산 거래 사고가 났을 때도 이들의 역할이 종종 문제로 떠오르곤 하죠.", ""], ["본문", "공인중개사는 국가 자격시험에 합격해 자격을 얻은 사람이에요. 중개사무소를 열려면 별도의 등록도 필요해요. 등록한 개업공인중개사와 그 사무소의 소속공인중개사는 거래할 집의 권리관계와 상태를 확인하고 설명하는 등 중개 업무를 맡아요.", ""], ["본문", "중개를 맡은 공인중개사는 계약서와 확인·설명서 등에 법에서 정한 사항을 적고 서명·날인할 의무가 있어요. 다만 중개사의 정보가 빠졌다는 이유만으로 집주인과 세입자가 맺은 계약이 곧바로 무효가 되는 것은 아니에요. 중개사의 의무 위반과 당사자 사이 계약의 효력은 구별해야 해요.", ""], ["본문", "중개보조원은 집을 보여 주거나 서류를 전달하는 등 단순한 보조 업무를 해요. 손님에게 자신이 중개보조원이라는 사실을 미리 알려야 하고, 중개사가 해야 할 계약 조건의 조율이나 확인·설명을 대신할 수는 없어요.", ""], ["본문", "뉴스에서 “무자격 중개”라는 말을 보면 누가 어떤 자격과 권한으로 일을 했는지 살펴보세요. 문제가 생겼을 때의 책임과 손해배상은 실제 행위와 피해, 인과관계 등을 따져 판단해요. 보험이나 공제에 가입해 있어도 모든 손해가 저절로 보상되는 것은 아니에요.", ""], ["본문", "집을 볼 때는 “중요한 조건은 어느 공인중개사에게 설명을 들으면 되나요?” 하고 물어볼 수 있어요. 전문가의 도움을 받되, 이해되지 않는 설명은 다시 질문하는 것이 좋아요.", ""], ["절 제목", "청약이란? : 새 집을 사고 싶다고 신청하기", ""], ["본문", "“새 아파트 청약 경쟁률 100 대 1!” 이런 제목을 본 적 있나요? 주택 청약은 분양받을 집을 정해 “저도 이 집을 사고 싶어요”라고 신청하는 일이에요. 공연 관람을 신청해도 모두 표를 받는 것은 아닌 것처럼, 신청과 당첨은 서로 달라요.", ""], ["도판 자리", "[도5-2] 제안 도판", "5-2"], ["소제목", "1) 청약은 왜 필요할까요?", ""], ["본문", "새로 지어지는 아파트는 원하는 사람이 아주 많아요. 특히 인기 있는 지역의 아파트는 지어지는 수보다 훨씬 더 많은 사람이 “나 사고 싶어요!” 하고 신청하죠. 하지만 모든 사람에게 집을 줄 수는 없으니까, 누가 먼저 그 집을 살 수 있을지를 정하는 방법, 바로 그것이 ‘청약 제도’예요.", ""], ["본문", "신청 자격과 당첨자를 정하는 방식은 주택과 공급 유형에 따라 달라요. 점수가 높은 순서로 뽑기도 하고, 추첨하기도 하지요. 흔한 선분양 아파트의 흐름은 ‘청약 신청 → 당첨자 선정과 자격 확인 → 분양계약·대금 납부 → 공사 완료 → 입주’예요. 집이 다 지어진 뒤에야 처음 계약하는 것은 아니에요.", ""], ["소제목", "2) 청약 통장, 왜 중요할까요?", ""], ["본문", "청약에 참여하려면 먼저 청약 통장이라는 특별한 통장을 만들어야 해요.이 통장에 돈을 넣으며 가입 기간과 납입 횟수를 쌓아 청약 자격을 갖춰요. 민영주택의 가점제에서는 통장에 가입한 기간이 점수의 한 항목이 되고, 국민주택에서는 넣은 횟수나 인정받은 금액이 당첨자를 정하는 기준이 되기도 해요. 그래서 청약 통장은 단순한 저금통장이라기보다, 새 집을 신청할 때 쓰이는 ‘응모 자격’에 가깝다고 생각하면 이해하기 쉬워요.", ""], ["소제목", "3) 청약 통장에서 알아둘 것", ""], ["본문", "청약 통장은 이 통장을 다루는 여러 은행에서 은행에서 만들 수 있어요. 보통 ‘주택청약종합저축’이라는 이름으로 판매되고 있고, 은행 창구나 모바일 앱을 통해 가입할 수 있어요.", ""], ["본문", "주택청약종합저축은 일반적으로 한 달에 2만~50만 원을 넣을 수 있지만, 국민주택에서 한 달 납입액으로 인정하는 한도는 25만 원이에요. 넣을 수 있는 돈과 청약에 인정되는 돈이 다를 수 있는 것이죠.", ""], ["본문", "미성년자도 법정대리인의 도움을 받아 가입할 수 있어요.", ""], ["본문", "미성년 때의 가입 기간과 납입 횟수에도 인정 한도가 있어요. 현재는 최대 5년·60회가 기준이고, 2024년 이전 기간에는 별도의 경과 규정이 적용돼요. 아주 어릴 때부터 가입했다고 그 시간이 모두 무제한으로 인정되는 것은 아니에요.", ""], ["본문", "통장을 만들지, 매달 얼마를 넣을지는 가족의 형편과 다른 저축 계획도 함께 생각할 일이에요. 이 책에서는 상품을 서둘러 고르기보다, 제도마다 기회를 나누는 기준이 다르다는 점을 알아두면 충분해요.", ""], ["소제목", "민영주택 일반공급 가점제의 세 가지 기준 (84점 만점)", ""], ["도판 자리", "[도5-3] 가점제 표 — 표 스타일로 조판(시안: 도5-3_가점제표_v1)", "5-3"], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "이 표는 가점제의 큰 틀을 보여 줘요. 실제 점수 계산에는 배우자의 통장 가입 기간 반영 등 세부 규정이 있어요. 모든 주택이 이 표로 당첨자를 정하지는 않고, 추첨제나 다른 순위 기준, 특별공급도 있답니다. 청약 제도는 정책에 따라 자주 바뀌기 때문에, 실제로 준비할 때는 은행과 청약 관련 공공 안내에서 그해의 최신 기준을 꼭 확인해야 해요.", ""], ["본문", "청약에서 중요한 것은 그 주택의 ‘입주자모집공고’예요. 신청 대상, 자격을 판단하는 날짜, 당첨 방식, 가격과 납부 일정이 담겨 있어요. 경쟁률 기사와 모집공고는 알려 주는 정보가 서로 달라요.", ""], ["본문", "###", ""], ["소소제목", "4) 뉴스에서 청약이라는 말이 보이면?", ""], ["본문", "뉴스에서 “청약 경쟁률이 100:1”이라는 말이 나오면, 모집한 집 수에 비해 신청 건수가 100배라는 뜻이에요. 10집을 모집하는 데 1,000건이 신청되었다면 100 대 1이지요.또 “청약 당첨 가점 커트라인이 70점”이라는 기사는, 그 주택형의 가점제 물량에서 당첨된 사람 가운데 가장 낮은 점수가 70점이었다는 뜻이에요.(추첨이나 특별공급으로 당첨된 사람은 이 점수와 상관이 없어요) 이처럼 청약 경쟁률이나 가점 커트라인은 그 아파트가 얼마나 인기 있는지 보여주는 중요한 지표랍니다.", ""], ["본문", "경쟁률을 보면 관심이 많이 모였다는 사실을 알 수 있어요. 그래서 청약은 단순히 집을 신청하는 절차를 넘어서, 부동산 시장의 분위기와 흐름을 읽는 중요한 신호가 되기도 한답니다.", ""], ["본문", "하지만 그 숫자만으로 집의 품질, 실제 계약한 사람 수, 앞으로의 가격까지 알 수는 없어요.", ""], ["절 제목", "용도지역, 도시계획, 그리고 재건축·재개발 이야기 : 우리 동네 변신의 비밀", ""], ["본문", "우리가 살고 있는 도시와 동네는 가만히 멈춰 있는 것이 아니라, 끊임없이 변하고 있어요. 새로운 건물이 들어서고, 도로가 생기고, 공원이 만들어지고, 때로는 오래된 건물이 철거되기도 하죠. 이런 변화들은 우연히 일어나는 게 아니라, 대부분 ‘도시계획’이라는 큰 그림 아래에서 이루어져요.", ""], ["본문", "도시계획은 땅과 시설을 어떻게 배치하고 도시를 어떤 방향으로 가꾸어 갈지 정하는 계획이에요. 긴 안목의 방향을 제시하는 계획도 있고, 땅의 이용 규칙을 구체적으로 정하는 계획도 있지요. 계획에 등장한 시설이 모두 바로 공사를 시작하는 것은 아니에요.", ""], ["본문", "그럼, 이제 도시계획과 관련된 주요 용어들을 함께 살펴볼까요?", ""], ["소제목", "1) 용도지역", ""], ["본문", "땅을 어떤 용도로 이용하고 어느 정도 규모의 건물을 지을지 정하는 기본 구분을 ‘용도지역’이라고 해요. 우리나라 땅은 크게 도시지역·관리지역·농림지역·자연환경보전지역으로 나뉘어요.", ""], ["본문", "이 가운데 도시지역을 다시 나눈 대표적인 네 종류를 볼까요?", ""], ["본문", "① 주거지역: 사람들이 살 수 있도록 아파트나 주택을 지을 수 있는 곳", ""], ["본문", "② 상업지역: 가게, 음식점, 사무실 같은 상업 시설을 지을 수 있는 곳", ""], ["본문", "③ 공업지역: 공장 등 산업 시설을 지을 수 있도록 허용된 곳", ""], ["본문", "④ 녹지지역: 산, 공원, 농지 등 자연을 보전하고 도시 환경을 쾌적하게 유지하기 위한 곳", ""], ["본문", "각 지역에서는 지을 수 있는 건물의 종류와 규모에 서로 다른 규칙을 적용해요. 용도지역이 바뀌면 그 땅을 이용하는 방식도 달라질 수 있어요. 예를 들어, 뉴스에서 “○○지역이 상업지역으로 바뀌었다”라는 소식이 들리면, “저 동네는 앞으로 더 높은 건물이나 쇼핑몰이 들어설 수 있겠구나!” 하고 이해하면 돼요.", ""], ["도판 자리", "[도5-4] 〈도해〉 가상의 작은 도시 지도에 용도지역을 색으로 칠한 그림. 주거·상업·공업·녹지지역을 서로 다른 색으로…", "5-4"], ["소제목", "2) 재건축", ""], ["본문", "도로 같은 기반시설은 비교적 갖추어져 있지만 건물이 낡거나 불량한 곳에서 주거환경을 개선하는 대표적인 사업이 재건축이에요. 오래된 아파트를 허물고 새로 짓는 모습을 떠올리면 쉬워요. 다만 일정한 나이가 되었다고 자동으로 시작되지는 않아요. 주민 동의와 여러 인가 절차를 거쳐야 하고, 법에서 정한 재건축진단도 필요해요.", ""], ["소제목", "3) 재개발", ""], ["본문", "재개발은 기반시설이 부족하고 낡은 건물이 모인 지역 등을 정비하는 사업이에요. 좁은 길과 상하수도, 공원, 건물을 함께 손볼 수 있어요. 어느 범위를 어떻게 바꾸는지, 비용은 누가 부담하는지, 주민과 가게는 어디로 옮기는지 함께 정해야 해요.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "재건축과 재개발을 구분할 때 흔히 \"재건축은 건물만 새로 짓는 것, 재개발은 동네 전체를 새로 만드는 것\"이라고 외워요. 틀린 말은 아니지만, 이렇게만 알고 있으면 실제 사업을 오해하기 쉬워요. 두 사업을 구분하려면 '기반시설'이 어떤 상태인지를 살펴봐야 해요. 기반시설이란 도로, 상하수도, 공원, 주차장처럼 사람들이 살아가는 데 꼭 필요한 바탕 시설을 말해요. 도로나 상하수도는 그런대로 잘 갖춰져 있는데 건물만 낡았다면 재건축을 해요. 반면 골목이 너무 좁아 소방차가 들어가기 어렵고, 하수도나 공원 같은 시설이 부족한 동네라면 건물과 함께 기반시설까지 새로 갖춰야 하니 재개발을 하지요. 즉, 재건축은 '낡은 집을 새 집으로 바꾸는 일'에 가깝고, 재개발은 '살기 불편한 동네를 살기 좋은 동네로 바꾸는 일'에 가까워요. 그래서 재개발은 공공의 이익을 위한 성격이 더 강하답니다. 그런데 두 사업에는 공통점이 있어요. 공사를 하는 동안 원래 살던 사람들이 다른 곳으로 이사해야 한다는 거예요. 집주인은 공사가 끝나면 새 집으로 돌아올 수 있지만, 세 들어 살던 사람들은 사정이 달라요. 새로 지은 집은 전세금이나 월세가 크게 오르는 경우가 많아서, 다시 돌아오기 어려울 때가 많거든요. 동네에서 오랫동안 가게를 꾸려 온 사람들도 마찬가지예요. 단골손님이 있던 자리를 떠나 처음부터 다시 시작해야 하지요. 그래서 재개발에서는 정해진 날짜 전부터 살거나 장사하던 세입자에게 이사 비용이나 임대주택에 들어갈 기회를 주고, 장사를 못 하게 된 만큼 보상하도록 법으로 정해 두었어요. 재건축은 이런 보상이 법으로 정해져 있지 않아 세입자가 더 어려움을 겪기도 해요. 동네를 새로 짓는 일에서 중요한 것은 번듯한 건물만이 아니에요. 그곳에 살던 사람들의 생활이 끊기지 않고 이어질 수 있도록 하는 일도 함께 생각해야 한답니다.", ""], ["도판 자리", "[도5-5] 〈비교 도해〉 왼쪽 ‘재건축’: 도로와 상하수도는 갖춰졌는데 건물이 낡은 아파트 → 같은 자리의 새 아파트.…", "5-5"], ["소소제목", "뉴스가 다르게 보이기 시작해요!", ""], ["본문", "이제 여러분은 뉴스나 신문에 나오는 부동산 기사를 전보다 훨씬 더 쉽게 이해할 수 있을 거예요. 예전에는 “용도지역 변경”, “재개발 추진”, “재건축 승인” 같은 말이 어렵고 낯설게 느껴졌다면, 지금은 “아! 이 동네가 앞으로 바뀌겠구나” 같은 생각이 자연스럽게 떠오를 거예요. 예를 들어 “△△아파트 재건축 승인”이라는 기사를 보면 “어느 단계의 승인일까? 공사까지 남은 절차는 무엇일까?” 하고, “○○구 재개발 본격화”라는 뉴스에서는 “살던 사람과 가게는 어디로 옮기고, 어떤 대책이 있을까?” 하고 물을 수 있게 돼요. 단어를 알면 뉴스가 알려 주는 것과 알려 주지 않는 것이 함께 보이기 시작해요.", ""], ["절 제목", "블록으로 이해하는 두 비율 : 건폐율과 용적률", ""], ["본문", "“재건축 사업성이 좋아졌다”는 말은 비용과 수입을 따져 사업을 진행할 여건이 나아졌다는 뜻이에요. 뉴스에서 그 근거로 자주 나오는 두 비율이 건폐율과 용적률이에요. 바닥에 블록을 놓고 위로 쌓는 모습을 상상해 보세요.", ""], ["소제목", "1) 건폐율이란? : 땅 위에 건물이 얼마나 올라갈 수 있을까?", ""], ["본문", "건폐율은 ‘대지 면적에 대한 건축면적의 비율’이에요. 땅 위에 건물이 얼마나 면적을 차지할 수 있는지를 나타내죠. 여기서는 단순한 직육면체 건물을 위에서 내려다본 넓이를 건축면적이라고 생각해 보아요. 100㎡ 땅에 건폐율 한도가 50%라면 건축면적은 최대 50㎡예요. (실제 건축면적의 계산에는 돌출 부분 등 별도의 법적 기준이 있습니다.)", ""], ["본문", "건폐율은 건물이 땅을 얼마나 덮는지 이해하는 데 도움이 돼요. 남는 공간에는 통로나 조경 공간 등이 놓일 수 있어요.", ""], ["본문", "도시계획에서는 용도지역별로 건폐율의 최대치를 법으로 정해두고 있는데요, 이건 도시의 쾌적함을 지키고, 화재나 재난 발생 시 대피 공간을 확보하기 위한 안전장치이기도 하답니다.", ""], ["소제목", "2) 용적률이란? : 여러 층의 넓이를 더해 보자", ""], ["본문", "용적률은 ‘대지 면적에 대한 용적률 산정용 연면적의 비율’이에요. 땅의 크기에 비해 건물을 얼마나 높이, 얼마나 크게 지을 수 있는지를 나타내요. 쉽게 생각하면, 계산에 포함되는 각 층의 바닥 넓이를 더해 땅의 넓이와 비교하는 것이에요. 지하층 등 일부 면적은 계산에서 빠져요. 이 장의 예에서는 모든 층이 계산에 포함된다고 해 볼게요. 100㎡ 땅에 50㎡씩 4층을 쌓으면 합계 200㎡, 용적률은 200%예요.", ""], ["본문", "같은 땅에 40㎡씩 5층을 쌓아도 합계는 200㎡예요. 용적률은 똑같이 200%지만 건폐율은 각각 50%, 40%로 달라지죠. 용적률이 곧 층수나 높이는 아니라는 뜻이에요. 실제로는 높이와 일조 등 다른 규칙도 함께 지켜야 해요.", ""], ["본문", "용적률이 낮으면 같은 땅에도 지을 수 있는 건물의 전체 넓이가 작아서, 주택가처럼 여유롭고 조용한 분위기를 만들 수 있어요. 반면, 용적률이 높으면 더 많은 바닥 면적을 지을 수 있어서, 도심의 고층 아파트나 오피스 건물처럼 밀집된 풍경이 생기게 되죠. 이 용적률도 용도지역에 따라 다르게 정해져 있어요. 예를 들어, 상업지역은 주거지역보다 용적률 상한이 높아서 같은 넓이의 땅에 더 많은 바닥 면적을 지을 수 있어요. 다만 앞에서 본 것처럼 용적률이 곧 높이는 아니어서, 주거지역에도 고층 아파트가 들어설 수 있어요. 이처럼 용적률은 도시의 모습과 분위기를 결정짓는 중요한 기준 중 하나예요.", ""], ["소제목", "3) 재건축과 재개발이 잘될지 가늠하는 숨은 열쇠!", ""], ["도판 자리", "[도5-6] 〈블록 도해〉 두 대지는 모두 100㎡. A는 층마다 50㎡인 4층 건물로 건폐율 50%·용적률 200%, …", "5-6"], ["본문", "재건축과 재개발의 사업성을 판단할 때 꼭 따져 봐야 할 두 가지가 있어요. 바로 용적률과 건폐율이에요. 용적률은 땅 넓이에 비해 건물의 모든 층 바닥 면적을 합친 크기가 얼마나 되는지를, 건폐율은 땅 넓이에 비해 건물이 땅을 얼마나 덮고 있는지를 나타내요.", ""], ["본문", "재건축과 재개발의 사업성을 따질 때 먼저 보는 것 가운데 하나는 같은 땅에 집을 얼마나 더 지을 수 있느냐예요. 그래야 새로 지은 집 가운데 일부를 원래 집주인(조합원)에게 배정하고, 남는 집을 팔아 공사비를 마련할 수 있거든요. 이렇게 이익이 남을 수 있는지를 보고 \"사업성이 있다\"고 해요. 그 열쇠가 바로 용적률인데, 여기서 눈여겨볼 것은 용적률의 '차이'예요. 지금 지어진 건물의 용적률과 새로 허용되는 용적률의 차이가 클수록 더 지을 수 있는 면적이 늘어나고, 그만큼 팔 수 있는 집도 많아지지요. 그래서 기존 용적률이 이미 높은 아파트는 새로 늘릴 면적이 적어 사업성이 떨어질 수 있어요. 무조건 '용적률이 높으면 좋다'고 말할 수 없는 이유예요.", ""], ["본문", "건폐율도 함께 볼 수 있어요. 새 아파트 단지는 보통 법에서 허용하는 한도보다 건폐율을 훨씬 낮게 지어요. 건물 사이를 넓게 띄우고 남는 땅에 조경과 산책로를 두면 햇빛과 바람이 잘 들고 사생활도 지키기 쉽기 때문이에요. 그래서 재건축 뉴스에서 사업성을 따질 때는 건폐율보다 용적률과 층수 규제가 더 자주 등장해요.", ""], ["본문", "하지만 사업성이 이 두 비율만으로 정해지는 것은 아니에요. 공사비는 얼마나 드는지, 새 집을 얼마에 팔 수 있는지, 주민이 따로 내야 할 돈은 얼마인지, 공사하는 동안 이사하는 데 드는 비용은 얼마인지, 그리고 주민들이 사업에 동의하는지까지 함께 따져야 해요. 또 용적률을 더 받는 대신 도로나 공원 같은 공공시설, 또는 땅의 일부를 지방자치단체에 내놓는 조건이 붙기도 하는데, 이 비용도 계산에 넣어야 하지요.", ""], ["본문", "그러니 뉴스에서 \"용적률 완화\"나 \"건폐율 규제 변경\" 같은 말이 나오면, '저 동네에 집을 더 많이, 더 잘 지을 수 있게 되어 사업성이 좋아질 수도 있겠구나' 하고 이해하면 돼요. 다만 실제로 사업이 잘될지는 여러 조건을 함께 봐야 알 수 있답니다.", ""], ["절 제목", "개발 소식은 누구에게나 호재일까?", ""], ["본문", "뉴스를 보다 보면 재건축 이야기와 함께 ‘개발호재(開發好材)’라는 말도 자주 등장해요. ‘개발’은 뭔가를 새롭게 만들거나 발전시키는 것을 뜻하고, ‘호재’는 좋은 재료나 반가운 소식을 의미해요. 그러니까 개발호재란, 그 동네에 앞으로 좋은 변화가 생길 거라는 소식을 말해요.", ""], ["본문", "다음은 뉴스 읽기 연습을 위해 만든 가상 제목이에요. 어떤 변화가 기대되고, 무엇을 더 확인해야 할지 생각해 보세요.", ""], ["본문 삽입", "“○○동 지하철역 신설 계획 발표… 주민 기대 높아져”", ""], ["본문 삽입", "“새 종합병원 건립 추진… 진료까지 걸리는 시간 줄어들까?”", ""], ["본문 삽입", "“○○지구 기업 유치 협의… 일자리 확대 기대”", ""], ["본문 삽입", "“○○동 도시재생 사업 시작… 골목과 생활시설 개선”", ""], ["본문", "이런 변화가 생기면 동네 환경이 더 좋아지고, 사람들이 그곳에서 살고 싶어져요. 그러면 자연스럽게 집값도 오를 가능성이 높아지죠. 그래서 부동산 뉴스는 이런 변화를 흔히 ‘호재’라고 불러요. 다만 같은 개발도 집주인에게는 가격 상승의 기대가 되지만, 세입자나 오래된 가게에는 임대료 상승과 이주의 부담이 될 수 있어요. 또 하나 주의할 점이 있어요. 뉴스에서 “여기에 지하철역이 들어온대요!” 같은 말이 들리더라도, 실제로는 아직 계획이 확정되지 않았거나 몇 년씩 미뤄지는 경우도 많아요. 그래서 그런 소식을 들었다고 해서 그대로 믿기보다는, 실제 진행 상황이나 정부의 공식 발표를 잘 살펴보는 태도가 중요해요.", ""], ["본문", "한편, 도시재생은 지역의 생활환경과 경제·공동체를 되살리는 폭넓은 일을 뜻해요. 건물을 허무는 재개발과 같은 뜻은 아니에요.", ""], ["본문", "‘호재’라는 말을 만나면 누구에게 어떤 점이 좋아지는지, 불편이나 부담은 누구에게 생기는지 함께 물어보세요.", ""], ["절 제목", "모델하우스 : 진짜 집이 아니라고요?", ""], ["본문", "새 집을 짓기 전에, 사람들이 실제로 어떤 집을 사게 될지 보여 주려고 만든 공간이 있어요. 바로 '모델하우스' 또는 '견본주택'이라고 불리는 곳이에요. 멋진 조명, 예쁘게 꾸민 아이 방, 최신형 냉장고와 식기세척기가 들어선 주방까지, 안에 들어가 보면 \"와, 나도 이런 집에 살고 싶다!\"는 생각이 절로 들 만큼 근사하지요.", ""], ["본문", "그런데 꼭 기억해야 할 점이 있어요. 견본주택에서 보이는 것이 실제 집에 모두 들어가는 것은 아니라는 거예요. 조명이나 붙박이장, 벽 마감재, 주방 설비 가운데에는 따로 돈을 내야 하는 '유상 옵션'이 있고, 분위기를 내려고 들여놓은 전시용 가구와 장식품도 있어요. 모델하우스에서 본 고급 조명이나 욕실 인테리어가 당연히 포함되는 줄 알고 계약했다가, 입주한 뒤에야 차이를 알고 속상해하는 사람도 있답니다. 그래서 어떤 것이 기본이고 어떤 것이 선택인지, 견본주택에 붙은 표시와 계약 내용을 함께 확인해야 해요.", ""], ["본문", "모델하우스는 사람들이 사고 싶은 마음이 들도록 섬세하게 꾸민 공간이기도 해요. 작은 소파와 유리 테이블을 놓으면 방이 더 넓어 보이고, 아이 방 책상에 책과 포근한 조명을 두면 공부가 잘될 것처럼 느껴지지요. 거실에 은은한 향기가 퍼지기도 해요. 이런 연출은 모두 \"여기서 살면 우리 가족도 행복할 것 같아!\" 하는 기분이 들게 하려는 거예요. 요즘엔 호텔처럼 꾸민 드레스룸이나 카페 같은 주방이 사진 명소가 되기도 해요. 그러니 분위기에 푹 빠지기보다, 집 자체와 전시를 위한 연출을 구분해서 보는 눈이 필요해요.", ""], ["본문", "견본주택에서 확인하기 어려운 것도 있어요. 바로 창밖 풍경과 햇빛이에요. 같은 구조의 집이라도 실제로 몇 동 몇 호인지, 어느 방향을 보고 있는지, 주변에 어떤 건물이 있는지에 따라 전망과 햇빛이 드는 정도가 크게 달라지거든요.", ""], ["본문", "아무리 예쁘고 멋져 보여도, 모델하우스는 어디까지나 '보여 주기 위한 집'이에요. \"와, 예쁘다!\" 하고 감탄한 다음에는 질문을 하나 더 해 보세요. \"이것도 기본으로 포함되나요?\" 이 질문 하나가 실제로 받게 될 집과 전시된 공간의 차이를 알려 줄 수 있어요.", ""], ["절 제목", "신기한 부동산 이야기: 모델하우스의 역사와 세계 속 재밌는 집 이야기", ""], ["본문", "집을 짓기 전에 미리 보여 주는 방법은 크게 두 가지예요. 집을 작게 줄여 만든 건축 모형과, 사람이 직접 들어가 생활공간을 살펴보는 견본주택이지요. 모형으로는 건물의 전체 모습과 배치를, 견본주택으로는 방과 주방의 크기나 마감재를 확인할 수 있어요.", ""], ["본문", "건축 모형의 역사는 수백 년 전으로 거슬러 올라가요. 르네상스 시대 이탈리아에서는 큰 건물을 짓기 전에 정교한 모형을 만들어 설계를 확인했어요. 이때 모형은 무언가를 팔기 위한 것이 아니라, 제대로 지을 수 있는지 미리 따져 보기 위한 도구였지요.", ""], ["본문", "사람이 들어가 보는 견본주택이 널리 퍼진 것은 20세기 미국에서였어요. 집을 사려는 중산층이 크게 늘자, 박람회나 새로 개발한 주택 단지에 실제 집을 꾸며 놓고 \"이런 집에 살고 싶지 않나요?\" 하고 보여 주기 시작했어요. 이렇게 견본주택은 집을 팔기 위한 공간으로 자리 잡게 되었답니다.", ""], ["소제목", "1) 한국 견본주택의 시작", ""], ["본문", "우리나라 아파트 견본주택의 출발로는 1969년 한강맨션 사례가 알려져 있어요. 당시에는 아파트가 아직 낯선 집이어서, 사람들이 \"도대체 그런 집 안은 어떻게 생겼을까?\" 하고 궁금해했지요. 견본주택은 이런 사람들에게 아파트의 생활공간을 직접 보여 주는 역할을 했어요. 이후 1971년 여의도 시범아파트처럼 큰 아파트 단지가 들어서면서 견본주택도 점점 흔한 풍경이 되었어요.", ""], ["본문", "시간이 흐르며 견본주택은 집을 구경하는 곳을 넘어, 건설사의 브랜드를 알리는 홍보 공간이 되기도 했어요. 2000년대에는 인터넷으로 집 내부를 보여 주는 '사이버 모델하우스'가 등장했고, 코로나19 무렵부터는 화면을 돌려 가며 집 구석구석을 살펴보는 온라인 견본주택이 크게 늘었어요. 하지만 방식이 달라져도 꼭 던져야 할 질문은 같아요. \"실제 집과 무엇이 같고, 무엇이 다를까?\"", ""], ["소제목", "2) 세계 속 재밌는 집 이야기", ""], ["소소제목", "■ 세계에서 가장 큰 개인 주택 ― 인도의 '안틸리아(Antilia)'", ""], ["본문", "인도 뭄바이에 있는 안틸리아는 세계에서 가장 큰 개인 주택으로 자주 소개되는 집이에요. 인도 최고 부자로 꼽히는 무케시 암바니 가족이 사는 이 집은 27층 규모로, 집이라기보다 호텔이나 백화점에 가까운 모습이지요. 안에는 168대를 세울 수 있는 주차 공간과 헬리콥터 착륙장, 극장, 수영장, 헬스장이 있고, 무더운 인도에서도 인공 눈을 뿌려 겨울 풍경을 즐길 수 있는 '눈의 방'까지 있다고 알려져 있어요. 이 집을 관리하는 직원만 수백 명에 이른다고 해요. 집 한 채에 도시의 여러 시설이 모인 셈이죠. 이렇게 큰 공간을 유지하려면 어떤 일과 자원이 필요할까요?", ""], ["소소제목", "■ 두 건물 사이에 숨은 집 ― 폴란드의 '케레트 하우스'", ""], ["본문", "폴란드 바르샤바의 케레트 하우스는 두 건물 사이 좁은 틈에 만든 작은 생활·작업 공간이에요. 내부 폭은 가장 좁은 곳이 72cm, 가장 넓은 곳이 122cm로, 사람 한 명이 겨우 지나갈 정도예요. 그런데도 그 안에 작은 침대와 책상, 주방과 욕실이 모두 들어 있어요. 이스라엘 작가 에트가르 케레트의 이름을 딴 이 집은 작가나 예술가들이 며칠씩 머물며 창작하는 실험적인 공간으로 쓰였어요. 좁은 공간도 창의적으로 쓰면 생활이 가능하다는 걸 보여 주지만, 누구나 오래 살기에 충분한 집의 기준을 보여 주는 것은 아니에요.", ""], ["소소제목", "■ 수학과 종이접기에서 얻은 집 ― 호주의 '클라인 보틀 하우스'", ""], ["본문", "호주의 클라인 보틀 하우스는 '클라인 병'이라는 수학적 형태와 종이접기에서 아이디어를 얻은 집이에요. 클라인 병은 안과 밖의 구분이 없는 신기한 곡면이에요. 실제 집에는 안뜰을 중심으로 여러 층을 잇는 큰 계단이 있고, 접힌 듯한 벽과 지붕이 집 전체를 감싸고 있어요. 수학의 모양을 그대로 옮기기보다, 사람이 생활할 수 있도록 다시 설계한 집이지요. 여러분이라면 어떤 도형에서 집의 아이디어를 얻고 싶나요?", ""], ["본문", "크고 독특한 집이 반드시 모두에게 편한 집은 아니에요. '누가, 얼마나 오래, 어떤 일을 하며 지내는 공간인가?'를 함께 생각해 보세요.", ""], ["도판 자리", "[도5-7] 안틸리아의 전체 모습, 케레트 하우스의 내부 폭, 클라인 보틀 하우스의 접힌 지붕과 안뜰. 사용 가능한 이미…", "5-7"], ["절 제목", "미션! 부동산 뉴스를 해석해 보자!", ""], ["본문", "문제 1) “△△지역 청약 경쟁률 역대 최고”", ""], ["본문", "알 수 있는 것: 이번 모집에 신청이 많이 몰렸어요.", ""], ["본문", "더 확인할 것: 몇 집을 모집했고 몇 건이 신청했나요? 어떤 유형의 경쟁률인가요? 실제 계약 결과도 같을까요?", ""], ["본문", "문제 2) “깡통전세 위험 커져, 세입자 주의 필요”", ""], ["본문", "알 수 있는 것: 집을 처분해도 보증금을 충분히 돌려받지 못할 위험이 커졌다는 뜻이에요.", ""], ["본문", "더 확인할 것: 어떤 지역과 집을 다뤘나요? 집값뿐 아니라 먼저 갚아야 할 빚도 살폈나요? 피해를 줄일 제도와 지원은 무엇인가요?", ""], ["본문", "문제 3) “○○지역, 용도지역 변경 추진… 공업지역에서 주거지역으로”", ""], ["본문", "알 수 있는 것: 땅의 이용 규칙을 바꾸는 일을 추진 중이에요.", ""], ["본문", "더 확인할 것: 변경이 확정됐나요? 바뀌는 범위는 어디인가요? 건물을 짓는 별도 절차도 진행됐나요?", ""], ["본문", "문제 4) “□□재건축 단지, 용적률 완화로 사업성 좋아져”", ""], ["본문", "알 수 있는 것: 허용되는 건물 면적이 늘어나 비용을 마련할 여지가 커졌다는 취지예요.", ""], ["본문", "더 확인할 것: 공사비와 주민 부담은 얼마인가요? 어떤 조건이 붙었나요? 용적률 하나만으로 사업의 성공을 확정할 수는 없어요.", ""], ["본문", "기사의 단어를 이해하고 나면 질문이 더 구체적이 돼요. 제목에 답이 모두 들어 있지 않다는 사실을 알아차린 것만으로도 뉴스 읽기가 한 걸음 깊어졌어요.", ""], ["본문", "여러분도 부동산과 관련된 뉴스를 보면 하나를 골라서 써 보세요. ‘제목으로 알 수 있는 사실’ 한 문장과 ‘더 확인하고 싶은 질문’. 뉴스의 비밀 코드를 푸는 열쇠는 어려운 단어를 줄줄 외우는 데 있지 않았어요. 누가 무엇을 하는지, 지금 어느 단계인지, 어떤 정보가 빠져 있는지 질문하는 데 있지요.", ""], ["절 제목", "생각해볼 질문", ""], ["번호 목록", "1. 청약 신청, 당첨, 분양계약은 어떻게 다른가요? 세 낱말을 순서대로 놓고 설명해 보세요.", ""], ["번호 목록", "2. 같은 땅에 용적률이 같은 두 건물이 있어요. 층수와 건폐율도 반드시 같을까요? 블록 그림으로 보여 주세요.", ""], ["번호 목록", "3. 뉴스에 “개발 계획 발표”라고 쓰여 있어요. 공사가 시작되었다고 말하려면 무엇을 더 알아봐야 할까요?", ""], ["절 제목", "조금 더 깊게 생각해보기", ""], ["질문 제목", "□ 부동산 용어와 도시 변화 이해", ""], ["본문", "뉴스에 자주 등장하는 부동산 관련 용어(예: 신탁, 청약, 용도지역, 재건축, 개발호재, 용적률, 건폐율 등) 중 세 가지 이상을 선택하여 설명하고, 이러한 용어들이 한국 사회의 부동산 시장 동향 및 도시 변화를 이해하는 데 어떻게 도움을 주는지 논하시오. 특히 ‘재건축’과 관련하여 용적률과 건폐율 개념을 설명하고, 이 두 비율이 사업성에 어떤 영향을 주는지 구체적으로 서술하시오.", ""], ["질문 제목", "□ 공인중개사와 중개보조원의 역할 비교", ""], ["본문", "공인중개사와 중개보조원의 역할을 비교 설명하고, 안전한 부동산 거래를 위해 공인중개사의 역할이 왜 중요한지 논하시오. 또한, 무자격자(자격증 없는 사람)가 중개 행위를 했을 때 생길 수 있는 문제점에 대해서도 함께 설명해 보세요.", ""], ["질문 제목", "□ 모델하우스의 기능과 한계", ""], ["본문", "모델하우스가 주는 긍정적인 기능과 한계점을 분석해 보세요. 소비자가 모델하우스를 현명하게 활용하여 실제 계약에서 발생할 수 있는 위험을 줄이는 방법은 무엇일까요?", ""], ["질문 제목", "□ 우리 동네의 용도지역과 개발호재 예측", ""], ["본문", "여러분이 사는 동네의 용도지역을 인터넷으로 조사하고, 용적률과 건폐율 제한이 어떻게 설정되어 있는지 확인해 보세요. 그 제한이 우리 동네의 건물 모양, 높이, 분위기에 어떤 영향을 주는지 설명하고, 앞으로 그 동네에 개발호재가 생긴다면 어떤 변화가 일어날지 예측해 보세요.", ""]]}, {"key": "ch06", "num": "06", "title": "집값이 달라지면, 삶도 달라질까?", "p": [["본문", "“요즘 우리 동네 집값이 많이 올랐대.”", ""], ["본문", "“집세가 올라서 다른 동네로 이사해야 할지도 모르겠어.”", ""], ["본문", "이런 이야기를 뉴스나 어른들 대화에서 들어본 적 있나요? 처음에는 그냥 숫자 이야기처럼 들릴 수도 있지만, 사실 집값이라는 건 우리 생활과도 깊이 연결되어 있어요. 집은 가족이 함께 시간을 보내고, 공부하고, 밥을 먹고, 쉴 수 있는 소중한 공간이죠. 그래서 그 공간의 값, 즉 집값이 오르거나 내리는 일은 때로는 사람들의 기분, 생활 방식, 심지어 앞으로의 계획에도 영향을 줄 수 있어요.", ""], ["본문", "예를 들어, 집을 가진 사람은 집값이 오르면 재산의 평가액이 늘었다고 느낄 수 있어요. 하지만 집을 팔기 전에는 바로 쓸 수 있는 현금이 아니고, 세금과 대출 부담도 함께 달라질 수 있어요. 반면에 아직 집이 없는 사람들에겐 집값 상승이 부담으로 다가오기도 해요. ‘내 집 마련’이 점점 멀어지는 느낌이 들고, 전세나 월세를 사는 경우에는 집세가 올라 더 많은 돈을 내야 하기도 하거든요. 이로 인해 이사를 자주 다니게 되거나, 원하는 동네에서 살지 못할 수도 있어요.", ""], ["본문", "동네에 투자와 새로운 가게가 몰리면서 임대료가 올라, 원래 살던 주민이나 장사하던 사람이 밀려나는 현상도 생길 수 있어요. 이런 변화를 ‘젠트리피케이션’이라고 해요. 새 건물이 들어섰다는 사실만으로 동네에 사는 모두의 생활이 좋아졌다고 말하기 어려운 이유예요.", ""], ["본문", "이처럼 집값은 부동산 시장에서 오르내리는 숫자만이 아니라, 누가 어디에서 어떻게 살 수 있는지를 가늠하게 해주는 중요한 기준이기도 해요. 학교, 친구, 이웃, 통학 거리, 편의시설처럼 우리 일상과 직접 닿아 있는 요소들이 모두 주거 공간과 연결되어 있거든요.", ""], ["본문", "집값이 오르면 왜 동네가 달라지는지, 사람들의 생활이 어떻게 바뀌는지, 그리고 ‘좋은 동네’라는 말에는 어떤 조건이 숨어 있는지도 함께 살펴볼 거예요. 세상은 단순하지 않지만, 차근차근 하나씩 이해하다 보면 분명히 보이는 것들이 있어요. 우리 함께 생각해 보아요.", ""], ["절 제목", "같은 집인데 왜 어떤 동네는 더 비쌀까?", ""], ["본문", "넓이와 지은 시기가 비슷한 집인데 동네에 따라 가격이 다를 수 있어요. “방도 비슷하고 욕실 수도 같은데 왜 그럴까?” 집의 조건에는 벽 안쪽의 공간뿐 아니라, 밖으로 나갔을 때 만나는 환경도 포함되기 때문이에요.", ""], ["본문", "학교까지 걸리는 시간, 버스를 갈아타는 횟수, 아플 때 갈 병원과 쉴 공원이 집마다 다를 수 있지요. 사람들이 선호하는 위치 때문에 가격에 더해지는 부분을 ‘입지 프리미엄’이라고 부르기도 해요.", ""], ["본문", "그렇다면 어떤 동네에 많은 사람들이 살고 싶어 할까요?", ""], ["본문", "출퇴근하는 사람에게는 교통이, 돌봄이 필요한 가족에게는 가까운 돌봄 시설이 중요할 수 있어요. 학교와 도서관이 가깝고 통학로가 안전한 곳을 찾는 가족도 있어요. 밤길의 조명이나 보행로의 상태처럼 지도에서 잘 보이지 않는 조건도 생활에 영향을 줘요.", ""], ["본문", "새 지하철이나 공원에 대한 기대도 집값에 영향을 줄 수 있어요. 하지만 시설이 좋아진다고 가격이 언제나 오르는 것은 아니에요. 공급되는 집 수, 금리, 사람들의 소득과 대출 여건도 함께 작용해요. 같은 동네 안에서도 집의 상태와 거래 시기에 따라 가격은 달라질 수 있어요.", ""], ["본문", "살고 싶어 하는 사람에 비해 살 수 있는 집이 부족하면 가격이 오르는 압력이 생길 수 있어요. 다만 집값은 여러 조건이 만나는 결과예요. 비싼 가격표가 동네의 모든 장점을 설명하지도, 그곳에 사는 사람의 가치를 나타내지도 않아요.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "동네를 새롭게 만드는 데는 오랫동안 자리를 지킨 가게와 주민의 노력도 들어 있어요. 변화를 볼 때 “무엇이 새로 생겼지?”와 함께 “계속 머물기 어려워진 사람은 없을까?”도 물어보세요.", ""], ["소제목", "‘좋은 동네’는 누가 정했을까?", ""], ["본문", "여러분에게 '좋은 동네'는 어떤 곳인가요? 친한 친구와 걸어서 만날 수 있는 곳일 수도 있고, 마음껏 운동할 공간이 많은 곳일 수도 있어요. 유튜브나 TV에서 본 멋진 동네가 떠오를 수도 있지요. 그런데 문득 이런 궁금증이 들지 않나요? '좋은 동네'는 누가, 어떤 기준으로 정하는 걸까? 사실 우리가 떠올리는 좋은 동네의 기준은 눈에 보이는 시설뿐 아니라, 사람들의 생각과 정책, 이웃 관계처럼 보이지 않는 힘들이 오랜 시간 쌓여 만들어진 거예요. 그리고 여기에 '누구에게 좋은가?'라는 질문을 붙이면, 좋은 동네의 모습은 또 달라진답니다.", ""], ["소제목", "1) 사람들의 선택이 모이면", ""], ["본문", "지하철역이 가깝고 학교, 병원, 마트, 공원이 잘 갖춰진 동네라면 많은 사람이 살고 싶어 할 거예요. 안전하고 조용한 분위기, 잘 관리된 거리도 좋은 인상을 주지요. 이런 조건을 갖춘 동네는 점점 더 많은 사람의 선택을 받고, 결국 '살기 좋은 곳'이라는 인식이 생겨요. 그런데 사람마다 필요한 것은 조금씩 달라요. 병원에 자주 가야 하는 사람은 진료받기 쉬운 곳을, 악기를 배우는 사람은 연습할 공간이 있는 곳을, 휠체어를 타는 사람은 턱이 없는 길을 먼저 찾을 거예요. 그래서 다양한 사람이 필요한 시설을 이용할 수 있는지가 동네를 살펴보는 중요한 기준이 돼요.", ""], ["소제목", "2) 그 동네에 대한 '이미지'", ""], ["본문", "\"저 동네는 학군이 좋아서 다들 가고 싶어 한대.\"", ""], ["본문", "\"광고에서 보니까 모든 게 좋아 보이던데?\"", ""], ["본문", "어떤 동네는 시설보다 사람들 머릿속의 이미지 덕분에 '좋은 동네'로 여겨지기도 해요. 광고와 방송, 사람들의 평판이 그 이미지를 만들고, 유명인이 산다거나 드라마에 자주 나온다면 그 인식은 더 강해지지요. 때로는 이미지가 실제 모습보다 더 큰 영향을 주기도 해요. 하지만 멋진 화면에 비친 모습과 실제 생활은 다를 수 있어요. 버스는 자주 오는지, 밤길은 안전한지는 직접 가 봐야 알 수 있거든요. 그러니 이미지가 어디에서 왔는지, 무엇을 보여 주고 무엇을 빼놓았는지도 따져 보아요.", ""], ["소제목", "3) 정책도 동네의 모습을 바꿔요", ""], ["본문", "정부나 지방자치단체가 세우는 도시 계획, 지하철이나 도로 같은 교통망, 재개발이나 재건축 사업은 동네의 미래를 크게 바꿔요. \"이곳에 새 도서관이 들어선대!\", \"지하철 노선이 연장된대!\" 같은 소식이 알려지면 그 지역은 더 살기 좋아질 거라는 기대를 모으고, 조용하던 동네에 사람들의 관심이 몰리지요. 그런데 이런 결정은 반대편의 모습도 만들어요. 편리한 시설이 특정 지역에만 모이면, 다른 지역 사람들은 같은 서비스를 누리려고 더 많은 시간과 비용을 들여야 하거든요. 도서관을 어디에 세울지, 버스가 어느 길로 다닐지 같은 공공의 결정이 모두에게 공평한지 살펴봐야 하는 이유예요.", ""], ["소제목", "4) 누가 사느냐에 따라, 이웃이 함께 만드는 일상", ""], ["본문", "동네는 그 안에 사는 사람들에 따라 분위기와 색깔이 달라져요. 가게 주인이 건네는 인사, 주민들이 함께 가꾸는 작은 화단, 서로의 아이를 돌봐 주는 모임도 모두 동네의 얼굴이지요. 시간이 지나 비슷한 취향을 가진 사람들이 모이면 카페나 서점, 작은 공방 같은 새로운 공간이 생기며 동네만의 개성이 만들어지기도 해요. 그런데 이런 변화 속에서 동네의 인기가 높아지고 집값과 가게 임대료가 오르면, 오랫동안 그 자리를 지켜 온 주민과 가게가 떠밀리듯 동네를 떠나는 일도 생겨요. 앞에서 말한 '젠트리피케이션'이에요. 새 건물이 들어서는 변화 속에서도 오래된 주민과 새로 온 주민이 함께 머물 방법을 찾는 것이 중요한 이유지요.", ""], ["본문", "'좋은 동네'는 단지 예쁜 건물이나 유명한 장소가 있는 곳만을 뜻하지 않아요. 얼마나 다양한 사람이 함께 어울려 살아가며, 그 안에서 편안함과 안전함을 느낄 수 있느냐가 더 중요한 기준이 될 수 있어요. 그러니 \"좋은 동네는 어디일까?\"를 생각할 때, \"그 동네는 어떤 삶을 담고 있을까?\", \"누구에게 좋은 동네일까?\" 하는 질문도 함께 던져 보면 어떨까요? '좋은 동네'란 결국 그 공간을 함께 살아가는 사람들이 만들어 가는 거니까요.", ""], ["절 제목", "도시 기본 계획이란? : 미래의 우리 동네를 그리는 큰 방향", ""], ["본문", "우리가 살고 있는 동네는 그냥 우연히 생긴 게 아니에요. 대부분은 누군가의 계획 아래, 조금씩 바뀌고 발전하면서 지금의 모습을 갖추게 되었죠. 그리고 앞으로도 동네는 계속 변화할 거예요. 이렇게 도시의 미래를 미리 그려보는 큰 그림을 우리는‘도시·군기본계획’(흔히 ‘도시기본계획’)이라고 불러요.", ""], ["본문", "도시·군기본계획은 도시의 기본적인 공간 구조와 장기 발전 방향을 제시하는 종합계획이에요. 주거와 교통, 환경, 공공시설 등에 관한 큰 방향을 담고, 더 구체적인 도시·군관리계획을 세우는 지침이 돼요.", ""], ["본문", "친구들과 학교 축제의 큰 방향을 먼저 정하고, 나중에 교실마다 어떤 행사를 할지 구체적으로 정하는 모습을 떠올려 보세요. 기본계획과 관리계획도 역할이 달라요. 개별 땅의 용도지역을 실제로 결정하는 것은 도시·군관리계획에서 다루는 일이에요.", ""], ["도판 자리", "[도6-1] 〈세 단계 도해〉 ①도시·군기본계획: 장기적인 공간 구조와 발전 방향 ②도시·군관리계획: 용도지역·시설 등을…", "6-1"], ["본문", "기본계획에 어떤 시설이나 개발 방향이 담겼다고 해서 바로 공사가 시작되거나 개인이 건축할 권리가 생기는 것은 아니에요. 개별 토지의 용도지역을 정하거나 도로·공원 사업을 실행하려면 도시·군관리계획, 사업계획, 예산과 인허가 같은 후속 절차가 필요해요. 뉴스에서 도시계획을 볼 때는 ‘장기 방향인지, 구체적으로 결정된 계획인지, 실제 사업 단계인지’를 구분해야 해요.", ""], ["본문", "주민의 의견을 듣는 공청회 같은 절차도 있어요. “청소년이 버스를 기다릴 곳이 필요해요”, “도서관까지 안전하게 걸어가고 싶어요”처럼 생활에서 출발한 의견을 말할 수 있어요.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "시청이나 군청 홈페이지에서 도시기본계획의 요약 자료를 찾아볼 수 있어요. 처음부터 두꺼운 보고서를 다 읽을 필요는 없어요. 우리 동네가 표시된 지도와 설명부터 살펴보세요. 내용이 조금 어려울 수 있지만, 제5장에서 배운 부동산 용어들을 떠올리면서 하나씩 살펴보면 생각보다 쉽게 이해할 수 있을 거예요.", ""], ["절 제목", "신기한 부동산 이야기 : 스타벅스와 집값, 무엇이 먼저일까?", ""], ["본문", "동네에 스타벅스가 새로 생겼어요. 비슷한 시기에 주변 집값도 올랐대요. 그러면 \"스타벅스가 집값을 올렸어!\"라고 말해도 될까요? 우리나라에도 \"스타벅스가 생기면 그 동네가 뜬다\"는 말이 있을 정도니, 한번 따져 볼 만하지요.", ""], ["본문", "미국의 부동산 데이터 회사 질로(Zillow)의 최고경영자와 수석 경제학자는 2015년에 펴낸 책 『질로 톡』에서 흥미로운 분석을 소개했어요. 1997~2014년 미국 주택의 가치가 평균 65% 오르는 동안, 스타벅스에서 약 400m 안에 있는 주택은 96%나 올랐다는 거예요. 던킨도너츠 근처 주택은 80% 올라 평균보다는 높았지만, 스타벅스 주변만큼은 아니었어요. 다만 이 결과는 특정 나라와 기간에 관찰된 비교라는 점을 기억해야 해요.", ""], ["본문", "여기서 알아 둘 개념이 있어요. 두 일이 함께 나타나는 관계를 '상관관계', 한 일이 다른 일의 원인이 되는 관계를 '인과관계'라고 해요. 함께 나타났다는 사실만으로 원인까지 밝혀지는 것은 아니에요. 스타벅스가 생겨 동네가 더 편리해졌을 수도 있지만, 반대로 스타벅스가 원래 사람이 많이 모이고 집값이 오를 만한 곳을 잘 골라 들어갔을 수도 있어요. 새로운 일자리나 교통시설이 가게 입점과 집값 양쪽에 영향을 줬을 가능성도 있지요.", ""], ["본문", "여름에는 아이스크림이 많이 팔리고 물놀이 사고도 늘어요. 그렇다고 아이스크림을 먹어서 물놀이 사고가 난다고 말할 수는 없겠지요. 더운 날씨처럼 두 일에 함께 영향을 주는 조건이 숨어 있으니까요. 마찬가지로 미국의 분석 하나만 보고 \"우리 동네에도 스타벅스가 생기면 집값이 반드시 오른다\"고 결론 내릴 수는 없어요.", ""], ["본문", "뉴스에서 \"A가 늘 때 B도 늘었다\"는 말을 만나면 좋은 연습 기회예요. A가 B의 원인인지, 반대로 B가 A의 원인인지, 아니면 다른 조건이 둘 모두에 영향을 줬는지 질문해 보세요.", ""], ["도판 자리", "[도6-2] 가운데 ‘새 카페 입점’과 ‘주변 집값 변화’를 놓는다. 옆에는 가설 세 가지를 점선으로 표시한다. ①가게가…", "6-2"], ["절 제목", "역사 속 부동산 이야기 — 맹모삼천지교를 다시 읽기", ""], ["본문", "'맹모삼천지교(孟母三遷之敎)'라는 말을 들어 본 적 있나요? 맹자의 어머니가 아들의 배움에 알맞은 환경을 찾아 세 번 거처를 옮겼다는 옛이야기에서 나온 말로, 교육 환경의 중요성을 이야기할 때 자주 인용돼요.", ""], ["도판 자리", "[도6-4] 제안 도판", "6-4"], ["본문", "맹자는 기원전 4세기 무렵 중국 전국 시대의 사상가로, 공자의 가르침을 이어받아 \"사람에게는 선한 마음의 싹이 있다\"는 성선설을 펼쳤어요. 맹자의 어머니 이야기는 맹자가 살던 때보다 200여 년 뒤인 한나라 때 쓰인 『열녀전』 같은 책에 전해져요. 그러니 실제 이사 기록처럼 읽기보다, 어떤 가르침을 전하려는 이야기인지 생각하며 읽어 보아요.", ""], ["본문", "이야기 속 어린 맹자는 무덤 근처에 살 때는 장례 치르는 모습을, 시장 근처에 살 때는 물건을 사고파는 모습을 흉내 내며 놀아요. 어머니는 마지막으로 학교 가까이로 이사하고, 맹자가 예절을 따라 하며 노는 모습을 보고서야 그곳에 머물기로 하지요. 이 이야기를 전한 사람들은 아이가 주변에서 보고 배우는 것이 중요하다고 여겼던 거예요. 그렇다고 시장에서 일하는 사람이나 그곳에 사는 아이를 낮게 볼 이유는 없어요. 시장에서도 계산과 거래, 협력처럼 배울 것이 많으니까요. 옛이야기가 강조한 가치와 오늘 우리가 생각할 가치를 구별해서 읽어야 해요.", ""], ["본문", "오늘날에도 이 이야기와 닮은 장면을 볼 수 있어요. 학교와 학원, 도서관이 가까운 이른바 '학군지'로 이사하려는 가족이 많지요. 통학 시간을 줄이고 배움의 기회를 넓히고 싶어서예요. 이런 선호 때문에 학군지의 집값이 높아지기도 하고, 아예 교육과 투자를 함께 노리는 선택으로 여기는 사람도 있어요. 하지만 특정 학군의 집값이 언제나 오르거나 경기가 나빠져도 그대로 유지된다는 보장은 없어요.", ""], ["본문", "또 비싼 동네에 산다고 저절로 공부를 잘하게 되는 것도, 그곳의 아이가 다른 동네 아이보다 더 훌륭한 것도 아니에요. 이사 비용과 부모님의 일터, 가족을 돌봐 주는 사람들과의 관계 때문에 가족마다 선택할 수 있는 범위도 다르지요. 환경의 차이를 아이나 부모의 노력 부족으로만 설명하면, 어떤 시설과 도움이 부족한지를 놓치기 쉬워요.", ""], ["본문", "사실 맹자의 어머니에게는 또 다른 이야기도 전해져요. 공부를 그만두고 돌아온 맹자 앞에서 짜던 베를 칼로 끊으며, 배움을 중간에 그만두는 것은 이렇게 짜던 천을 끊는 것과 같다고 가르쳤다는 '맹모단기지교(孟母斷機之敎)'예요. 맹자를 키운 것은 이사한 동네만이 아니라, 곁에서 함께 고민해 준 어른이었던 셈이지요.", ""], ["본문", "맹모삼천지교를 읽고 우리에게 남길 질문을 하나 골라 볼까요? \"어디로 이사해야 성공할까?\"보다 \"이사하지 않아도 잘 배우고 자라려면 우리 동네에 무엇이 필요할까?\"라는 질문은 어떨까요?", ""], ["절 제목", "새로운 부동산 용어 : 브역대신공평초를 풀어 보자", ""], ["본문", "부동산 기사나 온라인 글에서 '브역대신평초'라는 낯선 줄임말을 만날 수 있어요. 사람들이 아파트를 고를 때 자주 따지는 여섯 가지 조건을 묶은 말이에요. 여기에 공원의 '공'을 더해 일곱 가지로 말하기도 해요.", ""], ["도판 자리", "[도6-5] 제안 도판", "6-5"], ["본문", "하나씩 풀어 볼까요? '브'는 브랜드예요. 이름만 들어도 아는 대형 건설사의 아파트는 품질과 관리 면에서 높은 평가를 받는 경우가 많아요. '역'은 역세권으로, 지하철역이 걸어서 갈 만한 거리에 있다는 뜻이에요. '대'는 대단지로, 단지가 크면 편의시설이 잘 갖춰지고 관리가 체계적인 경우가 많지요. '신'은 신축, 즉 지은 지 얼마 안 되어 최신 설계가 반영된 아파트예요. '공'은 공원이 가까운 곳, '평'은 오르막이나 내리막이 없는 평지예요. 마지막 '초'는 '초품아', 곧 초등학교를 품은 아파트라는 말에서 왔어요. 아이들이 큰길을 건너지 않고 안전하게 학교에 다닐 수 있어 부모들이 선호하지요.", ""], ["본문", "일곱 글자 가운데 '역·공·평·초' 네 가지는 집이 어디에 있느냐, 곧 입지와 관련된 조건이에요. 그만큼 부동산에서 위치가 중요하다는 뜻이지요. 그런데 역이 가깝다고 해서 출퇴근이 저절로 편해지는 것은 아니에요. 내가 가려는 곳까지 한 번에 가는지, 몇 번 갈아타야 하는지도 따져 봐야 하거든요.", ""], ["본문", "무엇보다 이 말은 법으로 정한 기준도, 모든 사람에게 맞는 점수표도 아니에요. 휠체어나 유아차를 이용하는 사람에게는 경사와 보행로가, 청소년에게는 도서관과 대중교통이, 또 다른 사람에게는 임대료나 돌봄 시설이 더 중요할 수 있어요. 앞으로 이 줄임말을 만나면, 일곱 글자가 실제 생활에서 무엇을 바꾸는지, 그리고 나에게는 어떤 조건이 가장 중요한지 함께 생각해 보세요.", ""], ["절 제목", "집값이 달라지면, 삶도 달라질까? : 동네가 주는 기회, 그리고 우리가 만나는 세상", ""], ["본문", "한 동네에서 다른 동네로 이사하면 집의 위치만 달라질까요? 그렇지 않아요. 아침에 집을 나서는 시간, 친구를 만나러 가는 길, 방과 후에 들를 곳까지 달라질 수 있어요.", ""], ["본문", "어떤 동네는 지하철이나 버스가 편리해 학교에 오가기 쉽고, 어떤 동네는 큰 공원이 가까워 산책하거나 운동하기 좋아요. 도서관이나 문화센터가 가까운 동네에서는 책과 예술을 더 자주 접할 수 있고, 학교나 학원이 가까우면 배우러 오가는 시간과 비용도 줄어들지요. 이처럼 동네가 갖춘 조건에 따라 우리가 경험하는 일상과 만날 수 있는 기회가 달라져요.", ""], ["본문", "그런데 시설이 있다고 해서 누구나 쉽게 이용할 수 있는 것은 아니에요. 도서관이 지도에서는 가까워 보여도 큰 도로를 건너야 한다면 가는 길이 멀게 느껴질 수 있어요. 체육관이 있어도 이용료가 부담스럽거나 문 여는 시간이 맞지 않으면 자주 가기 어렵고요. 그래서 시설의 개수와 실제로 이용할 기회는 나누어 생각해야 해요. 걸리는 시간과 비용, 운영 시간, 계단이나 경사 같은 이동의 어려움까지 함께 살펴보아요.", ""], ["본문", "사는 동네가 어떤 기회를 더 쉽게 만나게 하거나 어렵게 만들 수는 있어요. 하지만 주소가 여러분의 능력이나 가치를 정하지는 않아요. 동네의 차이를 살피는 까닭은 친구네 동네에 순위를 매기기 위해서가 아니라, 필요한 기회를 더 고르게 나누기 위해서예요. 그래서 도시에서는 학교와 공공시설, 교통을 골고루 배치하고, 여러 지역에 공원을 만들며 생활환경을 고치려는 노력을 이어 가고 있어요.", ""], ["본문", "집값에는 이렇게 동네가 가진 여러 조건이 담겨 있어요. 이제 지도를 볼 때 시설을 나타내는 점만 보지 말고, 그 점까지 이어지는 사람들의 하루도 상상해 보세요. 같은 시설이라도 누가, 어떻게 이용하는지에 따라 의미가 달라질 거예요.", ""], ["절 제목", "미션: ‘우리 동네, 다른 동네’ 지도 비교 활동", ""], ["소제목", "1) 지도 위에 삶의 기회와 환경을 그려보자!", ""], ["본문", "우리는 모두 어떤 동네에 살고 있어요. 그런데 같은 도시 안에서도 동네마다 학교, 병원, 공원, 도서관, 문화시설 등이 얼마나 갖춰져 있는지, 또 얼마나 이용하기 쉬운지가 조금씩 달라요. 이 활동에서는 내가 사는 동네와 관심 있는 다른 동네 한 곳을 골라, 두 곳의 생활환경을 지도 위에서 비교해 볼 거예요.", ""], ["소제목", "2) 활동 방법", ""], ["본문", "① 두 동네를 고르고 지도를 준비해요.", ""], ["본문", "다른 동네는 뉴스나 인터넷에서 본 곳, 여행 가고 싶은 곳, 이사 가 보고 싶은 곳 등 어디든 좋아요. 두 지도는 같은 축척으로 맞춰야 거리를 제대로 비교할 수 있어요. 출발점은 우리 집 주소 대신 학교나 도서관 같은 공공장소로 정해요.", ""], ["본문", "(스마트폰 지도 앱이나 종이 지도를 활용해도 좋아요!)", ""], ["본문", "② 관심 있는 시설 세 종류를 골라 표시해요.", ""], ["본문", "아래에서 세 가지를 골라, 두 지도에 같은 색이나 아이콘으로 표시해 보세요.", ""], ["목록", "• 학교", ""], ["목록", "• 가까운 병원 또는 약국", ""], ["목록", "• 자주 가는 공원이나 놀이터", ""], ["목록", "• 마트, 편의점, 문구점, 식당 등 자주 가는 가게", ""], ["목록", "• 청소년이 공부하거나 모일 수 있는 곳", ""], ["목록", "• 도서관이나 체육관 등 공공시설", ""], ["본문", "③ 실제로 가는 길을 살펴봐요.", ""], ["본문", "각 동네에서 시설 한 곳을 골라, 출발점에서 가는 길을 확인해 보세요. 걸리는 시간, 건너야 할 큰길, 운영 시간, 이용료를 적어요. 확인하지 못한 정보는 추측하지 말고 '아직 모름'이라고 적어요.", ""], ["본문", "직접 걸어 볼 때는 익숙하고 안전한 길을 고르거나 어른과 함께해요. 지도로만 비교해도 충분해요.", ""], ["본문", "④ 두 동네를 비교하며 이야기해 봐요.", ""], ["목록", "• 두 동네에서 모두 편리하게 이용할 수 있는 시설은 무엇인가요? 차이가 큰 시설은요?", ""], ["목록", "• 시설이 가까워도 이용하기 어려운 이유가 있었나요?", ""], ["목록", "• 어린이, 어르신, 휠체어 이용자에게는 같은 길이 어떻게 다르게 느껴질까요?", ""], ["목록", "• 다른 동네에서 하루를 보낸다면 내 일상은 어떻게 달라질까요?", ""], ["목록", "• 이동의 어려움이나 비용을 줄이려면, 우리 동네에서 무엇을 바꾸면 좋을까요?", ""], ["소제목", "모두가 안심하고 살 수 있는 ‘집다운 집’을 위하여", ""], ["본문", "우리는 앞에서 집이 단순한 건물이 아니라, 사람들의 삶을 나누고 기회를 결정하기도 하는 힘을 가지고 있다는 걸 배웠어요. 그래서 어떤 사람에게 집은 든든한 자산이 되지만, 또 어떤 사람에게는 늘 걱정이 되는 짐처럼 느껴지기도 하죠. 그렇다면 이런 질문을 던져 볼 수 있어요.", ""], ["본문", "\"집이 누구에게나 따뜻하고 안정적인 공간이 되는 사회는 가능할까?\"", ""], ["본문", "\"사는 곳 때문에 차별받거나, 집값 걱정에 시달리지 않고 살 수 있는 세상을 만들 수 있을까?\"", ""], ["본문", "쉽게 정답을 찾을 수 있는 문제는 아니에요. 한 가지 정책으로 모든 문제를 해결하기도 어렵지요. 누구를 돕는지, 비용은 어떻게 마련할지, 다른 사람의 생활에는 어떤 영향을 줄지 살피며 여러 방법을 함께 검토해야 해요. 그렇다면 이런 세상을 만들기 위해 어떤 노력을 생각해 볼 수 있을까요?", ""], ["소소제목", "■ 형편에 맞는 비용으로 살 수 있는 집을 늘려요", ""], ["본문", "돈이 많지 않아도 안심하고 살 수 있는 공공임대주택이나 다양한 형태의 집을 마련하는 방법이 있어요. 이때 숫자만 늘리는 데 그치지 않고, 집의 품질과 위치, 가까운 돌봄·교통시설까지 함께 살펴야 해요.", ""], ["소소제목", "■ 세입자의 생활과 보증금을 지켜요", ""], ["본문", "전세나 월세로 사는 사람들이 갑자기 이사해야 하는 일이 없도록 계약을 안정적으로 이어 가는 제도, 보증금을 보호하는 장치, 분쟁이 생겼을 때 도움받을 수 있는 상담과 법률 지원이 필요해요. (제3장에서 배운 보증금 지키는 방법, 기억나나요?) 이런 제도가 실제로 필요한 사람에게 닿는지, 집을 빌려주는 쪽과 빌리는 쪽 모두에게 어떤 영향을 주는지도 함께 살펴야 하지요.", ""], ["소소제목", "■ 생활의 기회를 여러 동네에 나눠요", ""], ["본문", "학교, 병원, 공원 같은 시설이 한쪽에만 몰리지 않도록 필요한 곳에 마련하고, 버스와 보행로로 동네를 잇는 방법이 있어요. 새 시설을 짓는 것만큼, 이미 있는 시설을 누구나 이용하기 쉽게 바꾸는 일도 중요해요.", ""], ["소소제목", "■ 집의 가격과 살림을 함께 살펴요", ""], ["본문", "집은 재산이면서 생활의 터전이에요. 그래서 집을 여러 채 가진 사람을 어떻게 볼지, 세금과 대출을 어떻게 정할지를 두고 사람들의 의견이 갈리기도 해요. 어떤 정책을 이야기하든 집값만이 아니라, 사람들이 감당할 수 있는 비용과 생활의 안정을 함께 따져야 해요.", ""], ["소소제목", "■ 소유 말고 다른 선택도 존중해요", ""], ["본문", "집을 사는 것만이 성공한 주거 생활은 아니에요. 잘 관리되는 임대주택에서 안정적으로 살거나, 여러 사람이 공간을 나누어 함께 살거나, 뜻이 맞는 사람들이 힘을 모아 집을 짓는 방법도 있어요. 중요한 것은 각자의 필요와 형편에 맞는 선택을 존중하는 일이에요.", ""], ["본문", "집은 단지 가격표가 붙은 물건이 아니에요. 그 안에서 사람이 살아가고, 꿈을 꾸고, 가족이 자라고, 이웃과 시간을 나누며 하루하루를 보내지요. 그러니 집을 비싸고 싼 것으로만 바라보지 말고, '어떤 집에서, 어떻게 살아가는가'를 함께 생각해 볼 필요가 있어요.", ""], ["본문", "\"좋은 집이란 과연 어떤 집일까?\"", ""], ["본문", "\"좋은 동네는 정말 누구에게나 열려 있을까?\"", ""], ["본문", "이런 질문을 스스로 던져 보는 것만으로도, 우리는 모두가 안심하고 살아갈 수 있는 세상을 향해 한 발짝 다가설 수 있어요. 집 때문에 눈물 흘리지 않아도 되는 사회, 누구나 편안하게 머무를 수 있는 '집다운 집'이 있는 사회. 그런 세상을 함께 만들어 갈 수 있다면, 우리 모두의 미래는 지금보다 훨씬 더 따뜻해지지 않을까요?", ""], ["절 제목", "생각을 여는 세 가지 질문", ""], ["번호 목록", "1. 카페가 생긴 뒤 집값이 올랐어요. 카페가 원인이라고 말하려면 무엇을 더 알아야 할까요?", ""], ["번호 목록", "2. 도시기본계획에 공원 조성 방향이 담겼어요. 바로 공사 중인 공원과 무엇이 다른가요?", ""], ["번호 목록", "3. 두 동네에 도서관이 한 곳씩 있어요. 이용할 기회도 같다고 말할 수 있을까요? 시간·길·비용 중 하나로 설명해 보세요.", ""], ["절 제목", "더 깊게 생각해보기", ""], ["질문 제목", "□ 동네마다 집값이 다른 이유와 삶의 기회에 미치는 영향", ""], ["본문", "동네마다 집값이 다른 이유는 무엇일까요? 이런 차이가 교육, 건강, 이동 같은 삶의 기회에 어떤 영향을 줄 수 있을까요? 구체적인 사례와 함께 도시 기본 계획이 이 변화에 어떤 역할을 하는지도 설명해 보세요.", ""], ["질문 제목", "□ 도시 기본 계획이 우리 동네에 미치는 영향", ""], ["본문", "도시·군기본계획이 정한 큰 방향은 도시·군관리계획을 거쳐 땅의 쓰임새와 건물 크기의 규칙으로 구체화돼요. 이 계획이 우리 동네의 환경과 집값에 어떤 영향을 줄 수 있는지 예를 들어 설명해 보세요. 계획 과정에서 생길 수 있는 문제점도 함께 생각해 봅시다.", ""], ["질문 제목", "□ ‘좋은 동네’의 기준은 무엇일까?", ""], ["본문", "사람들은 왜 집값이 높은 동네를 ‘좋은 동네’라고 생각할까요? 집값 말고도 좋은 동네를 판단할 수 있는 기준이 있을까요? 여러분이 생각하는 진짜 ‘좋은 동네’의 조건은 무엇인지 설명해 보세요.", ""], ["질문 제목", "□ 공간 불평등과 그 해결 방법", ""], ["본문", "사는 지역에 따라 병원, 학교, 공원 등 접근성이 다르다면 어떤 문제가 생길까요? 이런 공간 불평등을 줄이기 위해 사회나 정부는 어떤 노력을 해야 할까요? 여러분의 생각을 서술해 보세요.", ""]]}, {"key": "ch07", "num": "07", "title": "나의 첫 번째 계약서", "p": [["본문", "여러분은 어른이 되어 어떤 공간에서 살고 있을지 상상해 본 적 있나요? 대학교 근처 원룸을 나만의 취향으로 꾸미는 모습일 수도 있고, 첫 직장 가까이에 작은 집을 얻어 독립하는 모습일 수도 있어요. 가족이나 친구와 함께 사는 모습을 떠올린 사람도 있겠지요. 언제, 어떤 방식으로 혼자 살게 될지는 사람마다 달라요.", ""], ["본문", "처음 집을 구하는 일은 설레면서도 막막할 수 있어요. '어디서부터 알아봐야 하지?', '혹시 손해를 보거나 사기를 당하면 어떡하지?', '어려운 서류는 누구에게 물어봐야 할까?' 하는 걱정이 드는 건 아주 자연스러운 일이에요.", ""], ["본문", "우리는 지금까지 땅과 소유의 의미에서 시작해 등기사항전부증명서, 보증금과 계약, 부동산 용어, 그리고 집과 동네, 사회의 관계까지 차근차근 살펴봤어요. 이 지식은 그런 순간에 '무엇을 확인해야 할까?' 하는 질문을 만드는 데 도움이 돼요. 그렇다고 한 번 읽었다고 모든 문제를 혼자 해결해야 하는 것은 아니에요. 믿을 만한 사람과 기관에 도움을 요청하는 것도 중요한 준비랍니다. 서두르지 않고 나의 속도에 맞춰 하나씩 확인해 나가면 돼요.", ""], ["본문", "이번 장에서는 스무 살 주하의 첫 자취방 계약을 따라가 볼 거예요. 주하와 가족, 집과 금액은 학습을 위해 만든 가상의 이야기예요. 대출과 보증의 심사 결과도 이야기 속 설정일 뿐, 실제 상품의 자격이나 승인 한도를 뜻하지는 않아요.", ""], ["본문", "이제, 우리 이야기의 마지막 장을 함께 열어 볼까요?", ""], ["절 제목", "[책 속의 책] 프롤로그: 새로운 시작은 늘 설레게 하지", ""], ["본문", "스무 살, 주하는 드디어 꿈에 그리던 Y대학교에 합격했다. 아직 입학식도 하지 않았지만, 마음은 벌써 캠퍼스의 벚꽃길을 걷고 있었다. 하지만 현실은 그리 낭만적이지 않았다. 집에서 학교까지 지하철로 두 시간이 넘게 걸렸고, 기숙사 신청도 했지만 떨어졌다. 결국 혼자 살 집을 구해야 했다.", ""], ["도판 자리", "[도7-1] 제안 도판", "7-1"], ["본문", "처음 해 보는 자취. 설레기도 했지만 어디서부터 시작해야 할지 막막했다. 방은 어떻게 구하는지, 계약서는 어떻게 쓰는지. 뉴스에서나 보던 전세사기라는 말도 머릿속을 맴돌았다. 주하는 스멀스멀 올라오는 걱정을 떨쳐 내듯 고개를 세차게 저었다.", ""], ["본문", "'모르는 것부터 적어 보자. 엄마 아빠 도움도 받고, 내가 직접 물어볼 것도 찾아보는 거야. 그래도 내 첫 집이니까.'", ""], ["본문", "그런 생각이 들자, 주하는 바로 동네 도서관으로 달려갔다. 부동산 관련 책이 모여 있는 서가에서 눈에 띄는 책 몇 권을 골라 대출했다. 집으로 돌아와 책상에 앉은 주하는 어떤 책부터 볼까 고르다가, '10대를 위한 부동산 교양 수업'이라는 제목에 눈길이 멈췄다.", ""], ["본문", "'10대라…… 불과 얼마 전까지 10대였으니까, 괜찮겠지?'", ""], ["본문", "책을 펼치자 이런 문장이 눈에 들어왔다.", ""], ["본문", "\"처음부터 어려운 권리를 모두 해석할 필요는 없어요. 어떤 내용을 직접 찾고, 무엇을 질문해야 하는지 아는 것부터 시작해 볼까요?\"", ""], ["본문", "주하는 그 구절을 곱씹었다. '내가 다 알아야 하는 건 아니구나. 모르는 것부터 적어 보자던 생각이 틀리지 않았네.'", ""], ["본문", "주하는 천천히 책장을 넘겼다. 땅의 가치, 집의 신분증이라 불리는 등기사항전부증명서, 보증금과 계약서에서 꼭 확인해야 할 것들, 낯선 부동산 용어, 그리고 집값이 우리 사회에 미치는 영향까지. 전세사기 이야기를 읽을 때는 '나한테도 이런 일이 생기면 어쩌지?' 하는 두려움이 스쳤다. 그래도 곧이어 보증금을 보호하는 장치들이 나왔다. 전입신고, 확정일자, 반환보증. 주하는 세 낱말을 메모장에 적고 옆에 물음표를 그렸다. 이름은 알겠는데, 실제로 언제 무엇을 해야 하는지는 다시 확인하고 싶었다.", ""], ["본문", "'이건 은행에, 이건 중개사님에게 물어봐야겠다.' 메모장에 질문이 하나둘 늘어났다.", ""], ["본문", "책을 다 읽고 나니 어느덧 밤이 되어 있었다. 다섯 시간 넘게 앉아 있었던 것 같다. 의자에서 일어나 기지개를 크게 켠 주하는 창문 너머로 바깥을 바라보았다. 반짝이는 별빛을 보고 있으니, 왠지 모를 설렘과 기대감이 마음속에서 피어올랐다.", ""], ["본문", "'나, 왠지 잘할 수 있을 것 같은데.'", ""], ["본문", "\"두려움은 모르는 데서 오고, 용기는 아는 데서 온다\"는 말이 문득 떠올랐다. 책을 읽기 전에는 막연하게 겁이 났는데, 이제는 다음에 무엇을 알아봐야 할지 조금은 보였다. 머지않아 공인중개사사무소라는 곳에도 처음 가 보게 되겠지. 처음으로 자기 이름을 쓰게 될 계약서. 하지만 주하는 혼자가 아니었다. 그때까지 함께 확인해 줄 사람들을 떠올리니, 마음이 든든해졌다.", ""], ["소제목", "[책 속의 책] 주하의 집 구하기 프로젝트 Part 1: 내가 살고 싶은 집 조건 정하기", ""], ["본문", "다음 날 아침, 주하는 눈을 뜨자마자 침대맡에 놓아둔 태블릿을 집어 들었다. 부동산 앱을 실행하고, 화면을 쓸어 올리며 Y대학교 근처에 혼자 살 만한 집들을 하나하나 살펴보았다. '이런 걸 손품 판다고 하지. 발품 팔기 전에 인터넷으로 먼저 매물을 알아보는 거.'", ""], ["도판 자리", "[도7-2] 제안 도판", "7-2"], ["본문", "하지만 막상 수많은 집을 보다 보니, 어떤 집이 좋고 어떤 집은 피해야 할지 쉽게 판단이 서지 않았다. 사진은 다 좋아 보이고, 설명도 비슷비슷했다. 이대로 보다가는 시간만 허비하겠다 싶어, 주하는 자취방을 고를 기준부터 세우기로 했다. 뭐든 기준이 있어야 비교도 하고 결정도 내릴 수 있으니까. 주하는 태블릿 펜을 꺼내 메모장을 켜고, 맨 위에 '내가 살고 싶은 집'이라고 적었다.", ""], ["본문", "가장 먼저 떠오른 조건은 단연 위치였다. 자취를 하기로 한 이유 자체가 긴 통학 시간을 줄이기 위해서였다. 게다가 주하는 아침잠이 많았다. 고등학교 때도 늦잠을 자고 허겁지겁 등교한 날이 한두 번이 아니었다. 그런 자신을 누구보다 잘 아는 주하는 '학교에서 걸어서 10분 안팎'을 1순위로 적었다. '아침에 조금은 여유가 생기겠지?'", ""], ["본문", "다음은 가격이었다. 아무리 마음에 드는 집이라도 예산을 넘으면 그림의 떡일 뿐이었다. 주하는 부모님과 상의해 보증금은 최대 500만 원, 월세는 40만 원 이하로 정했다. 그런데 적어 놓고 보니 빠진 게 있었다. 관리비와 공과금, 식비도 매달 나갈 테니까. 주하는 월세 칸 옆에 '한 달 생활비 전체'라고 새로 적었다. 아르바이트는 얼마나 할 수 있을지, 입학 후 시간표를 보고 정하기로 했다.", ""], ["본문", "부모님은 좋은 집이 있으면 전세도 괜찮다고 하셨지만, 주하는 책에서 읽은 내용을 떠올렸다. 전세는 큰 보증금을 맡기고 월세 없이 사는 방식이지만, 그 돈을 빌렸다면 이자와 갚아야 할 부담이 생긴다. 계약이 끝났을 때 보증금을 제때 돌려받을 수 있는지도 꼭 따져 봐야 한다. 월세는 매달 주거비가 나가는 대신 처음 맡기는 보증금 부담이 상대적으로 작다. '등록금도 만만치 않은데, 큰돈까지 부담 드리긴 싫어.' 주하는 우선 가족이 정한 예산에 맞춰 월세방부터 찾아보기로 했다.", ""], ["본문", "세 번째는 방 종류와 옵션이었다. 주하는 처음부터 원룸을 생각하고 있었다. 혼자 살기에 알맞은 크기이고, 공간이 너무 크면 오히려 관리가 힘들다고 들었기 때문이다. 무엇보다 작은 공간을 아늑하게 꾸미는 상상만으로도 마음이 설렜다. 조명과 커튼, 작은 책상과 침대를 직접 고르고 배치한다면 나만의 아지트가 될 것 같았다.", ""], ["본문", "냉장고, 세탁기, 에어컨 같은 가전이 갖춰져 있다면 처음 살 물건을 줄일 수 있었다. 큰 짐은 들일 때도 어렵지만, 이사할 때 빼기는 더 어렵다는 말도 떠올랐다. 다만 '풀옵션'이라는 말만 보고 결정하지는 않기로 했다. 어떤 가전이 포함되는지, 제대로 작동하는지, 고장 나면 누가 고쳐 주는지. 주하는 이 세 가지를 질문 목록에 적었다.", ""], ["본문", "마지막은 안전이었다. 마지막에 적긴 했지만, 부모님이 가장 먼저, 가장 크게 걱정하신 부분이었다. 아무리 위치가 좋고 방이 예뻐도 밤에 다니기 무서운 골목은 절대 안 된다고 단호하게 말씀하셨다. 처음엔 조금 과하다 싶었지만, 조건을 정리하다 보니 주하도 자연스럽게 고개가 끄덕여졌다.", ""], ["본문", "공동현관과 창문이 잘 잠기는지, 학교에서 집까지 이어지는 길에 가로등이 충분한지, 밤늦게까지 불을 켜 두는 가게가 있는지 살펴보기로 했다. CCTV가 달려 있다는 사실만으로 안전하다고 판단할 수는 없었다. 불이 났을 때 대피할 길과 소화기 같은 소방시설도 함께 확인하고 싶었다.", ""], ["본문", "네 가지 조건을 차근차근 정리하고 나니, 마음속의 막연한 불안이 조금은 걷히는 것 같았다. '그래, 이제 내가 어떤 집을 원하는지 분명해졌어.' 주하는 미소를 지으며 침대에서 일어났다. 창가로 다가가 커튼을 걷자, 기다렸다는 듯 환한 햇빛이 방 안으로 차르르 쏟아졌다. 따스한 빛이 바닥과 벽을 가득 채우며, 무언가 좋은 일이 곧 시작될 것 같은 예감이 들었다.", ""], ["본문", "새로운 하루, 그리고 새로운 시작이 진짜로 다가오고 있었다.", ""], ["절 제목", "[책 속의 책] 주하의 집 구하기 프로젝트 Part 2: 집 보러 다니기", ""], ["본문", "며칠 뒤, 주하는 드디어 발품을 팔러 길을 나섰다. Y대학교 정문 근처, 인터넷으로 미리 찜해 둔 '창남공인중개사사무소' 앞에 서자 괜히 가슴이 두근거렸다. 혹시 이상한 집만 보여 주면 어쩌지? 주하는 크게 심호흡을 했다. '괜찮아. 여태 공부한 게 얼만데.'", ""], ["도판 자리", "[도7-3] 제안 도판", "7-3"], ["본문", "문을 열자 중개사님이 반갑게 맞았다. 주하는 벽에 걸린 자격증 속 사진과 눈앞의 얼굴을 재빨리 비교했다. '음, 합격!' 속으로 웃으면서도 메모를 떠올리고 중개사무소 등록증까지 확인했다. 사진이 닮았다고 확인이 끝나는 건 아니었다.", ""], ["본문", "\"안녕하세요! 학교 근처 원룸을 구하러 왔어요. 보증금 500만 원에 월세 40만 원 이하로요. 관리비가 따로 얼마인지도 알고 싶어요.\"", ""], ["본문", "중개사님은 빙긋 웃으며 태블릿으로 매물 사진을 보여 주었다. 주하는 마음에 드는 집 세 곳을 골랐고, 두 사람은 본격적인 발품에 나섰다.", ""], ["본문", "첫 번째 집은 사진보다 훨씬 작고 어두웠다. 벽지에는 습기로 생긴 얼룩이 군데군데 남아 있었다. '역시 사진만 믿으면 안 되겠어.' 두 번째 집은 넓고 깔끔했지만, 창문을 열자 바로 앞에 옆 건물 벽이 바짝 붙어 있었다. 햇빛도 거의 들지 않았다.", ""], ["본문", "그리고 세 번째 집. 문을 열자 주하의 눈이 반짝였다. 남향 창으로 햇살이 들어왔고, 창밖으로 푸른 나무와 조용한 골목이 보였다. 냉장고와 세탁기, 전자레인지, 에어컨도 있었다. 주하는 포함되는 물건을 메모하고, 수도를 틀어 물이 잘 나오고 잘 빠지는지, 창문이 잘 잠기는지 살폈다. 학교까지 직접 걸어 보니 10분쯤 걸렸다. 주하가 \"와…\" 하고 감탄하자 중개사님이 말했다.", ""], ["본문", "\"이 집은 보증금 5,000만 원 전세로도 계약할 수 있어요. 월세 조건과 비교해 보셔도 돼요.\"", ""], ["본문", "\"아, 저는 월세만 생각하고 있었어요. 전세는 보증금이 너무 커서, 부모님께 부탁드리기 부담스러워서요.\"", ""], ["본문", "\"청년 대상 전세자금대출을 알아볼 수는 있어요. 다만 나이, 소득, 보증금, 집의 조건에 따라 은행 심사 결과가 달라져요. 월세와 비교할 때도 이자뿐 아니라 보증료와 갚는 조건까지 살펴야 하고요. 대출보증이 된다고 전세보증금 반환보증까지 자동으로 되는 것도 아니니, 은행과 보증기관에 각각 확인해 보세요.\"", ""], ["본문", "'돈을 빌리면 한 달에 얼마를 내야 하지?' 주하는 메모에 '한도, 금리, 보증료, 갚는 날'을 적었다. 월세를 안 낸다는 말보다, 실제로 감당할 돈이 얼마인지가 궁금했다. 몰랐던 선택지가 하나 열린 느낌이었지만, 사전 상담과 최종 승인은 다르다는 것도 기억해 두었다.", ""], ["본문", "그날 밤, 주하는 부모님께 낮에 본 집과 대출 이야기를 전했다. 아빠가 말했다. \"월세는 그동안 집을 쓰는 비용이야. 그냥 없어지는 아까운 돈이라고만 볼 건 아니지. 전세도 빌린 돈의 비용과 보증금을 못 돌려받을 위험을 같이 봐야 하고.\" 엄마가 계산기를 가져왔고, 세 사람은 두 방식의 한 달 비용과 처음 필요한 돈을 나란히 적었다.", ""], ["본문", "이야기를 마친 뒤, 주하는 부모님과 함께 그 집 주변을 다시 걸었다. 밤길이 궁금했다. 집 앞 골목에는 가로등이 켜져 있었고 편의점 간판도 환했지만, 조금 떨어진 모퉁이는 어두웠다. 학교에서 올 때 큰길을 따라 조금 돌아오는 길도 확인했다. '낮이랑 다르네. 이 길을 기억해 둬야겠어.'", ""], ["본문", "다음 날, 주하는 혹시나 해서 다른 부동산 몇 곳에도 들러 보았다. 하지만 비교할수록 세 번째 집이 더 또렷하게 떠올랐다. 저녁 무렵, 주하는 다시 창남공인중개사사무소 문을 열었다.", ""], ["본문", "\"어제 본 세 번째 집이 제일 마음에 들어요! 창가에 작은 책상을 놓고 싶어요.\" 주하는 메모장을 펼쳤다. \"그리고 계약 전에 확인할 질문을 가져왔어요. 은행 상담에 필요한 집 서류도 받을 수 있을까요?\"", ""], ["절 제목", "[책 속의 책] 주하의 집 구하기 프로젝트 Part 3: 계약하기", ""], ["본문", "며칠 동안 주하는 은행과 보증기관을 찾아 필요한 서류와 조건을 물었다. 사전 상담에서는 전세자금 4,000만 원을 심사받아 볼 수 있다는 안내를 받았다. 아직 승인은 아니었다. 남은 1,000만 원은 가족이 함께 계산했다. 처음 준비한 500만 원에 부모님이 500만 원을 더 보태기로 했다. 이사비와 보증료는 따로 준비하고, 대출이 부족하게 나오면 무리해서 계약을 이어 가지 않기로 약속했다.", ""], ["본문", "드디어 계약서 쓰는 날. 주하는 부모님과 함께 공인중개사사무소에 도착했다. 중개사님과 집주인 아저씨가 테이블에 마주 앉아 서류를 정리하고 있었다. 자리에 앉은 주하는 깊은 숨을 내쉬었다. '서명하기 전에 확인할 것들. 배운 걸 제대로 써먹어야 해.'", ""], ["본문", "중개사님이 그날 발급한 등기사항전부증명서를 펼쳤다. 주하는 표제부에서 주소와 동·호수가 직접 본 집과 같은지 확인했다. 갑구에서는 소유자 이름을 집주인 아저씨의 신분증과 대조했다. 을구에는 근저당권이 없었다. 이어 건축물대장에서 건물 용도와 위반건축물 표시가 없는지 보고, 주변 비슷한 집의 매매 시세와 전세 가격 자료도 함께 살폈다. 등기 한 장이 깨끗하다고 확인이 모두 끝나는 건 아니었다.", ""], ["본문", "\"정말 꼼꼼히 보시네요. 등기사항전부증명서 읽을 줄 아는 분, 생각보다 많지 않아요.\"", ""], ["본문", "\"책으로 열심히 배웠거든요.\"", ""], ["본문", "주하는 반환보증에 가입할 수 있는지 물었다.", ""], ["본문", "\"지금 확인한 정보로는 신청해 볼 수 있어요. 다만 최종 가입 여부는 보증기관 심사가 끝나야 알 수 있어요.\"", ""], ["본문", "주하는 메모에 '신청 가능 ≠ 가입 확정'이라고 적었다. 그래서 대출이나 반환보증이 거절될 때를 대비한 약속을 특약에 넣기로 했다. 집주인 아저씨는 미리 준비한 국세·지방세 납세증명서도 건넸다. 주하는 체납 내역과 함께 발급일과 유효기간을 살폈다. 원룸 건물에는 여러 세입자가 함께 사는 경우가 많아서, 주하는 먼저 들어온 세입자들의 보증금 정보(확정일자 부여 현황)도 보여 달라고 했다. 집주인은 보증 심사에 필요한 자료도 제공하기로 했다.", ""], ["본문", "서류 확인을 마치자 중개사님이 계약서 작성에 들어갔다. 주하는 설명을 들으며 항목을 하나씩 따라 읽었다.", ""], ["번호 목록", "1. 계약 목적물: 주소, 건물명, 면적 등", ""], ["번호 목록", "2. 임대차 보증금: 5,000만 원(전세)", ""], ["번호 목록", "3. 계약 기간: 2년", ""], ["번호 목록", "4. 입주 예정일: 2월 24일", ""], ["번호 목록", "5. 지급 방식: 계약금 1,000만 원(계약 당일), 잔금 4,000만 원(입주일, 대출 최종 승인과 실행을 전제로 함)", ""], ["번호 목록", "6. 특약(이 가상 계약에서 합의한 내용을 줄여 소개해요)", ""], ["본문", "① 냉장고·세탁기·전자레인지·에어컨을 제공한다. 입주 전 상태는 사진과 확인표로 남긴다. 정상적으로 쓰다 생긴 고장은 임대인이 수리하고, 임차인의 부주의로 생긴 손상은 임차인이 부담한다.", ""], ["본문", "② 보통의 사용으로 낡은 부분과 입주 전부터 있던 손상은 임차인의 원상회복 범위에서 뺀다.", ""], ["본문", "③ 임차인이 입주와 전입신고를 마쳐 대항력이 생길 때까지, 임대인은 근저당권 같은 새 권리를 설정하지 않는다. 어기면 임차인은 계약을 해제하고 낸 돈을 돌려받을 수 있다.", ""], ["본문", "④ 임차인의 잘못이 아닌 이유로 대출이 4,000만 원에 못 미치거나 거절되면, 임차인은 계약을 해제할 수 있고 임대인은 받은 돈을 모두 돌려준다. 입주 후 반환보증 가입이 거절되면 임차인은 계약을 끝낼 수 있고, 보증금 반환과 집 반환은 동시에 한다.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "특약은 집주인에게 약속을 지킬 의무를 만들지만, 은행이나 보증기관에 승인을 강요하지는 못해요. 실제 계약에서는 신청 기한과 돌려받는 날짜처럼 일정과 절차를 더 구체적으로 적어요.", ""], ["본문", "주하는 특약의 긴 문장을 천천히 읽었다. 이해가 안 되는 부분에서는 잠깐 기다려 달라고 했다. '원상회복'이라는 말에서 멈춘 주하가 물었다.", ""], ["본문", "\"여기 '원상회복'은 구체적으로 어떤 걸 말하는 건가요?\"", ""], ["본문", "\"살기 전부터 있던 흠집이나 보통으로 쓰면서 자연스럽게 낡은 부분은 주하 씨 책임이 아니에요. 주하 씨 잘못으로 망가진 부분만 고쳐 놓으면 돼요. 무조건 새것처럼 만들라는 뜻은 아니에요.\"", ""], ["본문", "주하는 집주인 아저씨에게 조심스럽게 물었다.", ""], ["본문", "\"벽에 액자를 못으로 걸면, 나갈 때 그 자국도 메워야 하나요?\"", ""], ["본문", "\"창가 옆 벽에 작은 못 두 개 정도는 괜찮아요. 그 자국은 안 메워도 되는 걸로 적읍시다.\"", ""], ["본문", "주하는 못 박을 위치를 사진에 표시했고, 중개사님은 그 합의를 특약에 덧붙였다. 말로만 들었을 때보다 약속이 훨씬 분명해졌다.", ""], ["본문", "작은 글씨의 조항까지 모두 확인한 뒤, 주하는 계약서 맨 아래에 이름을 또박또박 적었다. 집주인과 중개사님도 서명을 마쳤다. 서명 뒤,주하는 받는 사람과 계좌가 등기사항전부증명서의 소유자와 같은지 다시 확인하고 계약금 1,000만 원을 보냈다. 계약서와 중개대상물 확인·설명서, 영수증, 송금 기록도 한 파일에 챙겼다.", ""], ["본문", "계약서를 받아 든 순간, 주하는 잠시 생각에 잠겼다. 종이 몇 장이었지만, 그 안에는 며칠 동안 공부하고 발품 팔며 찾아다닌 시간과 앞으로 새로운 공간에서 살아갈 삶의 무게가 담겨 있었다. 남은 돈은 4,000만 원. 주하는 파일을 가슴에 꼭 안았다. 이제 정말, 그 방에서 지낼 날을 준비할 차례였다.", ""], ["절 제목", "[책 속의 책] 주하의 집 구하기 프로젝트 Part 4: 입주 전후에 할 일", ""], ["본문", "계약서에 서명했다고 모든 일이 끝난 건 아니었다. 계약 전이 '이 집이 괜찮은가'를 묻는 단계였다면, 이제는 '내 보증금을 어떻게 지킬까'를 스스로 챙길 차례였다.", ""], ["본문", "주하는 계약 다음 날 주민센터에 가서 계약서에 확정일자를 받았다. 확정일자는 이사할 때까지 기다리지 않아도 받을 수 있었다. 계약서를 은행에 제출하자 추가 심사가 이어졌고, 며칠 뒤 대출 4,000만 원이 최종 승인되었다. 주하는 금리와 갚는 방식, 대출금이 나가는 날을 확인하고 한 달 생활비 계산도 다시 맞췄다.", ""], ["본문", "입주일 아침, 주하는 잔금을 보내기 전에 등기사항전부증명서를 한 번 더 떼어 보았다. 계약하던 날 이후로 새로 생긴 권리는 없었다. 집주인 아저씨와 함께 집 상태를 둘러보고, 약속한 순서대로 대출금 4,000만 원이 집주인 계좌로 들어간 것을 확인한 뒤 열쇠를 넘겨받았다. 그리고 그날 낮, 곧장 주민센터로 가서 전입신고를 하고 처리된 주소를 확인했다.", ""], ["본문", "\"이제 진짜 이 집이 내 주소가 됐네.\"", ""], ["본문", "새 주소가 적힌 기록을 바라보며 주하는 책에서 읽은 내용을 떠올렸다. 집을 넘겨받고 전입신고까지 마쳤으니, 대항력은 다음 날 0시부터 생긴다. 여기에 미리 받아 둔 확정일자가 함께 갖춰져야, 혹시 집이 경매에 넘어가더라도 뒤 순위 권리자보다 먼저 보증금을 돌려받을 권리(우선변제권)를 주장할 수 있다.", ""], ["본문", "'확정일자, 집 넘겨받기, 전입신고. 이름만 외웠을 때와는 느낌이 다르네.' 주하는 처리한 서류를 파일에 넣으며 조용히 미소 지었다.", ""], ["잠깐 라벨", "잠깐!", ""], ["잠깐 본문", "전입신고는 정부24에서 온라인으로도 할 수 있어요. 하지만 '접수'와 '처리 완료'는 달라요. 처리는 공무원의 근무시간에 이루어지기 때문에, 밤에 신청하고 바로 끝났다고 생각하면 안 돼요. 확정일자는 전입신고와 별개의 절차이고, 인터넷등기소에서 온라인으로 받거나 임대차 신고를 할 때 함께 받을 수도 있어요. 어떤 방법이든 실제로 처리되었는지 꼭 확인해요.", ""], ["본문", "입주 후, 주하는 특약에서 약속한 기한 안에 전세보증금 반환보증을 신청했다. 은행에서 대출을 받으며 들었던 대출보증과는 다른 제도라는 점도 다시 확인했다. 보증기관은 집값과 먼저 설정된 권리, 계약 내용 등을 심사했고, 주하는 요청받은 서류를 보완해 냈다.", ""], ["본문", "얼마 뒤, 가입이 승인되었다는 안내가 왔다. 주하는 보증서에 적힌 보증금액과 보증 기간을 꼼꼼히 확인했다. 반환보증은 계약이 끝났는데도 집주인이 보증금을 돌려주지 못하면, 보증기관이 먼저 세입자에게 보증금을 돌려주고 나중에 집주인에게 그 돈을 받아 내는 제도다. 다만 계약 내용이 바뀌면 알려야 할 것이 있고, 보증금을 받으려면 정해진 절차를 밟아야 했다. 주하는 그 내용도 따로 적어 두었다. 신청서를 냈을 때보다 마음이 훨씬 놓였다.", ""], ["본문", "서류가 차곡차곡 쌓였다. 계약서와 송금 기록, 입주 날 찍은 집 상태 사진, 보증서가 한 폴더에 모였다. 주하는 이자와 생활비를 내는 날을 달력에 적고, 모르는 일이 생겼을 때 연락할 곳도 저장해 두었다. 책으로만 읽던 절차를 하나하나 직접 해 보고 나니, 주하는 퍼즐의 마지막 조각을 맞춘 기분이 들었다.", ""], ["도판 자리", "[도7-4] 〈두 줄 시간표〉 위쪽은 주하의 여정: 조건 정하기 → 집 보기·서류 확인·은행 사전 상담 → 계약·계약금 …", "7-4"], ["절 제목", "[책 속의 책] 에필로그 : 드디어 이사!", ""], ["본문", "시간을 조금 되돌려, 이삿날.", ""], ["도판 자리", "[도7-6] 제안 도판", "7-6"], ["본문", "주하와 부모님은 서류를 챙기고 짐을 나르느라 종일 분주했다. 옷 상자와 책 상자, 이불과 노트북, 식기와 냄비가 작은 방을 금세 채웠다. 엄마는 직접 싸 온 반찬을 냉장고에 차곡차곡 넣었고, 아빠는 전선을 정리하며 공유기를 설치했다. 익숙한 가족의 손길이 닿을수록 텅 빈 방이 주하의 방으로 바뀌어 갔다. 해가 기울 무렵, 세 사람 모두 배가 고팠다.", ""], ["본문", "\"엄마, 아빠, 우리 뭐 시켜 먹을까? 이삿날엔 역시 짜장면 콜?\"", ""], ["본문", "\"주하가 쏘는 거 맞지? 그럼 난 탕수육 추가!\"", ""], ["본문", "아빠의 너스레에 엄마와 주하는 동시에 웃음을 터뜨렸다. 조금 뒤, 접이식 작은 상 위에 짜장면과 탕수육이 놓였다. 탕수육 위로 김이 모락모락 피어오르고, 방 안에 따뜻한 음식 냄새가 퍼졌다.", ""], ["본문", "\"주하야, 주하 집, 좋네.\"", ""], ["본문", "아빠의 말에 엄마도 미소 지었다.", ""], ["본문", "\"우리 주하가 집 잘 골랐네.\"", ""], ["본문", "주하는 말없이 고개를 끄덕였다. 첫 한입을 삼키는 순간, 마음 한구석에서 이상하게 따뜻한 기분이 밀려왔다. 하루 종일 흘린 땀, 함께한 손길, 음식의 온기. 그 모든 것이 이 집을 그냥 원룸이 아닌, 진짜 '내가 살아가는 곳'으로 바꾸고 있었다.", ""], ["본문", "배달 그릇을 정리하고 부모님이 돌아가신 뒤, 현관문을 닫자 조용한 밤이 찾아왔다. 온전히 혼자가 된 주하는 방 한가운데 서서 천천히 주변을 둘러보았다. 아직은 모든 게 낯설었다. 하지만 이상하게도 곧 익숙해질 것 같은 예감이 들었다. 내 인생의 새로운 페이지가 지금 막 시작된 것 같았다.", ""], ["소제목", "나의 첫 번째 계약서 ― 어른이 되는 문턱", ""], ["본문", "To. 이 책을 읽고 있는 친구에게", ""], ["본문", "안녕. 나는 얼마 전, 생애 첫 집을 계약했어.", ""], ["본문", "종이에 이름을 적은 일이었지만, 그 순간은 내가 내 삶을 직접 선택하기 시작한 첫걸음이었어.", ""], ["본문", "처음에는 많이 두렵고 막막했어. 그래서 모르는 것부터 적었고, 하나씩 확인했고, 모르는 건 물어봤어. 부모님께, 중개사님께, 은행과 보증기관에. 그러면서 알게 됐어. 어른이 된다는 건 모든 걸 혼자 아는 게 아니라, 무엇을 모르는지 알고 제대로 물어볼 줄 아는 거라는 걸.", ""], ["본문", "\"법은 잠자는 자를 돕지 않는다\"는 말이 있대. 권리가 있어도 제때 알고 행사하지 않으면 지키기 어렵다는 뜻이래. 그래서 나는 모르는 걸 미루지 않고 물어보기로 했어. 그 말을 몸으로 느낀 날들이었어.", ""], ["본문", "앞으로 나는 또 어떤 집에서 살게 될까? 어떤 사람을 만나고, 어떤 선택을 하게 될까? 지금보다 더 복잡한 일들이 기다리고 있을 거야. 그래도 이제는 조금 덜 두려워. 서두르지 않고 준비하는 법, 그리고 멈춰서 물어보는 법을 배웠거든.", ""], ["본문", "내가 쓴 첫 계약서는 단지 자취방을 구한 기록이 아니라, 앞으로 나아갈 나를 위한 디딤돌이 되어 줄 거야.", ""], ["본문", "너도 언젠가 그런 날을 맞이하겠지. 이 책에서 배운 것들이 그때 너에게 힘이 되길 바라. 너만의 속도로, 멋진 계약서를 써 내려가길 응원할게.", ""], ["본문", "From. 주하", ""], ["절 제목", "다가올 미래, 집의 모양과 생활은 어떻게 달라질까?", ""], ["본문", "미래의 집을 상상할 때는 세 가지를 나누어 보면 좋아요. 누구와 어떻게 살 것인지, 어떤 방법으로 지을 것인지, 에너지와 생활을 어떻게 관리할 것인지예요. 다음 여섯 가지는 서로 경쟁하는 집 종류가 아니에요. 한 집에 여러 방식이 함께 쓰일 수 있어요.", ""], ["도판 자리", "[도7-5] 제안 도판", "7-5"], ["소제목", "1) 함께 사는 방식 ① 공유 주택", ""], ["본문", "개인 방은 따로 쓰면서 주방이나 거실 같은 공간을 함께 사용하는 방식이에요. 비용과 생활의 일부를 나누고 이웃과 교류할 수 있어요. 하지만 항상 더 저렴하거나 외롭지 않은 것은 아니에요. 청소, 소음, 손님 초대와 공동 비용의 규칙을 정하고, 혼자 쉴 공간도 존중해야 해요.", ""], ["소제목", "2) 함께 사는 방식 ② 코하우징", ""], ["본문", "각 가구가 독립적인 집에서 살면서 공동 식당이나 텃밭 같은 공간과 활동을 나누는 방식이에요. 주민이 계획과 운영에 참여하는 일이 중요해요. 어떤 일을 얼마나 함께할지는 공동체마다 달라요. 함께 식사하는 즐거움과 공동 일을 맡는 책임을 같이 생각해 볼 수 있지요.", ""], ["소제목", "3) 짓는 방식 ① 모듈러 주택", ""], ["본문", "공장에서 미리 만든 건물의 부분들을 현장으로 옮겨 조립하는 방식이에요. 현장 공사 기간을 줄이고 일정한 품질을 관리하는 데 도움이 될 수 있어요. 다만 운송과 조립, 기초 공사가 필요하고 비용도 조건에 따라 달라져요. 모든 모듈러 주택을 장난감 블록처럼 마음대로 옮기거나 늘릴 수 있는 것은 아니에요.", ""], ["소제목", "4) 짓는 방식 ② 3D 프린팅 주택", ""], ["본문", "큰 장비가 재료를 층층이 쌓아 벽 같은 건물 부분을 만드는 기술이에요. 설계에 따라 다양한 모양을 만들 수 있지요. 그러나 프린터가 지붕과 창문, 전기와 수도까지 집 전체를 한 번에 완성하는 것은 아니에요. 다른 공사와 연결해야 하고, 안전과 성능도 확인해야 해요. 공사 시간과 전체 비용이 얼마나 줄어드는지는 현장에 따라 달라요.", ""], ["소제목", "5) 에너지와 생활을 관리하기 ① 제로에너지 주택", ""], ["본문", "단열을 잘해 필요한 에너지를 줄이고, 태양광 같은 재생에너지 설비를 이용하는 집이에요. 이름에 ‘제로’가 들어가도 전기요금이 언제나 0원이라거나 외부 에너지를 전혀 쓰지 않는다는 뜻은 아니에요. 우리나라 인증에는 에너지 성능에 따른 여러 등급이 있어요. 에너지를 적게 쓰는 건물과 그 안에서의 생활 습관을 함께 생각해야 하지요.", ""], ["소제목", "6) 에너지와 생활을 관리하기 ② 스마트홈", ""], ["본문", "센서와 통신 기능 등을 이용해 조명, 냉난방, 가전과 보안을 관리하는 집이에요. 음성으로 불을 끄거나 온도에 맞춰 냉난방을 조절할 수 있어요. 이동이 불편한 사람에게 도움이 될 수도 있지요. 누구나 쉽게 조작할 수 있는지, 개인정보를 어떻게 보호하는지, 통신이 끊기면 어떻게 사용할지도 함께 살펴야 해요.", ""], ["본문", "기술이 새롭다는 이유만으로 모두에게 좋은 집이 되지는 않아요. 내가 편하게 쉴 수 있는지, 비용을 감당할 수 있는지, 이웃과 지구에 어떤 영향을 주는지를 함께 생각해 보세요. 집의 미래를 바꾸는 것은 기술뿐 아니라 우리가 정하는 생활의 규칙이기도 해요.", ""], ["소제목", "내가 꿈꾸는 집 그려 보기 ― 미래의 하루를 상상하며", ""], ["본문", "지금까지 우리는 집이 단순히 잠을 자는 공간이 아니라, 나의 삶을 담는 그릇이라는 사실을 배웠어요. 이제 그동안 배운 지식에 상상을 더해 '내가 꿈꾸는 집'을 그려 볼 차례예요. 비싸거나 큰 집이 아니어도 좋아요. 나에게 편안한 하루를 먼저 떠올리고, 그 하루를 담을 공간을 그려 보세요.", ""], ["소제목", "1) 상상을 돕는 질문", ""], ["본문", "아래 질문 가운데 마음에 드는 세 가지를 골라 보세요.", ""], ["목록", "• 내가 살고 싶은 집은 어떤 모습인가요?", ""], ["본문", "(예: 아파트, 단독주택, 여럿이 함께 사는 집, 내가 상상한 새로운 형태의 집)", ""], ["목록", "• 어떤 공간은 혼자 쓰고, 어떤 공간은 함께 나누고 싶나요?", ""], ["목록", "• 그 집은 어떤 동네에 있나요?", ""], ["본문", "(예: 도시, 시골, 바닷가, 산속… 왜 그곳을 골랐는지도 함께!)", ""], ["목록", "• 집 안에 꼭 있었으면 하는 공간은 무엇인가요?", ""], ["본문", "(예: 나만의 방, 책 읽는 구석, 그림 그리는 공간, 반려동물과 쉴 수 있는 마당)", ""], ["목록", "• 집 주변에는 무엇이 있나요?", ""], ["본문", "학교, 일터, 공원, 도서관, 친구를 만나는 곳까지 어떻게 가나요?", ""], ["목록", "• 그 집은 어떻게 얻게 되었나요?", ""], ["본문", "(사거나, 빌리거나, 직접 짓거나, 친구들과 함께 쓰거나… 어떤 방식이든 좋아요!)", ""], ["목록", "• 계약을 하게 된다면, 무엇을 가장 먼저 확인할 건가요?", ""], ["본문", "누구에게 어떤 설명을 듣고, 어떤 약속을 확인하고 싶나요? (등기사항전부증명서, 보증금, 계약 기간, 반환보증… 기억나죠?)", ""], ["목록", "• 그 집에서 어떤 삶을 살고 싶나요?", ""], ["본문", "누구와 함께, 어떤 하루를 보내고, 이웃과 어떤 관계를 맺고 싶나요?", ""], ["소제목", "2) 표현 방법은 자유!", ""], ["목록", "• 편지: 그 집에 살고 있을 미래의 나에게 편지를 써 보세요.", ""], ["목록", "• 짧은 글: 그 집에서 보내는 하루를 다섯 문장으로 써 보세요.", ""], ["목록", "• 그림: 방과 동네를 그리고, 꼭 필요한 공간 세 곳에 설명을 달아 보세요.", ""], ["목록", "• 이야기 나누기: 친구와 서로의 집을 소개하고, 궁금한 점을 한 가지씩 물어보세요.", ""], ["절 제목", "생각해 볼 질문", ""], ["번호 목록", "1. 주하가 계약금으로 낸 돈과 입주일에 낸 잔금은 각각 얼마인가요? 두 돈을 더하면 보증금과 맞나요?", ""], ["번호 목록", "2. 반환보증의 신청과 가입 승인은 어떻게 다른가요? 확정일자도 입주일까지 기다려야 할까요?", ""], ["번호 목록", "3. 주하가 집주인에게 물은 못 자국 이야기는 왜 글로도 남겼을까요?", ""], ["절 제목", "더 깊게 생각해보기", ""], ["질문 제목", "□ 나의 첫 임대차 계약, 무엇을 준비해야 할까?", ""], ["본문", "주하의 첫 부동산 계약 과정을 참고하여, 대학생이 되어 처음 자취를 하게 되는 상황에서 학습자가 경험하게 될 첫 임대차 계약 준비 과정에 관해 서술하시오.", ""], ["질문 제목", "□ 내가 생각하는 ‘첫 계약’의 핵심", ""], ["본문", "‘나의 첫 번째 계약’을 준비하는 입장에서, 여러분은 어떤 점을 가장 중요하게 생각하나요?", ""], ["본문", "집을 구하고 계약을 하기까지 어떤 준비가 필요하다고 느꼈는지 구체적으로 생각해 보고, 그 과정에서 필요한 태도와 마음가짐은 무엇인지 함께 서술해 보세요. 또한 정보를 미리 알고 준비하는 것과 그렇지 않은 것의 차이가 실제 상황에서 어떤 결과를 가져올 수 있을지도 상상해 봅시다.", ""], ["질문 제목", "□ 다가오는 미래, 집도 달라진다!", ""], ["본문", "미래 사회에서 등장할 다양한 주거 형태(예: 공유 주택, 코하우징, 스마트 하우스, 제로 에너지 하우스 등)를 한 가지 이상 선택하여 소개하고, 그것이 등장하게 된 사회적·기술적 배경과 특징을 구체적으로 설명하시오.", ""], ["질문 제목", "□ 내가 꿈꾸는 집, 그리고 그 집으로 가는 길", ""], ["본문", "‘내가 꿈꾸는 집’은 어떤 모습인가요? 직접 상상한 집을 구체적으로 묘사하고, 그 집을 마련하거나 계약하는 과정에서 오늘까지 배운 부동산 지식이 어떻게 활용될 수 있을지 설명하시오.", ""]]}, {"key": "back", "num": "", "title": "", "p": [["절 제목", "책을 덮으며 : 저자의 말", ""], ["본문", "책을 덮고 늘 걷던 길에 나서면, 전에는 그냥 지나쳤던 것이 하나쯤 눈에 들어올 거예요. 오래된 가게의 간판, 새로 놓인 횡단보도, 창가에 켜진 작은 불빛 같은 것들이요. 그곳에도 누군가의 약속과 생활이 담겨 있다는 것을, 우리는 이 책에서 함께 살펴보았어요.", ""], ["본문", "어려운 낱말을 모두 기억하지 못해도 괜찮아요. 필요한 순간에 다시 펼쳐 보고, 뜻을 찾아보고, 설명을 부탁할 수 있으면 돼요. \"이 말은 무슨 뜻인가요?\"라는 질문은 모자람을 드러내는 말이 아니라 배움을 시작하는 말이에요.", ""], ["본문", "주변을 보면 어떤 친구는 벌써 앞서가는 것 같고, 또 어떤 친구는 조금 더딘 것 같아 보일 수도 있어요. 하지만 이런 이야기가 있어요. 미국 뉴욕은 캘리포니아보다 시계가 세 시간 빠르지만, 그렇다고 캘리포니아가 뒤처진 것은 아니라고요. 누구는 이른 나이에 꿈을 이루고, 누구는 한참 기다린 뒤에 자기 자리를 찾아요. 모두 자기만의 시간대에서 살아가고 있을 뿐이지요. 그러니 남을 부러워하거나 얕볼 필요도, 서두를 필요도 없어요.", ""], ["본문", "앞으로 여러분이 고를 집과 살아갈 방식도 서로 다를 거예요. 누구는 가족과 오래 함께 살고, 누구는 다른 도시로 떠나고, 누구는 이웃과 공간을 나누겠지요. 집을 언제 마련하는지, 그 집이 얼마인지로 삶에 순서를 매길 필요는 없어요.", ""], ["본문", "그리고 지금의 여러분에게도 편히 쉬고 안전하게 지낼 권리가 있어요. 어른이 된 뒤에야 생기는 권리가 아니에요. 내 방의 불편을 말하고, 통학로를 살피고, 친구가 사는 곳을 함부로 평가하지 않는 일부터 시작할 수 있어요. 어떤 문제는 혼자의 지식과 노력만으로 풀기 어려워요. 그럴 때 함께 도울 사람과 제도를 찾는 것도 삶을 돌보는 힘이에요. 더 많은 사람이 안심하고 머물 수 있도록, 동네의 변화를 함께 이야기해 보세요.", ""], ["본문", "집을 알아 가는 일은 단거리 경주가 아니라 긴 여정이에요. 이 책은 그 여정의 출발선일 뿐이에요. 언젠가 여러분이 새로운 공간의 문을 열 때, 이 책에서 만난 질문 하나가 곁에 있으면 좋겠어요.", ""], ["본문", "\"여기에서 나는 어떤 하루를 살고 싶을까?\"", ""], ["본문", "여러분의 시간과 속도로, 여러분에게 맞는 삶을 찾아가길 응원합니다.", ""], ["본문", "#", ""], ["절 제목", "자료와 출처", ""], ["소제목", "제1장 출처", ""], ["참고 자료", "[1-1] American National Business Hall of Fame, 「Ray Kroc」 — 해리 소넨본과 맥도날드의 부동산 사업 구조.", ""], ["참고 자료", "[1-2] McDonald’s, 2024 Form 10-K — 임대료 수입 100억 1,700만 달러, 총매출 259억 2,000만 달러. 본문의 약 39%는 이 두 수치를 나눈 값.", ""], ["참고 자료", "[1-3] The Metropolitan Museum of Art, 「Cuneiform tablet: sale of real estate」 — 소장번호 86.11.443. 제작 시기·크기·소장품 설명과 이미지 권리 표시.", ""], ["참고 자료", "[1-4] Plutarch, 「Life of Crassus」 2.4 — 불탄 집과 인접한 집의 매입에 관한 후대 전기 기록. 불을 꺼 주는 조건으로 매각을 강요했다는 대화는 사용하지 않음.", ""], ["참고 자료", "[1-5] 국가법령정보센터, 「민법」 제99조 — 부동산과 동산의 구분.", ""], ["참고 자료", "[1-6] Knight Frank, 「The Wealth Report 2025」 — 2024년 모나코의 고급 주거용 부동산에서 미화 100만 달러로 살 수 있는 면적 19㎡. 정사각형 비교는 이해를 돕는 환산 예.", ""], ["참고 자료", "[1-7] 국가데이터처·한국은행·금융감독원, 「2025년 가계금융복지조사 결과」 — 2025년 12월 4일 발표. 2025년 3월 말 기준 가구 자산의 실물자산 비중 75.8%. 실물자산 전체를 부동산과 같은 뜻으로 쓰지 않음. (수치 확인: 뉴시스 2025년 12월 4일 보도)", ""], ["소제목", "제2장 출처", ""], ["참고 자료", "[2-1] 국가법령정보센터, 「주택임대차보호법」 제3조의3 — 임차권등기명령과 등기 완료 후의 보호.", ""], ["참고 자료", "[2-2] 한국경제, 화곡동 등기 위조 사건 보도 — 2022년 11월 보도. 2017년 빌라 매입, 2020년 은행 소송, 2022년 7월 대법원 확정의 경과를 바탕으로 정리했으며, 실제 인물의 대화는 재현하지 않음.", ""], ["참고 자료", "[2-3] 한국학중앙연구원, 한국민족문화대백과사전 「양안」 — 조선시대 토지 조사·기록의 성격.", ""], ["참고 자료", "[2-4] 대법원, 등기 전산화 관련 법원 소식 — 1992년 시작, 2002년 완료로 소개된 등기 전산화 경과.", ""], ["참고 자료", "[2-5] 영문 위키백과, 「Ius civile vigilantibus scriptum est」 — ‘권리 위에 잠자는 자’ 계열 격언이 2세기 로마 법률가 스카이볼라에서 비롯된 경과. 19세기 이후의 쓰임은 Felix Grollmann(2021), 뮌헨대학교 SFB 1369 『Mitteilungen』 2021년 2호 참조. 예링의 『권리를 위한 투쟁』(1872)을 격언의 출처로 쓰지 않음.", ""], ["소제목", "제3장 출처", ""], ["참고 자료", "[3-1] 국가법령정보센터, 「주택임대차보호법」 제3조·제3조의2·제3조의7·제4조·제6조의3 — 대항력, 우선변제권, 임대인의 정보 제시 의무, 임대차 기간과 갱신 후 해지 통고.", ""], ["참고 자료", "[3-2] JTBC, 울산 전세사기 수사 보도(네이트 게재) — 2025년 3월 경찰 수사 발표 보도. 본문은 검거 단계로 표시. 이어지는 계산 장면은 사건의 실제 금액과 구별한 가상 예.", ""], ["참고 자료", "[3-3] 어피티, 「2023년 3월 14일 머니레터」 피해 당사자 인터뷰 — 퇴거 통보와 보증금 3,300만 원을 돌려받기까지의 경과. 2016년 사건 발생, 2019년 반환이라는 인터뷰 내용에 맞춤.", ""], ["참고 자료", "[3-4] 국가법령정보센터, 「신탁법」 — 신탁의 정의와 신탁재산·수탁자의 권한 관련 규정. 임대 권한은 신탁 내용과 권리관계별로 확인.", ""], ["참고 자료", "[3-5] 매일신문, 대구 신탁부동산 임대사기 판결 보도 — 2024년 7월 보도에 나타난 1심 판결과 피해 규모.", ""], ["참고 자료", "[3-6] 찾기쉬운 생활법령정보, 「주택임대차보호법의 적용」 — 공부상 표시와 실제 용도, 무허가·미등기 주택의 적용 관계.", ""], ["참고 자료", "[3-7] 국세청, 「미납국세 열람제도」 안내 — 임대인 동의 없이 열람할 수 있는 시기와 보증금 요건. 세금과 보증금의 순위는 국세기본법 제35조 등 별도 규정에 따름.", ""], ["참고 자료", "[3-8] 주택도시보증공사, 「전세보증금반환보증」 — 보증 대상, 신청과 심사, 이행청구 절차. 한국주택금융공사의 전세지킴보증 안내도 함께 대조.", ""], ["참고 자료", "[3-9] 한국국학진흥원 스토리테마파크, 노상추 일기 기반 이야기 — 1796년 일기: 27관과 추가 3관을 둘러싼 이사 경과, 30냥 반환 기록. 서로 다른 화폐 표기를 임의로 같은 단위로 고치지 않음.", ""], ["참고 자료", "[3-10] 경북매일, 「신탁 전세사기 LH 매입 첫 사례 ‘대구’서 나왔다」 — 2025년 8월 17일 보도. 침산동 다세대주택 16세대 매입과 감정가 차익을 활용한 보증금 일부 반환. 2024년 개정 전세사기 특별법으로 신탁 사기 피해가 지원 대상이 된 경과.", ""], ["참고 자료", "[3-11] 세계일보, 조선 후기 세매 관습 연구 소개 기사 — 2024년 4월 30일 보도. 연구 「전세의 원형, 조선 후기 세매 관습의 특성에 관한 연구」와 『국역 노상추일기』를 인용해 세매·세전 관습과 노상추의 1796년 경험을 소개.", ""], ["소제목", "제4장 출처", ""], ["참고 자료", "[4-1] 네덜란드 국가기록원, 「Dutch-American Stories」 — 1626년 스하헌 편지의 60길더 기록. 편지와 거래 당사자의 계약서를 구별.", ""], ["참고 자료", "[4-2] 뉴욕시 Landmarks Preservation Commission, 「Purchase of Manhattan」 — 거래 당사자들의 토지 이용·소유 이해에 대한 역사적 해석과 한계.", ""], ["참고 자료", "[4-3] 국가법령정보센터, 「민법」 제114조 — 대리행위의 효력. 미성년자의 법률행위는 같은 법 제5조·제6조·제17조를 함께 참조.", ""], ["참고 자료", "[4-4] 대법원, 2016도13263 판결 관련 자료 — 2017년 4월 홈플러스 경품행사의 개인정보 수집·제공 동의 관련 판단.", ""], ["참고 자료", "[4-5] 국가법령정보센터, 「민법」 제565조 — 해약금과 이행 착수의 관계. 채무불이행 손해배상과 구별.", ""], ["참고 자료", "[4-6] 영문 위키백과, 「Peter Minuit」 — 스하헌 편지의 60길더를 2020년 기준 약 1,143달러로 환산한 값. 본문의 ‘약 1,100달러’는 이 환산의 어림값이며, 환산 방식에 따라 달라질 수 있음.", ""], ["소제목", "제5장 출처", ""], ["참고 자료", "[5-1] 국가법령정보센터, 「신탁법」 제2조·제101조 — 신탁의 정의와 종료 후 잔여재산의 귀속.", ""], ["참고 자료", "[5-2] 국가법령정보센터, 「공인중개사법」 — 제2조·제9조·제18조의4·제25조·제26조·제30조: 자격과 등록, 보조원 고지, 확인·설명, 계약서 및 손해배상.", ""], ["참고 자료", "[5-3] 국가법령정보센터, 「주택공급에 관한 규칙」 제59조 — 주택공급계약 체결 관련 규정. 본문의 순서는 일반적인 선분양의 개념도.", ""], ["참고 자료", "[5-4] 하나은행, 「주택청약종합저축」 상품 안내 — 납입 범위, 국민주택 월 납입 인정액과 미성년 기간 인정 기준. 상품 가입 권유가 아닌 제도 설명에 사용.", ""], ["참고 자료", "[5-5] 국가법령정보센터, 「주택공급에 관한 규칙」 별표 1 — 가점제 세 항목의 상한 32·35·17점. 본문의 표는 구조 이해용이며 세부 계산표가 아님. 국민주택의 당첨자 선정 기준(납입 횟수·저축 총액)은 같은 규칙 제27조 참조.", ""], ["참고 자료", "[5-6] 국가법령정보센터, 「국토의 계획 및 이용에 관한 법률」 제36조 — 네 가지 큰 용도지역과 도시지역 안의 구분.", ""], ["참고 자료", "[5-7] 국가법령정보센터, 「도시 및 주거환경정비법」 — 제2조의 사업 정의와 제12조 재건축진단. 과거의 안전진단 명칭과 현행 절차를 구분.", ""], ["참고 자료", "[5-8] 국가법령정보센터, 「건축법」 제55조 — 건폐율. 용적률은 같은 법 제56조, 면적 산정과 제외는 건축법 시행령 제119조를 함께 참조. 본문의 블록은 단순화한 계산 예.", ""], ["참고 자료", "[5-9] 황병연·이태희, 「아파트 모델하우스에서 시대별 가상현실 활용 흐름에 관한 연구」(2019) — 1969년 한강맨션 견본주택의 역사. 건축 모형과 분양용 견본주택의 기원을 동일시하지 않음.", ""], ["참고 자료", "[5-10] Guinness World Records, 「Largest house」 — 안틸리아의 층수와 시설 소개. 본문은 변할 수 있는 최고 기록보다 공간의 특징에 초점.", ""], ["참고 자료", "[5-11] Centrala, 「Keret House」 프로젝트 설명(Architizer) — 내부 폭 72~122cm와 단기 체류·작업 용도. 건물 사이 전체 틈의 폭과 내부 폭은 다름.", ""], ["참고 자료", "[5-12] McBride Charles Ryan, 「Klein Bottle House」 — 설계자가 소개한 안뜰·계단과 수학·종이접기에서 얻은 설계 아이디어.", ""], ["참고 자료", "[5-13] 서울특별시 주택정책, 「단독주택 재건축 세입자 대책」 첫 적용 안내 — 2019년. 재개발은 토지보상법에 따라 세입자 보상 대책이 의무이고, 재건축은 법적 근거가 없어 시가 용적률 인센티브로 보상을 유도하는 구조.", ""], ["참고 자료", "[5-14] 한국경제, 재개발 세입자 손실보상 용적률 인센티브 보도 — 2026년 2월 24일 보도. 재개발 세입자 손실보상은 정비구역 지정 공람공고일 전부터 거주·영업한 경우에만 받을 수 있다는 현행 기준.", ""], ["참고 자료", "[5-15] 뉴스토마토, 「건폐율 낮을수록 가치 높아…건폐율 20% 미만 아파트 ‘눈길’」 — 2020년 9월 8일 보도. 서울 조례상 건폐율 한도(제2종 일반주거지역 60%, 제3종 50%)와 실제 아파트 단지의 건폐율(통상 20~30%, 최근 20% 이하).", ""], ["소제목", "제6장 출처", ""], ["참고 자료", "[6-1] 국가법령정보센터, 「국토의 계획 및 이용에 관한 법률」 제2조 — 도시·군기본계획과 도시·군관리계획의 정의. 계획 발표와 개별 사업 실행을 구별.", ""], ["참고 자료", "[6-2] Zillow, 「Can Living Near a Starbucks Boost Your Home Value?」 — 질로가 Forbes에 기고한 2015년 분석 소개. 1997~2014년 미국 비교 수치이며, 본문에서는 상관관계만으로 인과를 확정할 수 없음을 설명. 책: Spencer Rascoff·Stan Humphries, 『Zillow Talk』(2015).", ""], ["참고 자료", "[6-3] 유향, 『열녀전』 「추맹가모」 원문(Chinese Text Project) — 무덤·시장·학교 주변 거처의 옛이야기. 현대 학군의 투자 성과를 증명하는 자료로 사용하지 않음.", ""], ["참고 자료", "[6-4] 경남신문, 「부동산 신조어 ‘브역대신평초’ 아시나요」 — 2026년 1월 27일 보도. 브랜드·역세권·대단지·신축·평지·초품아 여섯 가지 조건의 뜻. 본문에서는 사람들이 따지는 기준의 예로만 쓰고 가격 상승의 근거로 쓰지 않음.", ""], ["소제목", "제7장 출처", ""], ["참고 자료", "[7-1] 찾기쉬운 생활법령정보, 「임대차 계약에 따른 권리와 의무 확인하기」 — 민법상 수선·반환·원상회복 의무의 기본 설명. 본문의 통상 마모와 못 두 개에 관한 내용은 주하의 가상 계약에서 명시적으로 합의한 조건.", ""], ["참고 자료", "[7-2] 정부24, 「전입신고」 민원 안내 — 방문·온라인 신청과 근무시간 기준 처리 안내. 온라인 접수와 처리 완료를 구별.", ""], ["참고 자료", "[7-3] 국가법령정보센터, 「주택임대차보호법」 제3조·제3조의2·제3조의6·제3조의7 — 대항력과 우선변제권, 확정일자, 임대인의 정보 제시 의무(확정일자 부여 현황과 납세증명서). 주택 임대차 신고에 따른 확정일자 간주는 부동산 거래신고 등에 관한 법률 제6조의5 참조.", ""], ["참고 자료", "[7-4] 한국주택금융공사, 「전세지킴보증」 — 반환보증의 목적과 심사·가입·이행 절차. HUG 안내 [3-8]도 대조. 주하의 한도와 일정은 특정 상품을 재현한 것이 아닌 가상 설정.", ""], ["참고 자료", "[7-5] UK Cohousing Network, 「About cohousing」 — 독립된 주거공간, 공동시설, 주민의 운영 참여.", ""], ["참고 자료", "[7-6] 한국건설기술연구원, 「국내 모듈러 공동주택 현황 및 향후 역할」 — 공장 제작과 현장 시공을 결합하는 방식 및 성능 확보의 과제.", ""], ["참고 자료", "[7-7] 미국 HUD, 「3D Concrete Printed Construction Systems Part 2」 — 2023년 연구 보고서, 2024년 공개. 벽체 프린팅과 창호·설비·지붕·기초의 연결 및 기술 적용 과제.", ""], ["참고 자료", "[7-8] 한국에너지공단, 「제로에너지건축물 인증제도」 — 에너지 성능과 인증 등급. 외부 에너지 사용이나 요금이 무조건 0이라는 뜻으로 설명하지 않음.", ""]]}], "fig": {"1-1": [101, 84], "1-2": [45, 40], "1-3": [101, 84], "1-4": [101, 74], "1-5": [101, 60], "2-1": [101, 110], "2-1R": [101, 101], "2-2": [101, 82], "2-3": [101, 64], "2-4": [101, 106], "2-5": [101, 50], "3-1": [101, 75], "3-2": [101, 48], "3-3": [101, 78], "3-4": [101, 80], "3-5": [101, 75], "3-6": [101, 81], "3-7": [101, 56], "4-1": [101, 156], "4-2": [101, 86], "4-3": [101, 79], "4-4": [101, 82], "5-1": [101, 77], "5-2": [101, 62], "5-3": [101, 64], "5-4": [101, 77], "5-5": [101, 98], "5-6": [101, 78], "5-7": [101, 49], "6-1": [101, 57], "6-2": [101, 64], "6-4": [101, 109], "6-5": [101, 61], "7-1": [101, 48], "7-2": [101, 86], "7-3": [101, 72], "7-4": [101, 98], "7-5": [101, 98], "7-6": [101, 56]}};
var MM = 72 / 25.4;
var FRAME_H = 214 - 19.5 - 31;      // 판면 높이(mm)
var FIG_MAX_H = FRAME_H - 15;       // 도판 자리 상자 최대 높이(mm): 판면 높이 − (자리 문단 한 줄 + 앞뒤 간격)
var log = [];          // 확인 필요
var report = [];       // 장별 시작 쪽 등
var started = false;

// ── 공통 도우미 ──────────────────────────────────────────
function say(msg) {
    // UXP 스크립트에는 alert가 없을 수 있다 → 인디자인 대화상자로 대신 띄운다
    if (typeof alert === "function") { try { alert(msg); return; } catch (e) {} }
    try { if (typeof console !== "undefined") console.log(msg); } catch (e) {}
    try {
        var d = APP.dialogs.add({ name: "조판 결과" });
        var col = d.dialogColumns.add();
        var lines = String(msg).split("\n");
        for (var i = 0; i < lines.length && i < 30; i++) col.staticTexts.add({ staticLabel: lines[i] || " " });
        d.show(); d.destroy();
    } catch (e) {}
}
function filePath(f) {
    // ExtendScript는 File 객체, UXP는 경로 문자열을 돌려준다
    if (f === null || f === undefined) return "";
    if (typeof f === "string") return f;
    return f.fsName || f.nativePath || String(f);
}
function withSource(srcFile, label, fn) {
    // 원본 파일을 받는 메서드: 받은 값 그대로 시도 → 실패하면 경로 문자열로 다시 시도
    try { fn(srcFile); return; } catch (e1) {
        var p = filePath(srcFile);
        if (p && p !== srcFile) { try { fn(p); return; } catch (e2) { log.push(label + ": " + e2); return; } }
        log.push(label + ": " + e1);
    }
}
function findStyle(doc, coll, name) { var s = doc[coll].itemByName(name); return s.isValid ? s : null; }
function setp(obj, k, v) {
    var who = "";
    try { who = obj.name; } catch (e) {}
    try { obj[k] = v; } catch (e) { log.push(who + "." + k + ": " + e); return; }
    // UXP에서는 잘못된 속성 이름이 오류 없이 무시될 수 있다 → 숫자·참거짓은 다시 읽어 확인
    if (typeof v === "number" || typeof v === "boolean") {
        var r; try { r = obj[k]; } catch (e) { r = undefined; }
        if (typeof v === "number" ? !(typeof r === "number" && Math.abs(r - v) < 0.01) : r !== v)
            log.push(who + "." + k + " 적용 안 됨(값 " + r + ")");
    }
}
function fontName(family, styles) {
    // 설치된 글꼴에서 '가족\t스타일' 이름을 찾는다. 스타일 이름 후보를 차례로 시도
    for (var i = 0; i < styles.length; i++) {
        var n = family + "\t" + styles[i];
        try { if (APP.fonts.itemByName(n).isValid) return n; } catch (e) {}
    }
    log.push("글꼴 없음: " + family + " " + styles.join("/") + " — 국부론 패키지의 Document fonts가 새 문서에는 적용되지 않았을 수 있음");
    return null;
}
function swatchOrMake(doc, names, cmyk) {
    for (var i = 0; i < names.length; i++) { var s = doc.swatches.itemByName(names[i]); if (s.isValid) return s; }
    try {
        var c = doc.colors.add({ name: names[0], model: E("ColorModel").PROCESS, space: E("ColorSpace").CMYK, colorValue: cmyk });
        log.push("견본 새로 만듦: " + names[0] + " (국부론에서 같은 이름을 못 찾음)");
        return c;
    } catch (e) { log.push("견본 만들기 실패: " + names[0] + ": " + e); return doc.swatches.itemByName("Black"); }
}
function isRightPage(page) {
    // 마주 보는 페이지, 1쪽 시작: documentOffset 짝수 = 오른쪽(홀수 쪽). 열거형 비교를 피한다(UXP 차이)
    return page.documentOffset % 2 === 0;
}

// ── 본 작업 ──────────────────────────────────────────────
function main() {
    started = true;
    if (APP.documents.length === 0) { say("《국부론 수업》 파일을 먼저 여세요."); return; }
    var src = APP.activeDocument;
    if (!src.saved) { say("열린 문서를 먼저 저장하세요(스타일을 파일에서 가져옵니다)."); return; }
    var srcFile = src.fullName;
    var srcMasterName = mainMasterName(src);
    var MU = E("MeasurementUnits");
    APP.scriptPreferences.measurementUnit = MU.POINTS;

    // 1) 새 문서: 판형 150×214, 여백 위19.5 아래31 안쪽27 바깥22, 1단, 도련 3 (국부론 IDML 값)
    var doc = APP.documents.add();
    var dp = doc.documentPreferences;
    dp.facingPages = true; dp.pageWidth = 150 * MM; dp.pageHeight = 214 * MM;
    dp.documentBleedTopOffset = 3 * MM; dp.documentBleedBottomOffset = 3 * MM;
    dp.documentBleedInsideOrLeftOffset = 3 * MM; dp.documentBleedOutsideOrRightOffset = 3 * MM;
    setMargins(doc.marginPreferences);
    var ms0 = doc.masterSpreads.item(0);
    for (var mi = 0; mi < ms0.pages.length; mi++) setMargins(ms0.pages.item(mi).marginPreferences);

    // 2) 국부론에서 스타일·견본·부모 페이지 가져오기
    var CR = E("GlobalClashResolutionStrategy").LOAD_ALL_WITH_OVERWRITE, IF = E("ImportFormat");
    withSource(srcFile, "견본", function (f) { doc.loadSwatches(f); });
    withSource(srcFile, "문자·문단 스타일", function (f) { doc.importStyles(IF.TEXT_STYLES_FORMAT, f, CR); });
    withSource(srcFile, "개체 스타일", function (f) { doc.importStyles(IF.OBJECT_STYLES_FORMAT, f, CR); });
    withSource(srcFile, "표 스타일", function (f) { doc.importStyles(IF.TABLE_AND_CELL_STYLES_FORMAT, f, CR); });
    withSource(srcFile, "부모 페이지", function (f) { doc.loadMasters(f, CR); });
    var master = pickMaster(doc, srcMasterName);

    // 3) 이 책용 스타일(제안) 만들기 — 국부론 스타일을 바탕으로
    makeStyles(doc);

    // 4) 장마다 흘리기
    var LO = E("LocationOptions");
    var first = true;
    for (var c = 0; c < DATA.book.length; c++) {
        var ch = DATA.book[c];
        var page;
        if (first) { page = doc.pages.item(0); first = false; } else { page = doc.pages.add(LO.AT_END); }
        var line = (ch.num ? ch.num + "장" : ch.key) + ": ";
        if (ch.num) {
            // 도비라 펼침면(짝수 쪽 + 홀수 쪽): 지금 쪽이 홀수(오른쪽)면 그 쪽을 빈 쪽으로 두고 다음 쪽부터
            if (isRightPage(page)) { page.appliedMaster = master; page = doc.pages.add(LO.AT_END); }
            page.appliedMaster = master;
            var right = doc.pages.add(LO.AT_END); right.appliedMaster = master;
            dobira(doc, right, ch);
            line += "도비라 " + page.name + "~" + right.name + "쪽, ";
            page = doc.pages.add(LO.AT_END);
        }
        page.appliedMaster = master;
        line += "본문 " + page.name + "쪽부터";
        var res = flow(doc, page, ch, master);
        line += " " + res.last + "쪽까지" + (res.overset ? " ※넘침 남음" : "");
        report.push(line);
    }
    APP.scriptPreferences.measurementUnit = MU.AUTO_VALUE;
    var summary = "조판 완료: 총 " + doc.pages.length + "쪽\n" + report.join("\n") +
        (log.length ? ("\n\n확인 필요 " + log.length + "건 (전체는 1쪽 왼쪽 대지의 '조판 기록')\n" + log.slice(0, 12).join("\n")) : "\n\n확인 필요 없음");
    writeLog(doc, summary + (log.length > 12 ? "\n" + log.slice(12).join("\n") : ""));
    say(summary);
}

function setMargins(mp) {
    // 마주 보는 페이지에서 left = 안쪽, right = 바깥
    mp.top = 19.5 * MM; mp.bottom = 31 * MM; mp.left = 27 * MM; mp.right = 22 * MM; mp.columnCount = 1;
}

function mainMasterName(src) {
    // 국부론 페이지에 가장 많이 적용된 부모 페이지 이름 = 본문용
    var count = {}, best = "", n = 0;
    try {
        var pages = src.pages;
        for (var i = 0; i < pages.length; i++) {
            var m = pages.item(i).appliedMaster;
            if (!m || !m.isValid) continue;
            var k = m.name; count[k] = (count[k] || 0) + 1;
            if (count[k] > n) { n = count[k]; best = k; }
        }
    } catch (e) { log.push("국부론 부모 페이지 집계: " + e); }
    return best;
}
function pickMaster(doc, name) {
    if (name) { var m = doc.masterSpreads.itemByName(name); if (m.isValid) { report.push("부모 페이지: " + name + " (국부론 본문에 가장 많이 쓰인 것)"); return m; } }
    var last = doc.masterSpreads.item(doc.masterSpreads.length - 1);
    log.push("본문 부모 페이지를 이름으로 못 찾아 마지막 부모 페이지(" + last.name + ")를 썼음");
    return last;
}

function frameBounds(page) {
    var b = page.bounds, top = 19.5 * MM, bot = 31 * MM, ins = 27 * MM, out = 22 * MM;
    var isRight = isRightPage(page);
    return [b[0] + top, b[1] + (isRight ? ins : out), b[2] - bot, b[3] - (isRight ? out : ins)];
}

function dobira(doc, page, ch) {
    var b = page.bounds, bl = 3 * MM;
    var r = page.rectangles.add({ geometricBounds: [b[0] - bl, b[1], b[2] + bl, b[3] + bl] });
    var k80 = doc.swatches.itemByName("C=0 M=0 Y=0 K=80");
    setp(r, "fillColor", k80.isValid ? k80 : doc.swatches.itemByName("Black"));
    var t = page.textFrames.add({ geometricBounds: [b[0] + 95 * MM, b[1] + 38.3 * MM, b[0] + 160 * MM, b[1] + 115 * MM] });
    t.contents = ch.num + "\r" + ch.title + "\r\r[도비라 자리 — 공통 일러스트: 시안/illust/도비라_공통_v1.png]";
    var ps = findStyle(doc, "paragraphStyles", "도비라 제목");
    if (ps) { var tp = t.parentStory.paragraphs; for (var i = 0; i < tp.length; i++) tp.item(i).appliedParagraphStyle = ps; }
}

function flow(doc, page, ch, master) {
    var LO = E("LocationOptions");
    var tf = page.textFrames.add({ geometricBounds: frameBounds(page) });
    var texts = [];
    for (var i = 0; i < ch.p.length; i++) texts.push(ch.p[i][1]);
    tf.contents = texts.join("\r");
    var story = tf.parentStory, paras = story.paragraphs;
    if (paras.length !== ch.p.length) log.push(ch.key + ": 문단 수 불일치(데이터 " + ch.p.length + ", 인디자인 " + paras.length + ")");
    var cache = {};
    for (var j = 0; j < ch.p.length && j < paras.length; j++) {
        var nm = ch.p[j][0];
        if (!(nm in cache)) { cache[nm] = findStyle(doc, "paragraphStyles", nm); if (!cache[nm]) log.push("스타일 없음: " + nm); }
        if (cache[nm]) paras.item(j).applyParagraphStyle(cache[nm], true);
    }
    // 도판 자리: 시안 크기의 회색 상자를 '줄 위' 고정 개체로 넣는다.
    // (인라인으로 넣으면 고정 행간 26pt 때문에 상자가 윗줄 글자를 덮는다)
    var AP = E("AnchorPosition"), HA = E("HorizontalAlignment");
    var gray = doc.swatches.itemByName("C=0 M=0 Y=0 K=20");
    if (!gray.isValid) gray = doc.swatches.itemByName("Paper");
    for (var k = ch.p.length - 1; k >= 0; k--) {
        var fid = ch.p[k][2];
        if (!fid || k >= paras.length) continue;
        var ids = (fid === "2-1") ? ["2-1R", "2-1"] : [fid];   // 뒤에서부터 넣으므로 결과 순서는 2-1, 2-1R
        for (var q = 0; q < ids.length; q++) {
            var sz = DATA.fig[ids[q]] || [101, 60], h = sz[1];
            if (h > FIG_MAX_H) { log.push("도" + ids[q] + ": 높이 " + h + "mm가 판면에 안 들어가 자리 상자를 " + FIG_MAX_H + "mm로 줄임(실제 도판은 한 면 전체로 따로 앉힐 것)"); h = FIG_MAX_H; }
            try {
                if (q > 0) paras.item(k).insertionPoints.item(0).contents = "\r";   // 2-1 펼침면: 상자마다 문단을 나눈다
                var box = paras.item(k).insertionPoints.item(0).textFrames.add();
                box.geometricBounds = [0, 0, h * MM, sz[0] * MM];
                var ao = box.anchoredObjectSettings;
                setp(ao, "anchoredPosition", AP.ABOVE_LINE);
                setp(ao, "horizontalAlignment", HA.CENTER_ALIGN);
                box.contents = "[도" + ids[q].replace("R", " 오른쪽") + "] " + sz[0] + "×" + sz[1] + "mm — 시안 PDF를 놓을 자리";
                box.fillColor = gray;
            } catch (e) { log.push("도판 자리 " + ids[q] + ": " + e); }
        }
    }
    // 넘친 글을 새 쪽으로 이어 흘리기. 새 틀에 글이 한 자도 안 들어가면(안 들어가는 개체) 멈춘다
    var last = tf, guard = 0, overset = false;
    while (last.overflows) {
        if (guard++ >= 400) { overset = true; log.push(ch.key + ": 400쪽을 넘겨 흘리기를 멈춤"); break; }
        var np = doc.pages.add(LO.AT_END);
        np.appliedMaster = master;
        var nf = np.textFrames.add({ geometricBounds: frameBounds(np) });
        last.nextTextFrame = nf;
        try { nf.recompose(); } catch (e) {}
        if (nf.characters.length === 0) {
            overset = true;
            log.push(ch.key + ": " + np.name + "쪽 틀에 글이 들어가지 않아 멈춤(판면보다 큰 개체 확인)");
            nf.remove(); np.remove(); break;
        }
        last = nf;
    }
    return { last: last.parentPage ? last.parentPage.name : page.name, overset: overset };
}

function makeStyles(doc) {
    var P = doc.paragraphStyles;
    function mk(name, base, props) {
        var s = P.itemByName(name);
        if (!s.isValid) s = P.add({ name: name });
        var b = P.itemByName(base);
        if (b.isValid) setp(s, "basedOn", b); else log.push("바탕 스타일 없음: " + base + " (" + name + ")");
        for (var i = 0; i < props.length; i++) {
            if (props[i][1] === null) continue;   // 글꼴을 못 찾은 경우
            setp(s, props[i][0], props[i][1]);
        }
        return s;
    }
    var SP = E("StartParagraph"), J = E("Justification");
    var yellow = swatchOrMake(doc, ["C=0 M=6 Y=68 K=0"], [0, 6, 68, 0]);
    var teal = swatchOrMake(doc, ["도해_청록 c80m30y40"], [80, 30, 40, 0]);
    var gothicBd = fontName("Sandoll 고딕Neo1", ["07 Bd", "Bd"]);
    var gothicLt = fontName("Sandoll 고딕Neo1", ["03 Lt", "Lt"]);
    var gyeokdong = fontName("Sandoll 격동굴림2", ["06 Hv", "Hv"]);
    // [제안] 절 제목: 국부론 '대제목'과 같은 서체·크기·색, 새 쪽 시작만 끔
    mk("절 제목", "대제목", [["startParagraph", SP.ANYWHERE], ["spaceBefore", 39], ["spaceAfter", 6.5], ["keepWithNext", 3]]);
    // [레퍼런스] 소제목 = 국부론 '큰 제목'
    mk("소제목", "큰 제목", [["spaceBefore", 13]]);
    // [제안] 셋째 단계 제목
    mk("소소제목", "본문", [["appliedFont", gothicBd], ["pointSize", 10.5], ["firstLineIndent", 0], ["spaceBefore", 6.5], ["keepWithNext", 2]]);
    mk("질문 제목", "소소제목", [["fillColor", teal]]);
    mk("목록", "본문", [["leftIndent", 4 * MM], ["firstLineIndent", -4 * MM]]);
    mk("번호 목록", "본문", [["leftIndent", 5 * MM], ["firstLineIndent", -5 * MM]]);
    // [제안] '잠깐!' 상자: 국부론 상자와 같은 연노랑(0/6/68/0)을 문단 음영으로.
    // 음영 폭은 단(판면 101mm)에 맞추고 좌우 오프셋 0, 글은 들여쓰기 3mm로 안쪽 여백을 만든다(음영이 판면 밖으로 나가지 않게)
    var shade = [["paragraphShadingOn", true], ["paragraphShadingColor", yellow], ["paragraphShadingTopOffset", 4 * MM],
                 ["paragraphShadingBottomOffset", 3 * MM], ["paragraphShadingLeftOffset", 0], ["paragraphShadingRightOffset", 0]];
    mk("잠깐 라벨", "만화 대사", [["justification", J.LEFT_ALIGN], ["pointSize", 13], ["firstLineIndent", 0], ["leftIndent", 3 * MM], ["rightIndent", 3 * MM], ["spaceBefore", 26], ["keepWithNext", 2]].concat(shade));
    mk("잠깐 본문", "본문", [["firstLineIndent", 0], ["leftIndent", 3 * MM], ["rightIndent", 3 * MM], ["spaceAfter", 26]].concat(shade));
    mk("도판 자리", "본문", [["firstLineIndent", 0], ["justification", J.CENTER_ALIGN], ["spaceBefore", 6.5], ["spaceAfter", 13]]);
    mk("참고 자료", "본문", [["appliedFont", gothicLt], ["pointSize", 8], ["leading", 12], ["firstLineIndent", -6 * MM], ["leftIndent", 6 * MM]]);
    mk("참고 자료 제목", "소소제목", [["spaceBefore", 13]]);
    var white = doc.swatches.itemByName("Paper");
    mk("도비라 제목", "대제목", [["appliedFont", gyeokdong], ["pointSize", 18], ["fillColor", white], ["justification", J.CENTER_ALIGN], ["startParagraph", SP.ANYWHERE]]);
}

function writeLog(doc, text) {
    try {
        var p = doc.pages.item(0), b = p.bounds;
        var t = p.textFrames.add({ geometricBounds: [b[0], b[1] - 130 * MM, b[2], b[1] - 10 * MM] });
        t.contents = text;
        t.name = "조판 기록";
        try { t.nonprinting = true; } catch (e) {}
    } catch (e) { log.push("조판 기록 글상자: " + e); }
}

// 실행: 되돌리기 한 번으로 전체를 취소할 수 있게 doScript로 감싼다. 안 되면 그냥 실행
(function () {
    try {
        var lang = ID ? E("ScriptLanguage").UXPSCRIPT : E("ScriptLanguage").JAVASCRIPT;
        APP.doScript(main, lang, [], E("UndoModes").ENTIRE_SCRIPT, "부동산교양수업 조판");
        if (!started) main();   // doScript가 함수를 실행하지 않은 경우
    } catch (e) {
        if (!started) main(); else say("실행 중 오류: " + e + "\n" + log.join("\n"));
    }
})();
